package main

import (
	"container/heap"
)

type Tuple1 struct {
	F0 int
	F1 int
	F2 int
	F3 int
}

type Tuple2 struct {
	F0 int
	F1 int
}

type item struct {
	d   int
	idx int
}

type pq []item

func (p pq) Len() int            { return len(p) }
func (p pq) Less(i, j int) bool  { return p[i].d < p[j].d }
func (p pq) Swap(i, j int)       { p[i], p[j] = p[j], p[i] }
func (p *pq) Push(x interface{}) { *p = append(*p, x.(item)) }
func (p *pq) Pop() interface{} {
	o := *p
	n := len(o)
	x := o[n-1]
	*p = o[:n-1]
	return x
}

func FastestDelivery(n int, roads []Tuple1, stations []int, capacity int, swap_time int, max_swaps int, s int, t int) *Tuple2 {
	if s == t {
		return &Tuple2{0, 0}
	}
	isSt := make([]bool, n)
	for _, x := range stations {
		if x >= 0 && x < n {
			isSt[x] = true
		}
	}
	adj := make([][]Tuple1, n)
	for _, r := range roads {
		adj[r.F0] = append(adj[r.F0], r)
	}
	C := capacity + 1
	K := max_swaps + 1
	total := n * C * K
	const INF = int(1) << 60
	dist := make([]int, total)
	for i := range dist {
		dist[i] = INF
	}
	enc := func(u, c, k int) int { return (u*C+c)*K + k }
	start := enc(s, capacity, 0)
	dist[start] = 0
	h := &pq{{0, start}}
	for h.Len() > 0 {
		it := heap.Pop(h).(item)
		if it.d > dist[it.idx] {
			continue
		}
		k := it.idx % K
		rest := it.idx / K
		c := rest % C
		u := rest / C
		d := it.d
		if isSt[u] && k < max_swaps {
			ni := enc(u, capacity, k+1)
			nd := d + swap_time
			if nd < dist[ni] {
				dist[ni] = nd
				heap.Push(h, item{nd, ni})
			}
		}
		for _, r := range adj[u] {
			if r.F3 > 0 && c < r.F3 {
				continue
			}
			nc := c - r.F3
			if nc > capacity {
				nc = capacity
			}
			if nc < 0 {
				continue
			}
			ni := enc(r.F1, nc, k)
			nd := d + r.F2
			if nd < dist[ni] {
				dist[ni] = nd
				heap.Push(h, item{nd, ni})
			}
		}
	}
	best := INF
	bk := 0
	for k := 0; k < K; k++ {
		for c := 0; c < C; c++ {
			d := dist[enc(t, c, k)]
			if d < best || (d == best && k < bk) {
				best = d
				bk = k
			}
		}
	}
	if best >= INF {
		return nil
	}
	return &Tuple2{best, bk}
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1, long f2, long f3) {}

    public record Tuple2(long f0, long f1) {}

    public static Tuple2 fastestDelivery(long n, List<Tuple1> roads, List<Long> stations, long capacity, long swap_time, long max_swaps, long s, long t) {
        int N = (int) n;
        int C = (int) capacity;
        int K = (int) max_swaps;
        boolean[] station = new boolean[N];
        for (Long x : stations) station[(int) (long) x] = true;
        List<List<Tuple1>> adj = new ArrayList<>();
        for (int i = 0; i < N; i++) adj.add(new ArrayList<>());
        for (Tuple1 r : roads) adj.get((int) r.f0()).add(r);
        int total = N * (C + 1) * (K + 1);
        long[] dist = new long[total];
        Arrays.fill(dist, Long.MAX_VALUE);
        int start = (((int) s) * (C + 1) + C) * (K + 1);
        dist[start] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        pq.add(new long[]{0, start});
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            int st = (int) cur[1];
            if (cur[0] > dist[st]) continue;
            int k = st % (K + 1);
            int rest = st / (K + 1);
            int c = rest % (C + 1);
            int node = rest / (C + 1);
            if (station[node] && k < K) {
                int ns = (node * (C + 1) + C) * (K + 1) + k + 1;
                long nd = cur[0] + swap_time;
                if (nd < dist[ns]) {
                    dist[ns] = nd;
                    pq.add(new long[]{nd, ns});
                }
            }
            for (Tuple1 r : adj.get(node)) {
                long e = r.f3();
                if (e > 0 && c < e) continue;
                long nc = Math.min((long) C, c - e);
                if (nc < 0) continue;
                int ns = (((int) r.f1()) * (C + 1) + (int) nc) * (K + 1) + k;
                long nd = cur[0] + r.f2();
                if (nd < dist[ns]) {
                    dist[ns] = nd;
                    pq.add(new long[]{nd, ns});
                }
            }
        }
        long best = Long.MAX_VALUE;
        long bestK = 0;
        for (int c = 0; c <= C; c++) {
            for (int k = 0; k <= K; k++) {
                long d = dist[(((int) t) * (C + 1) + c) * (K + 1) + k];
                if (d == Long.MAX_VALUE) continue;
                if (d < best || (d == best && k < bestK)) {
                    best = d;
                    bestK = k;
                }
            }
        }
        if (best == Long.MAX_VALUE) return null;
        return new Tuple2(best, bestK);
    }
}

