std::optional<std::tuple<long long, long long>> fastest_delivery(long long n, const std::vector<std::tuple<long long, long long, long long, long long>>& roads, const std::vector<long long>& stations, long long capacity, long long swap_time, long long max_swaps, long long s, long long t) {
    const long long INF = std::numeric_limits<long long>::max();
    int C = (int)capacity + 1;
    int K = (int)max_swaps + 1;
    std::vector<char> isStation(n, 0);
    for (long long x : stations) if (x >= 0 && x < n) isStation[x] = 1;
    std::vector<std::vector<std::tuple<int,long long,long long>>> adj(n);
    for (auto &r : roads) {
        auto [u, v, m, e] = r;
        adj[u].push_back({(int)v, m, e});
    }
    auto id = [&](int v, int c, int k) { return ((long long)v * C + c) * K + k; };
    std::vector<long long> dist((size_t)n * C * K, INF);
    typedef std::pair<long long, long long> P;
    std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
    long long st = id((int)s, (int)capacity, 0);
    dist[st] = 0;
    pq.push({0, st});
    while (!pq.empty()) {
        auto [d, x] = pq.top();
        pq.pop();
        if (d > dist[x]) continue;
        int k = (int)(x % K);
        long long r = x / K;
        int c = (int)(r % C);
        int v = (int)(r / C);
        if (isStation[v] && k < max_swaps) {
            long long y = id(v, (int)capacity, k + 1);
            long long nd = d + swap_time;
            if (nd < dist[y]) {
                dist[y] = nd;
                pq.push({nd, y});
            }
        }
        for (auto &[w, m, e] : adj[v]) {
            if (e > 0 && c < e) continue;
            long long nc = std::min<long long>(capacity, c - e);
            if (nc < 0) continue;
            long long y = id(w, (int)nc, k);
            long long nd = d + m;
            if (nd < dist[y]) {
                dist[y] = nd;
                pq.push({nd, y});
            }
        }
    }
    bool found = false;
    long long bm = 0, bk = 0;
    for (int c = 0; c < C; c++) {
        for (int k = 0; k < K; k++) {
            long long d = dist[id((int)t, c, k)];
            if (d == INF) continue;
            if (!found || d < bm || (d == bm && k < bk)) {
                found = true;
                bm = d;
                bk = k;
            }
        }
    }
    if (!found) return std::nullopt;
    return std::make_tuple(bm, bk);
}

export function fastestDelivery(n: number, roads: [number, number, number, number][], stations: number[], capacity: number, swap_time: number, max_swaps: number, s: number, t: number): [number, number] | null {
  if (s === t) return [0, 0];
  const C = capacity + 1;
  const K = max_swaps + 1;
  const isStation = new Array<boolean>(n).fill(false);
  for (const x of stations) if (x >= 0 && x < n) isStation[x] = true;
  const adj: [number, number, number][][] = [];
  for (let i = 0; i < n; i++) adj.push([]);
  for (const [u, v, m, e] of roads) adj[u].push([v, m, e]);

  const total = n * C * K;
  const dist = new Array<number>(total).fill(Infinity);
  // heap
  const hd: number[] = [];
  const hs: number[] = [];
  const push = (d: number, st: number) => {
    let i = hd.length;
    hd.push(d);
    hs.push(st);
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (hd[p] <= d) break;
      hd[i] = hd[p];
      hs[i] = hs[p];
      i = p;
    }
    hd[i] = d;
    hs[i] = st;
  };
  const pop = (): [number, number] => {
    const rd = hd[0], rs = hs[0];
    const ld = hd.pop()!;
    const ls = hs.pop()!;
    const len = hd.length;
    if (len > 0) {
      let i = 0;
      while (true) {
        let c = 2 * i + 1;
        if (c >= len) break;
        if (c + 1 < len && hd[c + 1] < hd[c]) c++;
        if (hd[c] >= ld) break;
        hd[i] = hd[c];
        hs[i] = hs[c];
        i = c;
      }
      hd[i] = ld;
      hs[i] = ls;
    }
    return [rd, rs];
  };

  const idx = (v: number, c: number, k: number) => (v * C + c) * K + k;
  const start = idx(s, capacity, 0);
  dist[start] = 0;
  push(0, start);
  while (hd.length > 0) {
    const [d, st] = pop();
    if (d > dist[st]) continue;
    const k = st % K;
    const rest = (st - k) / K;
    const c = rest % C;
    const v = (rest - c) / C;
    for (const [w, m, e] of adj[v]) {
      if (e > 0 && c < e) continue;
      let nc = c - e;
      if (nc > capacity) nc = capacity;
      const ns = idx(w, nc, k);
      const nd = d + m;
      if (nd < dist[ns]) {
        dist[ns] = nd;
        push(nd, ns);
      }
    }
    if (isStation[v] && k < max_swaps) {
      const ns = idx(v, capacity, k + 1);
      const nd = d + swap_time;
      if (nd < dist[ns]) {
        dist[ns] = nd;
        push(nd, ns);
      }
    }
  }
  let best: [number, number] | null = null;
  for (let c = 0; c < C; c++) {
    for (let k = 0; k < K; k++) {
      const d = dist[idx(t, c, k)];
      if (d === Infinity) continue;
      if (best === null || d < best[0] || (d === best[0] && k < best[1])) best = [d, k];
    }
  }
  return best;
}

