import "errors"

type Tuple1 struct {
	F0 int
	F1 int
	F2 bool
}

func BestContext(messages []Tuple1, budget int, max_gap int, bonus int) (*int, error) {
	if budget < 0 || max_gap < 0 {
		return nil, errors.New("invalid")
	}
	const NEG = int(-1) << 60
	W := budget + 1
	G := max_gap + 1
	K := make([]int, W)
	D := make([][]int, W)
	for w := 0; w < W; w++ {
		K[w] = NEG
		D[w] = make([]int, G)
		for g := range D[w] {
			D[w][g] = NEG
		}
	}
	D[0][0] = 0
	for _, m := range messages {
		l, v, p := m.F0, m.F1, m.F2
		nK := make([]int, W)
		nD := make([][]int, W)
		for w := 0; w < W; w++ {
			nK[w] = NEG
			nD[w] = make([]int, G)
			for g := range nD[w] {
				nD[w][g] = NEG
			}
		}
		for w := 0; w < W; w++ {
			// keep
			if w+l <= budget {
				nw := w + l
				if K[w] > NEG {
					c := K[w] + v + bonus
					if c > nK[nw] {
						nK[nw] = c
					}
				}
				for g := 0; g < G; g++ {
					if D[w][g] > NEG {
						c := D[w][g] + v
						if c > nK[nw] {
							nK[nw] = c
						}
					}
				}
			}
			if !p {
				if K[w] > NEG && 1 <= max_gap {
					if K[w] > nD[w][1] {
						nD[w][1] = K[w]
					}
				}
				for g := 0; g < G; g++ {
					if D[w][g] > NEG && g+1 <= max_gap {
						if D[w][g] > nD[w][g+1] {
							nD[w][g+1] = D[w][g]
						}
					}
				}
			}
		}
		K, D = nK, nD
	}
	best := NEG
	for w := 0; w < W; w++ {
		if K[w] > best {
			best = K[w]
		}
		for g := 0; g < G; g++ {
			if D[w][g] > best {
				best = D[w][g]
			}
		}
	}
	if best <= NEG {
		return nil, nil
	}
	r := best
	return &r, nil
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1, boolean f2) {}

    public static Long bestContext(List<Tuple1> messages, long budget, long max_gap, long bonus) {
        if (budget < 0 || max_gap < 0) throw new IllegalArgumentException();
        int n = messages.size();
        int B = (int) budget;
        final long NEG = Long.MIN_VALUE / 4;
        int[] pc = new int[n + 1];
        for (int i = 0; i < n; i++) pc[i + 1] = pc[i] + (messages.get(i).f2() ? 1 : 0);
        long best = NEG;
        if (n <= max_gap && pc[n] == 0) best = 0;
        long[][] dp = new long[n][B + 1];
        for (long[] r : dp) Arrays.fill(r, NEG);
        for (int i = 0; i < n; i++) {
            Tuple1 m = messages.get(i);
            if (m.f0() > B) continue;
            int len = (int) m.f0();
            long val = m.f1();
            if (i <= max_gap && pc[i] == 0) {
                if (dp[i][len] < val) dp[i][len] = val;
            }
            for (int j = i - 1; j >= 0; j--) {
                if (i - j - 1 > max_gap) break;
                if (pc[i] - pc[j + 1] != 0) continue;
                long add = val + (j == i - 1 ? bonus : 0);
                long[] pj = dp[j];
                long[] di = dp[i];
                for (int w = len; w <= B; w++) {
                    long p = pj[w - len];
                    if (p == NEG) continue;
                    long c = p + add;
                    if (c > di[w]) di[w] = c;
                }
            }
            if (n - 1 - i <= max_gap && pc[n] - pc[i + 1] == 0) {
                for (int w = 0; w <= B; w++) {
                    if (dp[i][w] != NEG && dp[i][w] > best) best = dp[i][w];
                }
            }
        }
        if (best == NEG) return null;
        return best;
    }
}

