std::optional<long long> best_context(const std::vector<std::tuple<long long, long long, bool>>& messages, long long budget, long long max_gap, long long bonus) {
    if (budget < 0 || max_gap < 0) throw std::invalid_argument("negative");
    int n = (int)messages.size();
    const long long NEG = LLONG_MIN / 4;
    std::vector<int> pc(n + 1, 0);
    for (int i = 0; i < n; i++) pc[i + 1] = pc[i] + (std::get<2>(messages[i]) ? 1 : 0);
    std::optional<long long> best;
    auto upd = [&](long long v) {
        if (!best || v > *best) best = v;
    };
    if (n <= max_gap && pc[n] == 0) upd(0);
    int B = (int)budget;
    std::vector<std::vector<long long>> dp(n, std::vector<long long>(B + 1, NEG));
    for (int i = 0; i < n; i++) {
        long long len = std::get<0>(messages[i]);
        long long val = std::get<1>(messages[i]);
        if (len > B) continue;
        int L = (int)len;
        if (i <= max_gap && pc[i] == 0) {
            dp[i][L] = std::max(dp[i][L], val);
        }
        for (int j = i - 1; j >= 0; j--) {
            if (i - j - 1 > max_gap) break;
            if (pc[i] - pc[j + 1] != 0) break;
            long long add = val + (j == i - 1 ? bonus : 0);
            for (int w = 0; w + L <= B; w++) {
                if (dp[j][w] == NEG) continue;
                long long c = dp[j][w] + add;
                if (c > dp[i][w + L]) dp[i][w + L] = c;
            }
        }
        if (n - 1 - i <= max_gap && pc[n] - pc[i + 1] == 0) {
            for (int w = 0; w <= B; w++) {
                if (dp[i][w] != NEG) upd(dp[i][w]);
            }
        }
    }
    return best;
}

export function bestContext(messages: [number, number, boolean][], budget: number, max_gap: number, bonus: number): number | null {
  if (budget < 0 || max_gap < 0) throw new Error("invalid");
  const n = messages.length;
  const pre: number[] = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) pre[i + 1] = pre[i] + (messages[i][2] ? 1 : 0);
  let best = -Infinity;
  if (n <= max_gap && pre[n] === 0) best = 0;
  if (n === 0) return best === -Infinity ? null : best;
  const W = budget + 1;
  const dp: Float64Array[] = [];
  for (let i = 0; i < n; i++) dp.push(new Float64Array(W).fill(-Infinity));
  for (let i = 0; i < n; i++) {
    const len = messages[i][0];
    const val = messages[i][1];
    if (len > budget) continue;
    const row = dp[i];
    if (i <= max_gap && pre[i] === 0) {
      if (val > row[len]) row[len] = val;
    }
    const jmin = Math.max(0, i - 1 - max_gap);
    for (let j = i - 1; j >= jmin; j--) {
      // pinned strictly between j and i
      if (pre[i] - pre[j + 1] > 0) break;
      const add = val + (j === i - 1 ? bonus : 0);
      const pr = dp[j];
      for (let w = 0; w + len <= budget; w++) {
        const p = pr[w];
        if (p === -Infinity) continue;
        const c = p + add;
        if (c > row[w + len]) row[w + len] = c;
      }
    }
    if (n - 1 - i <= max_gap && pre[n] - pre[i + 1] === 0) {
      for (let w = 0; w <= budget; w++) {
        if (row[w] > best) best = row[w];
      }
    }
  }
  return best === -Infinity ? null : best;
}

