func MinPruningCost(parent []int, demand []int, cap []int, cut_cost []int, critical []bool, root_cap int, penalty int) *int {
	n := len(parent)
	const INF = int(1) << 60
	children := make([][]int, n)
	for v := 1; v < n; v++ {
		children[parent[v]] = append(children[parent[v]], v)
	}
	order := []int{0}
	for i := 0; i < len(order); i++ {
		order = append(order, children[order[i]]...)
	}
	sub := make([]int, n)
	hasCrit := make([]bool, n)
	dp := make([][]int, n)
	for i := n - 1; i >= 0; i-- {
		v := order[i]
		sub[v] = demand[v]
		hasCrit[v] = critical[v]
		cur := make([]int, demand[v]+1)
		for j := range cur {
			cur[j] = INF
		}
		cur[demand[v]] = 0
		for _, c := range children[v] {
			sub[v] += sub[c]
			if hasCrit[c] {
				hasCrit[v] = true
			}
			nw := make([]int, len(cur)+sub[c])
			for j := range nw {
				nw[j] = INF
			}
			cc := cut_cost[c] + penalty*sub[c]
			dc := dp[c]
			for l := 0; l < len(cur); l++ {
				if cur[l] >= INF {
					continue
				}
				if !hasCrit[c] {
					if cur[l]+cc < nw[l] {
						nw[l] = cur[l] + cc
					}
				}
				for lp := 0; lp < len(dc) && lp <= cap[c]; lp++ {
					if dc[lp] >= INF {
						continue
					}
					x := cur[l] + dc[lp]
					if x < nw[l+lp] {
						nw[l+lp] = x
					}
				}
			}
			cur = nw
			dp[c] = nil
		}
		dp[v] = cur
	}
	best := INF
	for l := 0; l < len(dp[0]) && l <= root_cap; l++ {
		if dp[0][l] < best {
			best = dp[0][l]
		}
	}
	if best >= INF {
		return nil
	}
	return &best
}

import java.util.*;

public final class Solution {
    public static Long minPruningCost(List<Long> parent, List<Long> demand, List<Long> cap, List<Long> cut_cost, List<Boolean> critical, long root_cap, long penalty) {
        int n = parent.size();
        final long INF = Long.MAX_VALUE / 4;
        List<List<Integer>> ch = new ArrayList<>();
        for (int i = 0; i < n; i++) ch.add(new ArrayList<>());
        for (int v = 1; v < n; v++) ch.get((int) (long) parent.get(v)).add(v);
        int[] order = new int[n];
        int head = 0, tail = 0;
        order[tail++] = 0;
        while (head < tail) {
            int v = order[head++];
            for (int c : ch.get(v)) order[tail++] = c;
        }
        long[][] dp = new long[n][];
        int[] sub = new int[n];
        boolean[] hasCrit = new boolean[n];
        for (int idx = n - 1; idx >= 0; idx--) {
            int v = order[idx];
            int d = (int) (long) demand.get(v);
            long[] cur = new long[d + 1];
            Arrays.fill(cur, INF);
            cur[d] = 0;
            int curMax = d;
            boolean hc = critical.get(v);
            for (int c : ch.get(v)) {
                long[] dc = dp[c];
                int cm = sub[c];
                long cutCost = INF;
                if (!hasCrit[c]) {
                    cutCost = cut_cost.get(c) + penalty * (long) sub[c];
                }
                long capc = cap.get(c);
                long[] nw = new long[curMax + cm + 1];
                Arrays.fill(nw, INF);
                for (int j = 0; j <= curMax; j++) {
                    if (cur[j] >= INF) continue;
                    if (cutCost < INF) {
                        long val = cur[j] + cutCost;
                        if (val < nw[j]) nw[j] = val;
                    }
                    for (int k = 0; k <= cm; k++) {
                        if (k > capc) break;
                        if (dc[k] >= INF) continue;
                        long val = cur[j] + dc[k];
                        if (val < nw[j + k]) nw[j + k] = val;
                    }
                }
                cur = nw;
                curMax += cm;
                hc = hc || hasCrit[c];
                dp[c] = null;
            }
            dp[v] = cur;
            sub[v] = curMax;
            hasCrit[v] = hc;
        }
        long best = INF;
        long[] r = dp[0];
        for (int j = 0; j < r.length; j++) {
            if (j <= root_cap && r[j] < best) best = r[j];
        }
        return best >= INF ? null : Long.valueOf(best);
    }
}

#include <vector>
#include <optional>
#include <algorithm>
#include <climits>

std::optional<long long> min_pruning_cost(const std::vector<long long>& parent, const std::vector<long long>& demand, const std::vector<long long>& cap, const std::vector<long long>& cut_cost, const std::vector<bool>& critical, long long root_cap, long long penalty) {
    const long long INF = LLONG_MAX / 4;
    int n = parent.size();
    std::vector<std::vector<int>> ch(n);
    for (int v = 1; v < n; v++) ch[parent[v]].push_back(v);
    std::vector<int> order;
    order.push_back(0);
    for (size_t i = 0; i < order.size(); i++) {
        for (int c : ch[order[i]]) order.push_back(c);
    }
    std::vector<std::vector<long long>> dp(n);
    std::vector<long long> S(n, 0);
    std::vector<char> hc(n, 0);
    for (int idx = n - 1; idx >= 0; idx--) {
        int v = order[idx];
        S[v] = demand[v];
        hc[v] = critical[v] ? 1 : 0;
        std::vector<long long> cur(demand[v] + 1, INF);
        cur[demand[v]] = 0;
        for (int c : ch[v]) {
            std::vector<long long> opt(S[c] + 1, INF);
            for (long long l = 0; l <= S[c]; l++) {
                if (l <= cap[c]) opt[l] = dp[c][l];
            }
            if (!hc[c]) {
                long long cc = cut_cost[c] + penalty * S[c];
                opt[0] = std::min(opt[0], cc);
            }
            std::vector<long long> nw(cur.size() + S[c], INF);
            for (size_t a = 0; a < cur.size(); a++) {
                if (cur[a] >= INF) continue;
                for (size_t b = 0; b < opt.size(); b++) {
                    if (opt[b] >= INF) continue;
                    long long val = cur[a] + opt[b];
                    if (val < nw[a + b]) nw[a + b] = val;
                }
            }
            cur.swap(nw);
            S[v] += S[c];
            if (hc[c]) hc[v] = 1;
            std::vector<long long>().swap(dp[c]);
        }
        long long lim = (v == 0) ? root_cap : cap[v];
        for (long long L = 0; L < (long long)cur.size(); L++) {
            if (L > lim) cur[L] = INF;
        }
        dp[v] = std::move(cur);
    }
    long long best = INF;
    for (long long x : dp[0]) best = std::min(best, x);
    if (best >= INF) return std::nullopt;
    return best;
}

export function minPruningCost(parent: number[], demand: number[], cap: number[], cut_cost: number[], critical: boolean[], root_cap: number, penalty: number): number | null {
  const n = parent.length;
  const children: number[][] = Array.from({ length: n }, () => []);
  for (let v = 1; v < n; v++) children[parent[v]].push(v);
  const order: number[] = [0];
  for (let i = 0; i < order.length; i++) {
    for (const c of children[order[i]]) order.push(c);
  }
  const dp: number[][] = new Array(n);
  const tot: number[] = new Array(n).fill(0);
  const hasCrit: boolean[] = new Array(n).fill(false);
  for (let i = n - 1; i >= 0; i--) {
    const v = order[i];
    let cur: number[] = new Array(demand[v] + 1).fill(Infinity);
    cur[demand[v]] = 0;
    let total = demand[v];
    let crit = critical[v];
    for (const c of children[v]) {
      const g = dp[c];
      const canCut = !hasCrit[c];
      const cutC = cut_cost[c] + penalty * tot[c];
      const next: number[] = new Array(cur.length + g.length - 1).fill(Infinity);
      for (let l = 0; l < cur.length; l++) {
        const cv = cur[l];
        if (cv === Infinity) continue;
        if (canCut) {
          const x = cv + cutC;
          if (x < next[l]) next[l] = x;
        }
        for (let k = 0; k < g.length; k++) {
          const gv = g[k];
          if (gv === Infinity) continue;
          const x = cv + gv;
          if (x < next[l + k]) next[l + k] = x;
        }
      }
      cur = next;
      total += tot[c];
      if (hasCrit[c]) crit = true;
      dp[c] = [];
    }
    tot[v] = total;
    hasCrit[v] = crit;
    const lim = v === 0 ? root_cap : cap[v];
    for (let l = lim + 1; l < cur.length; l++) cur[l] = Infinity;
    dp[v] = cur;
  }
  let best = Infinity;
  for (const x of dp[0]) if (x < best) best = x;
  return best === Infinity ? null : best;
}

package main

import (
	"container/heap"
	"sort"
)

type Tuple1 struct {
	F0 int
	F1 int
	F2 int
	F3 int
	F4 int
}

type ev struct {
	r, x, b int
}

type evHeap []ev

func (h evHeap) Len() int            { return len(h) }
func (h evHeap) Less(i, j int) bool  { return h[i].r < h[j].r }
func (h evHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *evHeap) Push(x interface{}) { *h = append(*h, x.(ev)) }
func (h *evHeap) Pop() interface{} {
	old := *h
	n := len(old)
	v := old[n-1]
	*h = old[:n-1]
	return v
}

func EarliestArrival(connections []Tuple1, transfer []int, source int, target int, start_time int, max_boardings int) *int {
	if source == target {
		r := start_time
		return &r
	}
	const INF = int(1) << 60
	cs := make([]Tuple1, len(connections))
	copy(cs, connections)
	sort.Slice(cs, func(i, j int) bool { return cs[i].F3 < cs[j].F3 })
	tripIdx := map[int]int{}
	for _, c := range cs {
		if _, ok := tripIdx[c.F0]; !ok {
			tripIdx[c.F0] = len(tripIdx)
		}
	}
	tripBest := make([]int, len(tripIdx))
	for i := range tripBest {
		tripBest[i] = INF
	}
	best := make([]int, len(transfer))
	for i := range best {
		best[i] = INF
	}
	h := &evHeap{}
	heap.Push(h, ev{start_time, source, 0})
	ans := INF
	for _, c := range cs {
		d := c.F3
		for h.Len() > 0 && (*h)[0].r <= d {
			e := heap.Pop(h).(ev)
			if e.b < best[e.x] {
				best[e.x] = e.b
			}
		}
		t := tripIdx[c.F0]
		b := tripBest[t]
		if best[c.F1] < INF && best[c.F1]+1 < b {
			b = best[c.F1] + 1
		}
		if b >= INF || b > max_boardings {
			continue
		}
		tripBest[t] = b
		if c.F2 == target {
			if c.F4 < ans {
				ans = c.F4
			}
		}
		heap.Push(h, ev{c.F4 + transfer[c.F2], c.F2, b})
	}
	if ans >= INF {
		return nil
	}
	return &ans
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1, long f2, long f3, long f4) {}

    public static Long earliestArrival(List<Tuple1> connections, List<Long> transfer, long source, long target, long start_time, long max_boardings) {
        if (source == target) return start_time;
        if (max_boardings <= 0) return null;
        int m = connections.size();
        int n = transfer.size();
        Integer[] ord = new Integer[m];
        for (int i = 0; i < m; i++) ord[i] = i;
        Tuple1[] cs = connections.toArray(new Tuple1[0]);
        Arrays.sort(ord, (a, b) -> {
            int c = Long.compare(cs[a].f0(), cs[b].f0());
            if (c != 0) return c;
            return Long.compare(cs[a].f3(), cs[b].f3());
        });
        int[] from = new int[m], to = new int[m];
        long[] dep = new long[m], arr = new long[m];
        int[] tripEnd = new int[m]; // exclusive end of trip for connection g
        int[] tripId = new int[m];
        long[] tid = new long[m];
        for (int g = 0; g < m; g++) {
            Tuple1 t = cs[ord[g]];
            from[g] = (int) t.f1();
            to[g] = (int) t.f2();
            dep[g] = t.f3();
            arr[g] = t.f4();
            tid[g] = t.f0();
        }
        int tc = 0;
        int[] tripEndByTrip = new int[m + 1];
        {
            int g = 0;
            while (g < m) {
                int h = g;
                while (h < m && tid[h] == tid[g]) h++;
                for (int i = g; i < h; i++) tripId[i] = tc;
                tripEndByTrip[tc] = h;
                tc++;
                g = h;
            }
        }
        int[] minBoard = new int[tc];
        for (int i = 0; i < tc; i++) minBoard[i] = tripEndByTrip[i];
        // station lists sorted by dep
        int[] cnt = new int[n + 1];
        for (int g = 0; g < m; g++) cnt[from[g] + 1]++;
        for (int i = 0; i < n; i++) cnt[i + 1] += cnt[i];
        int[] fill = new int[n];
        int[] lst = new int[m];
        Integer[] byDep = new Integer[m];
        for (int i = 0; i < m; i++) byDep[i] = i;
        Arrays.sort(byDep, (a, b) -> Long.compare(dep[a], dep[b]));
        for (int k = 0; k < m; k++) {
            int g = byDep[k];
            int s = from[g];
            lst[cnt[s] + fill[s]++] = g;
        }
        int[] ptr = new int[n];
        for (int i = 0; i < n; i++) ptr[i] = cnt[i + 1] - cnt[i];
        long INF = Long.MAX_VALUE;
        long[] tau = new long[n];
        Arrays.fill(tau, INF);
        int src = (int) source, tgt = (int) target;
        tau[src] = start_time;
        int[] marked = new int[n];
        int mc = 0;
        marked[mc++] = src;
        boolean[] inNext = new boolean[n];
        int[] next = new int[n];
        long[] ready = new long[n];
        for (long round = 1; round <= max_boardings && mc > 0; round++) {
            for (int i = 0; i < mc; i++) {
                int x = marked[i];
                ready[i] = (x == src) ? start_time : tau[x] + transfer.get(x);
            }
            int nc = 0;
            for (int i = 0; i < mc; i++) {
                int x = marked[i];
                long r = ready[i];
                int base = cnt[x];
                int lo = 0, hi = ptr[x];
                // first pos in [0,ptr) with dep >= r
                while (lo < hi) {
                    int mid = (lo + hi) >>> 1;
                    if (dep[lst[base + mid]] >= r) hi = mid;
                    else lo = mid + 1;
                }
                int newPtr = lo;
                for (int p = newPtr; p < ptr[x]; p++) {
                    int g = lst[base + p];
                    int tr = tripId[g];
                    int mb = minBoard[tr];
                    if (g < mb) {
                        for (int q = g; q < mb; q++) {
                            int y = to[q];
                            if (arr[q] < tau[y]) {
                                tau[y] = arr[q];
                                if (!inNext[y]) {
                                    inNext[y] = true;
                                    next[nc++] = y;
                                }
                            }
                        }
                        minBoard[tr] = g;
                    }
                }
                ptr[x] = newPtr;
            }
            for (int i = 0; i < nc; i++) {
                marked[i] = next[i];
                inNext[next[i]] = false;
            }
            mc = nc;
        }
        return tau[tgt] == INF ? null : Long.valueOf(tau[tgt]);
    }
}

#include <vector>
#include <tuple>
#include <optional>
#include <algorithm>
#include <unordered_map>
#include <climits>

std::optional<long long> earliest_arrival(const std::vector<std::tuple<long long, long long, long long, long long, long long>>& connections, const std::vector<long long>& transfer, long long source, long long target, long long start_time, long long max_boardings) {
    if (source == target) return start_time;
    if (max_boardings <= 0) return std::nullopt;
    const long long INF = LLONG_MAX;
    int n = connections.size();
    int S = transfer.size();
    // trips
    std::unordered_map<long long, int> tid;
    tid.reserve(n * 2 + 1);
    std::vector<int> tripOf(n);
    int T = 0;
    for (int i = 0; i < n; i++) {
        long long id = std::get<0>(connections[i]);
        auto it = tid.find(id);
        if (it == tid.end()) {
            it = tid.emplace(id, T++).first;
        }
        tripOf[i] = it->second;
    }
    std::vector<std::vector<int>> chain(T);
    for (int i = 0; i < n; i++) chain[tripOf[i]].push_back(i);
    std::vector<int> pos(n);
    for (int t = 0; t < T; t++) {
        auto& ch = chain[t];
        std::sort(ch.begin(), ch.end(), [&](int a, int b) {
            return std::get<3>(connections[a]) < std::get<3>(connections[b]);
        });
        for (int k = 0; k < (int)ch.size(); k++) pos[ch[k]] = k;
    }
    std::vector<std::vector<std::pair<long long, int>>> byStation(S);
    for (int i = 0; i < n; i++) {
        long long f = std::get<1>(connections[i]);
        byStation[f].push_back({std::get<3>(connections[i]), i});
    }
    for (auto& v : byStation) std::sort(v.begin(), v.end());
    std::vector<long long> ready(S, INF), processed(S, INF);
    std::vector<int> start(T);
    for (int t = 0; t < T; t++) start[t] = chain[t].size();
    std::vector<int> newb(T, INT_MAX);
    std::vector<char> flag(S, 0);
    std::vector<int> marked, nextMarked;
    ready[source] = start_time;
    marked.push_back((int)source);
    flag[source] = 1;
    long long best = INF;
    long long rounds = 0;
    std::vector<int> touchedTrips;
    while (!marked.empty() && rounds < max_boardings) {
        rounds++;
        touchedTrips.clear();
        for (int x : marked) {
            flag[x] = 0;
            long long r = ready[x];
            long long old = processed[x];
            processed[x] = r;
            auto& v = byStation[x];
            auto it = std::lower_bound(v.begin(), v.end(), std::make_pair(r, INT_MIN));
            for (; it != v.end() && it->first < old; ++it) {
                int c = it->second;
                int t = tripOf[c];
                int p = pos[c];
                if (p < start[t] && p < newb[t]) {
                    if (newb[t] == INT_MAX) touchedTrips.push_back(t);
                    newb[t] = p;
                }
            }
        }
        marked.clear();
        nextMarked.clear();
        for (int t : touchedTrips) {
            int i = newb[t];
            newb[t] = INT_MAX;
            int s = start[t];
            start[t] = i;
            auto& ch = chain[t];
            for (int j = i; j < s; j++) {
                const auto& c = connections[ch[j]];
                long long to = std::get<2>(c);
                long long arr = std::get<4>(c);
                if (to == target) {
                    if (arr < best) best = arr;
                } else {
                    long long nr = arr + transfer[to];
                    if (nr < ready[to]) {
                        ready[to] = nr;
                        if (!flag[to]) {
                            flag[to] = 1;
                            nextMarked.push_back((int)to);
                        }
                    }
                }
            }
        }
        marked.swap(nextMarked);
    }
    if (best == INF) return std::nullopt;
    return best;
}

export function earliestArrival(connections: [number, number, number, number, number][], transfer: number[], source: number, target: number, start_time: number, max_boardings: number): number | null {
  if (source === target) return start_time;
  const n = connections.length;
  const S = transfer.length;
  if (n === 0 || max_boardings < 1) return null;

  // trip chains
  const next = new Int32Array(n).fill(-1);
  const tripMap = new Map<number, number[]>();
  for (let i = 0; i < n; i++) {
    const t = connections[i][0];
    let arr = tripMap.get(t);
    if (!arr) { arr = []; tripMap.set(t, arr); }
    arr.push(i);
  }
  for (const arr of tripMap.values()) {
    arr.sort((a, b) => connections[a][3] - connections[b][3]);
    for (let j = 0; j + 1 < arr.length; j++) next[arr[j]] = arr[j + 1];
  }

  // station departure lists
  const lists: number[][] = [];
  for (let s = 0; s < S; s++) lists.push([]);
  for (let i = 0; i < n; i++) lists[connections[i][1]].push(i);
  const deps: number[][] = [];
  for (let s = 0; s < S; s++) {
    lists[s].sort((a, b) => connections[a][3] - connections[b][3]);
    deps.push(lists[s].map((c) => connections[c][3]));
  }
  const lo = new Int32Array(S);
  for (let s = 0; s < S; s++) lo[s] = lists[s].length;

  const f = new Int32Array(n); // 0 = unlabeled

  const lowerBound = (a: number[], t: number): number => {
    let l = 0, h = a.length;
    while (l < h) {
      const m = (l + h) >> 1;
      if (a[m] < t) l = m + 1; else h = m;
    }
    return l;
  };

  // label from station x with ready time t, new level lvl, push into list
  const spread = (x: number, t: number, lvl: number, out: number[]) => {
    const idx = lowerBound(deps[x], t);
    const L = lists[x];
    const end = lo[x];
    for (let j = idx; j < end; j++) {
      const d = L[j];
      if (f[d] === 0) { f[d] = lvl; out.push(d); }
    }
    if (idx < end) lo[x] = idx;
  };

  let cur: number[] = [];
  spread(source, start_time, 1, cur);
  let level = 1;
  let best = Infinity;
  while (cur.length > 0 && level <= max_boardings) {
    // chain closure
    for (let i = 0; i < cur.length; i++) {
      const nx = next[cur[i]];
      if (nx >= 0 && f[nx] === 0) { f[nx] = level; cur.push(nx); }
    }
    const nxt: number[] = [];
    for (let i = 0; i < cur.length; i++) {
      const c = cur[i];
      const cn = connections[c];
      const x = cn[2];
      const arr = cn[4];
      if (x === target && arr < best) best = arr;
      spread(x, arr + transfer[x], level + 1, nxt);
    }
    cur = nxt;
    level++;
  }
  return best === Infinity ? null : best;
}

package main

import "errors"

type Tuple1 struct {
	F0 int
	F1 string
	F2 int
	F3 bool
}

type clientState struct {
	tokens   int
	last     int
	strikes  []int
	head     int
	banUntil int
}

func AdmitRequests(requests []Tuple1, config map[string]int) ([]string, error) {
	for i := 1; i < len(requests); i++ {
		if requests[i].F0 < requests[i-1].F0 {
			return nil, errors.New("times out of order")
		}
	}
	cp := config["cap"]
	period := config["period"]
	gcap := config["gcap"]
	gperiod := config["gperiod"]
	reserve := config["reserve"]
	strikesN := config["strikes"]
	window := config["window"]
	ban := config["ban"]

	g := gcap
	gLast := 0
	clients := make(map[string]*clientState)
	res := make([]string, 0, len(requests))

	for _, r := range requests {
		t, c, cost, vip := r.F0, r.F1, r.F2, r.F3
		// update global
		{
			d := t/gperiod - gLast/gperiod
			if d > 0 {
				g += d
				if g > gcap {
					g = gcap
				}
			}
			gLast = t
		}
		st, ok := clients[c]
		if !ok {
			st = &clientState{tokens: cp, last: t}
			clients[c] = st
		}
		if t < st.banUntil {
			res = append(res, "BANNED")
			continue
		}
		// update client bucket
		{
			d := t/period - st.last/period
			if d > 0 {
				st.tokens += d
				if st.tokens > cp {
					st.tokens = cp
				}
			}
			st.last = t
		}
		if st.tokens < cost {
			st.strikes = append(st.strikes, t)
			for st.head < len(st.strikes) && st.strikes[st.head] <= t-window {
				st.head++
			}
			if len(st.strikes)-st.head >= strikesN {
				st.strikes = nil
				st.head = 0
				st.banUntil = t + ban
				res = append(res, "BAN")
			} else {
				res = append(res, "DENY")
			}
			continue
		}
		okG := false
		if vip {
			okG = g >= cost
		} else {
			okG = g-cost >= reserve
		}
		if !okG {
			res = append(res, "BUSY")
			continue
		}
		st.tokens -= cost
		g -= cost
		res = append(res, "OK")
	}
	return res, nil
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, String f1, long f2, boolean f3) {}

    private static final class Client {
        long tokens;
        long lastT;
        long banUntil = Long.MIN_VALUE;
        ArrayDeque<Long> strikes = new ArrayDeque<>();
    }

    public static List<String> admitRequests(List<Tuple1> requests, Map<String, Long> config) {
        long cap = config.get("cap");
        long period = config.get("period");
        long gcap = config.get("gcap");
        long gperiod = config.get("gperiod");
        long reserve = config.get("reserve");
        long strikesNeeded = config.get("strikes");
        long window = config.get("window");
        long ban = config.get("ban");

        long prev = Long.MIN_VALUE;
        for (Tuple1 r : requests) {
            if (r.f0() < prev) throw new IllegalArgumentException("time decreased");
            prev = r.f0();
        }

        List<String> res = new ArrayList<>(requests.size());
        Map<String, Client> clients = new HashMap<>();
        long gTokens = gcap;
        long gLast = 0;

        for (Tuple1 r : requests) {
            long t = r.f0();
            String c = r.f1();
            long cost = r.f2();
            boolean vip = r.f3();

            Client cl = clients.get(c);
            if (cl == null) {
                cl = new Client();
                cl.tokens = cap;
                cl.lastT = t;
                clients.put(c, cl);
            } else {
                long k = t / period - cl.lastT / period;
                if (k > 0) cl.tokens = Math.min(cap, cl.tokens + k);
                cl.lastT = t;
            }
            long gk = t / gperiod - gLast / gperiod;
            if (gk > 0) gTokens = Math.min(gcap, gTokens + gk);
            gLast = t;

            if (t < cl.banUntil) {
                res.add("BANNED");
                continue;
            }
            if (cl.tokens < cost) {
                cl.strikes.addLast(t);
                while (!cl.strikes.isEmpty() && cl.strikes.peekFirst() <= t - window) {
                    cl.strikes.pollFirst();
                }
                if (cl.strikes.size() >= strikesNeeded) {
                    cl.strikes.clear();
                    cl.banUntil = t + ban;
                    res.add("BAN");
                } else {
                    res.add("DENY");
                }
                continue;
            }
            boolean ok = vip ? gTokens >= cost : gTokens - cost >= reserve;
            if (!ok) {
                res.add("BUSY");
                continue;
            }
            cl.tokens -= cost;
            gTokens -= cost;
            res.add("OK");
        }
        return res;
    }
}

#include <vector>
#include <string>
#include <tuple>
#include <map>
#include <unordered_map>
#include <deque>
#include <stdexcept>
#include <algorithm>

std::vector<std::string> admit_requests(const std::vector<std::tuple<long long, std::string, long long, bool>>& requests, const std::map<std::string, long long>& config) {
    // Validate time ordering before producing anything.
    for (size_t i = 1; i < requests.size(); ++i) {
        if (std::get<0>(requests[i]) < std::get<0>(requests[i - 1]))
            throw std::invalid_argument("times decreasing");
    }
    long long cap = config.at("cap");
    long long period = config.at("period");
    long long gcap = config.at("gcap");
    long long gperiod = config.at("gperiod");
    long long reserve = config.at("reserve");
    long long strikes = config.at("strikes");
    long long window = config.at("window");
    long long ban = config.at("ban");

    struct Client {
        long long tokens;
        long long last;
        long long banned_until;
        std::deque<long long> st;
    };
    std::unordered_map<std::string, Client> clients;
    long long gtokens = gcap;
    long long glast = 0;

    std::vector<std::string> res;
    res.reserve(requests.size());
    for (const auto& rq : requests) {
        long long t = std::get<0>(rq);
        const std::string& c = std::get<1>(rq);
        long long cost = std::get<2>(rq);
        bool vip = std::get<3>(rq);

        // global refill
        {
            long long cnt = t / gperiod - glast / gperiod;
            if (cnt > 0) gtokens = std::min(gcap, gtokens + cnt);
            glast = t;
        }
        auto it = clients.find(c);
        if (it == clients.end()) {
            Client cl;
            cl.tokens = cap;
            cl.last = t;
            cl.banned_until = 0;
            it = clients.emplace(c, std::move(cl)).first;
        }
        Client& cl = it->second;
        {
            long long cnt = t / period - cl.last / period;
            if (cnt > 0) cl.tokens = std::min(cap, cl.tokens + cnt);
            cl.last = t;
        }
        if (t < cl.banned_until) {
            res.push_back("BANNED");
            continue;
        }
        if (cl.tokens < cost) {
            cl.st.push_back(t);
            while (!cl.st.empty() && cl.st.front() <= t - window) cl.st.pop_front();
            if ((long long)cl.st.size() >= strikes) {
                cl.st.clear();
                cl.banned_until = t + ban;
                res.push_back("BAN");
            } else {
                res.push_back("DENY");
            }
            continue;
        }
        bool ok = vip ? (gtokens >= cost) : (gtokens - cost >= reserve);
        if (!ok) {
            res.push_back("BUSY");
            continue;
        }
        cl.tokens -= cost;
        gtokens -= cost;
        res.push_back("OK");
    }
    return res;
}

export function admitRequests(requests: [number, string, number, boolean][], config: Record<string, number>): string[] {
  const cap = config["cap"], period = config["period"];
  const gcap = config["gcap"], gperiod = config["gperiod"];
  const reserve = config["reserve"];
  const strikesNeeded = config["strikes"];
  const windowLen = config["window"];
  const banLen = config["ban"];

  for (let i = 1; i < requests.length; i++) {
    if (requests[i][0] < requests[i - 1][0]) {
      throw new Error("times not non-decreasing");
    }
  }

  interface St {
    tokens: number;
    last: number;
    strikes: number[];
    head: number;
    bannedUntil: number;
  }
  const clients = new Map<string, St>();
  let gTokens = gcap;
  let gLast = 0;
  const res: string[] = [];

  for (const [t, c, cost, vip] of requests) {
    let s = clients.get(c);
    if (!s) {
      s = { tokens: cap, last: Math.floor(t / period), strikes: [], head: 0, bannedUntil: -1 };
      clients.set(c, s);
    }
    // refill
    const cnt = Math.floor(t / period);
    if (cnt > s.last) {
      s.tokens = Math.min(cap, s.tokens + (cnt - s.last));
      s.last = cnt;
    }
    const gcnt = Math.floor(t / gperiod);
    if (gcnt > gLast) {
      gTokens = Math.min(gcap, gTokens + (gcnt - gLast));
      gLast = gcnt;
    }

    if (t < s.bannedUntil) {
      res.push("BANNED");
      continue;
    }
    if (s.tokens < cost) {
      while (s.head < s.strikes.length && s.strikes[s.head] <= t - windowLen) s.head++;
      s.strikes.push(t);
      if (s.strikes.length - s.head >= strikesNeeded) {
        s.strikes = [];
        s.head = 0;
        s.bannedUntil = t + banLen;
        res.push("BAN");
      } else {
        res.push("DENY");
      }
      continue;
    }
    const ok = vip ? gTokens >= cost : gTokens - cost >= reserve;
    if (!ok) {
      res.push("BUSY");
      continue;
    }
    s.tokens -= cost;
    gTokens -= cost;
    res.push("OK");
  }
  return res;
}

package main

import (
	"fmt"
	"strings"
	"unicode"
)

type Tuple1 struct {
	F0 string
	F1 []string
	F2 string
	F3 string
}

func pyRepr(s string) string {
	quote := '\''
	if strings.ContainsRune(s, '\'') && !strings.ContainsRune(s, '"') {
		quote = '"'
	}
	var b strings.Builder
	b.WriteRune(quote)
	for _, r := range s {
		switch {
		case r == quote || r == '\\':
			b.WriteRune('\\')
			b.WriteRune(r)
		case r == '\n':
			b.WriteString("\\n")
		case r == '\r':
			b.WriteString("\\r")
		case r == '\t':
			b.WriteString("\\t")
		case r == ' ':
			b.WriteRune(r)
		case r < 0x80 && (r < 0x20 || r == 0x7f):
			b.WriteString(fmt.Sprintf("\\x%02x", r))
		case unicode.IsPrint(r):
			b.WriteRune(r)
		case r < 0x100:
			b.WriteString(fmt.Sprintf("\\x%02x", r))
		case r < 0x10000:
			b.WriteString(fmt.Sprintf("\\u%04x", r))
		default:
			b.WriteString(fmt.Sprintf("\\U%08x", r))
		}
	}
	b.WriteRune(quote)
	return b.String()
}

func isName(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_') {
			return false
		}
	}
	return true
}

func isWord(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z') {
			return false
		}
	}
	return true
}

func isSeg(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '.' || c == '_' || c == '-') {
			return false
		}
	}
	return true
}

type rule struct {
	deny   bool
	ptype  int // 0 any, 1 group, 2 user
	pname  string
	anyAct bool
	acts   map[string]bool
	segs   []string
	L      int
}

func parsePath(p string, wild bool) ([]string, bool) {
	if len(p) == 0 || p[0] != '/' {
		return nil, false
	}
	if p == "/" {
		return []string{}, true
	}
	parts := strings.Split(p[1:], "/")
	for _, s := range parts {
		if isSeg(s) {
			continue
		}
		if wild && (s == "*" || s == "**") {
			continue
		}
		return nil, false
	}
	return parts, true
}

func isPySpace(r rune) bool {
	return unicode.IsSpace(r) || (r >= 0x1c && r <= 0x1f)
}

func EvaluateAccess(rules []string, requests []Tuple1) ([]string, error) {
	rs := make([]rule, len(rules))
	for i, text := range rules {
		f := strings.FieldsFunc(text, isPySpace)
		if len(f) != 4 {
			return nil, fmt.Errorf("rule %d: expected 4 fields, got %d", i, len(f))
		}
		var r rule
		switch f[0] {
		case "ALLOW":
		case "DENY":
			r.deny = true
		default:
			return nil, fmt.Errorf("rule %d: bad effect %s", i, pyRepr(f[0]))
		}
		p := f[1]
		switch {
		case p == "*":
		case strings.HasPrefix(p, "user:") && isName(p[5:]):
			r.ptype = 2
			r.pname = p[5:]
		case strings.HasPrefix(p, "group:") && isName(p[6:]):
			r.ptype = 1
			r.pname = p[6:]
		default:
			return nil, fmt.Errorf("rule %d: bad principal %s", i, pyRepr(p))
		}
		a := f[2]
		if a == "*" {
			r.anyAct = true
		} else {
			r.acts = map[string]bool{}
			for _, w := range strings.Split(a, ",") {
				if !isWord(w) {
					return nil, fmt.Errorf("rule %d: bad action %s", i, pyRepr(a))
				}
				r.acts[w] = true
			}
		}
		segs, ok := parsePath(f[3], true)
		if !ok {
			return nil, fmt.Errorf("rule %d: bad resource %s", i, pyRepr(f[3]))
		}
		r.segs = segs
		for _, s := range segs {
			if s != "*" && s != "**" {
				r.L++
			}
		}
		rs[i] = r
	}
	paths := make([][]string, len(requests))
	for j, q := range requests {
		if !isName(q.F0) {
			return nil, fmt.Errorf("request %d: bad user %s", j, pyRepr(q.F0))
		}
		for _, g := range q.F1 {
			if !isName(g) {
				return nil, fmt.Errorf("request %d: bad groups", j)
			}
		}
		if !isWord(q.F2) {
			return nil, fmt.Errorf("request %d: bad action %s", j, pyRepr(q.F2))
		}
		ps, ok := parsePath(q.F3, false)
		if !ok {
			return nil, fmt.Errorf("request %d: bad path %s", j, pyRepr(q.F3))
		}
		paths[j] = ps
	}
	res := make([]string, len(requests))
	for j, q := range requests {
		path := paths[j]
		groups := map[string]bool{}
		for _, g := range q.F1 {
			groups[g] = true
		}
		best := -1
		firstIdx := -1
		denyIdx := -1
		for i := range rs {
			r := &rs[i]
			switch r.ptype {
			case 2:
				if r.pname != q.F0 {
					continue
				}
			case 1:
				if !groups[r.pname] {
					continue
				}
			}
			if !r.anyAct && !r.acts[q.F2] {
				continue
			}
			a := 0
			if !r.anyAct {
				a = 1
			}
			score := r.L*6 + r.ptype*2 + a
			if score < best {
				continue
			}
			if !matchPath(r.segs, path) {
				continue
			}
			if score > best {
				best = score
				firstIdx = i
				denyIdx = -1
			}
			if r.deny && denyIdx < 0 {
				denyIdx = i
			}
		}
		if best < 0 {
			res[j] = "DENY by default"
		} else if denyIdx >= 0 {
			res[j] = fmt.Sprintf("DENY by rule %d", denyIdx)
		} else {
			res[j] = fmt.Sprintf("ALLOW by rule %d", firstIdx)
		}
	}
	return res, nil
}

func matchPath(segs, path []string) bool {
	n := len(segs)
	cur := make([]bool, n+1)
	nxt := make([]bool, n+1)
	cur[0] = true
	closure := func(c []bool) {
		for k := 0; k < n; k++ {
			if c[k] && segs[k] == "**" {
				c[k+1] = true
			}
		}
	}
	closure(cur)
	for _, p := range path {
		for k := range nxt {
			nxt[k] = false
		}
		any := false
		for k := 0; k < n; k++ {
			if !cur[k] {
				continue
			}
			s := segs[k]
			if s == "**" {
				nxt[k] = true
				any = true
			} else if s == "*" || s == p {
				nxt[k+1] = true
				any = true
			}
		}
		if !any {
			return false
		}
		closure(nxt)
		cur, nxt = nxt, cur
	}
	return cur[n]
}

import java.util.*;

public final class Solution {
    public record Tuple1(String f0, List<String> f1, String f2, String f3) {}

    private static final class Rule {
        boolean allow;
        int ptype; // 0 any, 1 group, 2 user
        String pname;
        Set<String> actions; // null = any
        String[] segs;
        int literalCount;
        int key;
    }

    private static boolean isWs(char c) {
        return (c >= 0x09 && c <= 0x0D) || (c >= 0x1C && c <= 0x20) || c == 0x85 || c == 0xA0
                || c == 0x1680 || (c >= 0x2000 && c <= 0x200A) || c == 0x2028 || c == 0x2029
                || c == 0x202F || c == 0x205F || c == 0x3000;
    }

    private static List<String> pySplit(String s) {
        List<String> res = new ArrayList<>();
        int n = s.length();
        int i = 0;
        while (i < n) {
            while (i < n && isWs(s.charAt(i))) i++;
            if (i >= n) break;
            int j = i;
            while (j < n && !isWs(s.charAt(j))) j++;
            res.add(s.substring(i, j));
            i = j;
        }
        return res;
    }

    private static boolean allIn(String s, int kind) {
        if (s.isEmpty()) return false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            boolean ok;
            if (kind == 0) ok = (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_';
            else if (kind == 1) ok = (c >= 'a' && c <= 'z');
            else ok = (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '.' || c == '_' || c == '-';
            if (!ok) return false;
        }
        return true;
    }

    private static String[] splitSegs(String path) {
        // path starts with "/" ; returns null if invalid structure
        if (path.equals("/")) return new String[0];
        String rest = path.substring(1);
        return rest.split("/", -1);
    }

    public static List<String> evaluateAccess(List<String> rules, List<Tuple1> requests) {
        if (rules == null) throw new IllegalArgumentException("rules must be a list");
        if (requests == null) throw new IllegalArgumentException("requests must be a list");
        List<Rule> parsed = new ArrayList<>();
        for (int i = 0; i < rules.size(); i++) {
            String r = rules.get(i);
            if (r == null) throw new IllegalArgumentException("rule " + i + ": not a str");
            List<String> f = pySplit(r);
            if (f.size() != 4) throw new IllegalArgumentException("rule " + i + ": expected 4 fields");
            Rule rule = new Rule();
            String eff = f.get(0);
            if (eff.equals("ALLOW")) rule.allow = true;
            else if (eff.equals("DENY")) rule.allow = false;
            else throw new IllegalArgumentException("rule " + i + ": bad effect");
            String pr = f.get(1);
            if (pr.equals("*")) {
                rule.ptype = 0;
            } else if (pr.startsWith("user:") && allIn(pr.substring(5), 0)) {
                rule.ptype = 2;
                rule.pname = pr.substring(5);
            } else if (pr.startsWith("group:") && allIn(pr.substring(6), 0)) {
                rule.ptype = 1;
                rule.pname = pr.substring(6);
            } else throw new IllegalArgumentException("rule " + i + ": bad principal");
            String ac = f.get(2);
            if (ac.equals("*")) {
                rule.actions = null;
            } else {
                String[] parts = ac.split(",", -1);
                Set<String> set = new HashSet<>();
                for (String p : parts) {
                    if (!allIn(p, 1)) throw new IllegalArgumentException("rule " + i + ": bad action");
                    set.add(p);
                }
                rule.actions = set;
            }
            String res = f.get(3);
            if (!res.startsWith("/")) throw new IllegalArgumentException("rule " + i + ": bad resource");
            String[] segs = splitSegs(res);
            int lit = 0;
            for (String s : segs) {
                if (s.equals("*") || s.equals("**")) continue;
                if (!allIn(s, 2)) throw new IllegalArgumentException("rule " + i + ": bad resource");
                lit++;
            }
            rule.segs = segs;
            rule.literalCount = lit;
            rule.key = lit * 6 + rule.ptype * 2 + (rule.actions != null ? 1 : 0);
            parsed.add(rule);
        }
        int m = requests.size();
        String[][] paths = new String[m][];
        for (int j = 0; j < m; j++) {
            Tuple1 t = requests.get(j);
            if (t == null) throw new IllegalArgumentException("request " + j + ": expected 4-tuple");
            if (t.f0() == null || !allIn(t.f0(), 0)) throw new IllegalArgumentException("request " + j + ": bad user");
            if (t.f1() == null) throw new IllegalArgumentException("request " + j + ": bad groups");
            for (String g : t.f1()) {
                if (g == null || !allIn(g, 0)) throw new IllegalArgumentException("request " + j + ": bad groups");
            }
            if (t.f2() == null || !allIn(t.f2(), 1)) throw new IllegalArgumentException("request " + j + ": bad action");
            String p = t.f3();
            if (p == null || !p.startsWith("/")) throw new IllegalArgumentException("request " + j + ": bad path");
            String[] segs = splitSegs(p);
            for (String s : segs) {
                if (!allIn(s, 2)) throw new IllegalArgumentException("request " + j + ": bad path");
            }
            paths[j] = segs;
        }
        List<String> out = new ArrayList<>(m);
        for (int j = 0; j < m; j++) {
            Tuple1 t = requests.get(j);
            Set<String> groups = new HashSet<>(t.f1());
            String[] path = paths[j];
            int n = path.length;
            boolean[] cur = new boolean[n + 1];
            boolean[] nxt = new boolean[n + 1];
            int bestKey = -1;
            int bestDeny = -1, bestAllow = -1;
            for (int i = 0; i < parsed.size(); i++) {
                Rule r = parsed.get(i);
                if (r.key < bestKey) continue;
                if (r.ptype == 2 && !r.pname.equals(t.f0())) continue;
                if (r.ptype == 1 && !groups.contains(r.pname)) continue;
                if (r.actions != null && !r.actions.contains(t.f2())) continue;
                if (r.literalCount + (r.segs.length - r.literalCount) * 0 > n) continue;
                // resource match
                Arrays.fill(cur, false);
                cur[0] = true;
                boolean any = true;
                for (String s : r.segs) {
                    Arrays.fill(nxt, false);
                    if (s.equals("**")) {
                        int first = -1;
                        for (int k = 0; k <= n; k++) if (cur[k]) { first = k; break; }
                        if (first >= 0) for (int k = first; k <= n; k++) nxt[k] = true;
                    } else if (s.equals("*")) {
                        for (int k = 0; k < n; k++) if (cur[k]) nxt[k + 1] = true;
                    } else {
                        for (int k = 0; k < n; k++) if (cur[k] && path[k].equals(s)) nxt[k + 1] = true;
                    }
                    boolean[] tmp = cur; cur = nxt; nxt = tmp;
                    any = false;
                    for (int k = 0; k <= n; k++) if (cur[k]) { any = true; break; }
                    if (!any) break;
                }
                if (!any || !cur[n]) continue;
                if (r.key > bestKey) {
                    bestKey = r.key;
                    bestDeny = -1;
                    bestAllow = -1;
                }
                if (r.allow) {
                    if (bestAllow < 0) bestAllow = i;
                } else {
                    if (bestDeny < 0) bestDeny = i;
                }
            }
            if (bestKey < 0) out.add("DENY by default");
            else if (bestDeny >= 0) out.add("DENY by rule " + bestDeny);
            else out.add("ALLOW by rule " + bestAllow);
        }
        return out;
    }
}

#include <vector>
#include <string>
#include <tuple>
#include <stdexcept>
#include <cstdint>
#include <algorithm>

namespace {

std::string pyrepr(const std::string& s) {
    char q = '\'';
    if (s.find('\'') != std::string::npos && s.find('"') == std::string::npos) q = '"';
    std::string r(1, q);
    const char* hex = "0123456789abcdef";
    for (unsigned char c : s) {
        if (c == (unsigned char)q || c == '\\') { r += '\\'; r += (char)c; }
        else if (c == '\n') r += "\\n";
        else if (c == '\r') r += "\\r";
        else if (c == '\t') r += "\\t";
        else if (c < 0x20 || c == 0x7f) { r += "\\x"; r += hex[c >> 4]; r += hex[c & 15]; }
        else r += (char)c;
    }
    r += q;
    return r;
}

size_t wsLen(const std::string& s, size_t i) {
    unsigned char c = s[i];
    if (c == ' ' || (c >= 9 && c <= 13) || (c >= 0x1c && c <= 0x1f)) return 1;
    size_t n = s.size();
    if (c == 0xC2 && i + 1 < n) {
        unsigned char d = s[i + 1];
        if (d == 0x85 || d == 0xA0) return 2;
    }
    if (c == 0xE1 && i + 2 < n && (unsigned char)s[i + 1] == 0x9A && (unsigned char)s[i + 2] == 0x80) return 3;
    if (c == 0xE2 && i + 2 < n) {
        unsigned char d = s[i + 1], e = s[i + 2];
        if (d == 0x80 && ((e >= 0x80 && e <= 0x8A) || e == 0xA8 || e == 0xA9 || e == 0xAF)) return 3;
        if (d == 0x81 && e == 0x9F) return 3;
    }
    if (c == 0xE3 && i + 2 < n && (unsigned char)s[i + 1] == 0x80 && (unsigned char)s[i + 2] == 0x80) return 3;
    return 0;
}

std::vector<std::string> pysplit(const std::string& s) {
    std::vector<std::string> out;
    size_t i = 0, n = s.size();
    std::string cur;
    bool in = false;
    while (i < n) {
        size_t w = wsLen(s, i);
        if (w) {
            if (in) { out.push_back(cur); cur.clear(); in = false; }
            i += w;
        } else {
            cur += s[i]; in = true; i++;
        }
    }
    if (in) out.push_back(cur);
    return out;
}

bool isName(const std::string& s) {
    if (s.empty()) return false;
    for (char c : s) if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_')) return false;
    return true;
}
bool isWord(const std::string& s) {
    if (s.empty()) return false;
    for (char c : s) if (!(c >= 'a' && c <= 'z')) return false;
    return true;
}
bool isSegChars(const std::string& s) {
    if (s.empty()) return false;
    for (char c : s)
        if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '.' || c == '_' || c == '-')) return false;
    return true;
}

bool splitPath(const std::string& p, std::vector<std::string>& segs, bool wild) {
    segs.clear();
    if (p.empty() || p[0] != '/') return false;
    if (p.size() == 1) return true;
    size_t i = 1;
    while (true) {
        size_t j = p.find('/', i);
        std::string seg = p.substr(i, j == std::string::npos ? std::string::npos : j - i);
        if (!(isSegChars(seg) || (wild && (seg == "*" || seg == "**")))) return false;
        segs.push_back(seg);
        if (j == std::string::npos) break;
        i = j + 1;
    }
    return true;
}

struct Rule {
    bool deny;
    int P; // 0,1,2
    std::string name;
    bool anyAction;
    std::vector<std::string> actions;
    std::vector<std::string> segs;
    int L;
};

}

std::vector<std::string> evaluate_access(const std::vector<std::string>& rules, const std::vector<std::tuple<std::string, std::vector<std::string>, std::string, std::string>>& requests) {
    std::vector<Rule> rs;
    for (size_t i = 0; i < rules.size(); i++) {
        std::string pre = "rule " + std::to_string(i) + ": ";
        auto f = pysplit(rules[i]);
        if (f.size() != 4)
            throw std::invalid_argument(pre + "expected 4 fields, got " + std::to_string(f.size()));
        Rule r;
        if (f[0] == "ALLOW") r.deny = false;
        else if (f[0] == "DENY") r.deny = true;
        else throw std::invalid_argument(pre + "bad effect " + pyrepr(f[0]));
        const std::string& pr = f[1];
        if (pr == "*") { r.P = 0; }
        else if (pr.compare(0, 5, "user:") == 0 && isName(pr.substr(5))) { r.P = 2; r.name = pr.substr(5); }
        else if (pr.compare(0, 6, "group:") == 0 && isName(pr.substr(6))) { r.P = 1; r.name = pr.substr(6); }
        else throw std::invalid_argument(pre + "bad principal " + pyrepr(pr));
        const std::string& ac = f[2];
        if (ac == "*") r.anyAction = true;
        else {
            r.anyAction = false;
            bool ok = true;
            size_t st = 0;
            while (true) {
                size_t j = ac.find(',', st);
                std::string w = ac.substr(st, j == std::string::npos ? std::string::npos : j - st);
                if (!isWord(w)) { ok = false; break; }
                r.actions.push_back(w);
                if (j == std::string::npos) break;
                st = j + 1;
            }
            if (!ok) throw std::invalid_argument(pre + "bad action " + pyrepr(ac));
        }
        if (!splitPath(f[3], r.segs, true))
            throw std::invalid_argument(pre + "bad resource " + pyrepr(f[3]));
        r.L = 0;
        for (auto& s : r.segs) if (s != "*" && s != "**") r.L++;
        rs.push_back(std::move(r));
    }
    std::vector<std::vector<std::string>> paths(requests.size());
    for (size_t j = 0; j < requests.size(); j++) {
        std::string pre = "request " + std::to_string(j) + ": ";
        const auto& [user, groups, action, path] = requests[j];
        if (!isName(user)) throw std::invalid_argument(pre + "bad user " + pyrepr(user));
        for (auto& g : groups) if (!isName(g)) throw std::invalid_argument(pre + "bad groups");
        if (!isWord(action)) throw std::invalid_argument(pre + "bad action " + pyrepr(action));
        if (!splitPath(path, paths[j], false)) throw std::invalid_argument(pre + "bad path " + pyrepr(path));
    }
    std::vector<std::string> res;
    for (size_t j = 0; j < requests.size(); j++) {
        const auto& [user, groups, action, path] = requests[j];
        const auto& ps = paths[j];
        int n = (int)ps.size();
        uint64_t full = (n + 1 >= 64) ? ~0ULL : ((1ULL << (n + 1)) - 1);
        bool have = false;
        int bL = 0, bP = 0, bA = 0;
        long bd = -1, ba = -1;
        for (size_t i = 0; i < rs.size(); i++) {
            const Rule& r = rs[i];
            if (r.P == 2) { if (r.name != user) continue; }
            else if (r.P == 1) {
                if (std::find(groups.begin(), groups.end(), r.name) == groups.end()) continue;
            }
            int A = r.anyAction ? 0 : 1;
            if (!r.anyAction && std::find(r.actions.begin(), r.actions.end(), action) == r.actions.end()) continue;
            // resource match
            uint64_t set = 1;
            for (const auto& sg : r.segs) {
                if (set == 0) break;
                if (sg == "**") {
                    int low = __builtin_ctzll(set);
                    set = full & ~((1ULL << low) - 1);
                } else if (sg == "*") {
                    set = (set << 1) & full;
                } else {
                    uint64_t ns = 0;
                    uint64_t t = set;
                    while (t) {
                        int p = __builtin_ctzll(t);
                        t &= t - 1;
                        if (p < n && ps[p] == sg) ns |= 1ULL << (p + 1);
                    }
                    set = ns;
                }
            }
            if (!((set >> n) & 1)) continue;
            bool greater = false;
            if (!have) greater = true;
            else if (r.L != bL) greater = r.L > bL;
            else if (r.P != bP) greater = r.P > bP;
            else if (A != bA) greater = A > bA;
            if (greater) {
                have = true; bL = r.L; bP = r.P; bA = A; bd = -1; ba = -1;
            } else if (r.L != bL || r.P != bP || A != bA) continue;
            if (r.deny) { if (bd < 0) bd = (long)i; }
            else { if (ba < 0) ba = (long)i; }
        }
        if (!have) res.push_back("DENY by default");
        else if (bd >= 0) res.push_back("DENY by rule " + std::to_string(bd));
        else res.push_back("ALLOW by rule " + std::to_string(ba));
    }
    return res;
}

function isWs(c: number): boolean {
  return (
    (c >= 9 && c <= 13) ||
    (c >= 0x1c && c <= 0x20) ||
    c === 0x85 ||
    c === 0xa0 ||
    c === 0x1680 ||
    (c >= 0x2000 && c <= 0x200a) ||
    c === 0x2028 ||
    c === 0x2029 ||
    c === 0x202f ||
    c === 0x205f ||
    c === 0x3000
  );
}

function pySplit(s: string): string[] {
  const res: string[] = [];
  let cur = "";
  for (const ch of s) {
    if (isWs(ch.codePointAt(0)!)) {
      if (cur.length > 0) {
        res.push(cur);
        cur = "";
      }
    } else cur += ch;
  }
  if (cur.length > 0) res.push(cur);
  return res;
}

function pyRepr(v: unknown): string {
  if (typeof v !== "string") {
    if (v === null || v === undefined) return "None";
    if (v === true) return "True";
    if (v === false) return "False";
    if (typeof v === "number") return String(v);
    try {
      return JSON.stringify(v) ?? String(v);
    } catch {
      return String(v);
    }
  }
  const quote = v.includes("'") && !v.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of v) {
    const c = ch.codePointAt(0)!;
    if (ch === quote || ch === "\\") out += "\\" + ch;
    else if (ch === "\n") out += "\\n";
    else if (ch === "\r") out += "\\r";
    else if (ch === "\t") out += "\\t";
    else if (c < 0x20 || c === 0x7f || (c >= 0x80 && c <= 0xa0) || c === 0xad) {
      out += "\\x" + c.toString(16).padStart(2, "0");
    } else if (c === 0x2028 || c === 0x2029 || c === 0x1680 || (c >= 0x2000 && c <= 0x200a) || c === 0x202f || c === 0x205f || c === 0x3000) {
      out += "\\u" + c.toString(16).padStart(4, "0");
    } else out += ch;
  }
  return out + quote;
}

const NAME = /^[a-z0-9_]+$/;
const ACTW = /^[a-z]+$/;
const ACTL = /^[a-z]+(,[a-z]+)*$/;
const SEG = /^[a-z0-9._-]+$/;
const PRIN = /^(user|group):[a-z0-9_]+$/;

interface Rule {
  deny: boolean;
  pk: number; // 0 any,1 group,2 user
  pname: string;
  actions: Set<string> | null;
  hasStar: boolean;
  pieces: string[][];
  L: number;
  spec: number;
}

function segMatch(p: string, s: string): boolean {
  return p === "*" || p === s;
}

function pieceAt(piece: string[], path: string[], at: number): boolean {
  for (let k = 0; k < piece.length; k++) {
    if (!segMatch(piece[k], path[at + k])) return false;
  }
  return true;
}

function resMatch(r: Rule, path: string[]): boolean {
  const n = path.length;
  if (!r.hasStar) {
    const p = r.pieces[0];
    if (p.length !== n) return false;
    return pieceAt(p, path, 0);
  }
  const first = r.pieces[0];
  const last = r.pieces[r.pieces.length - 1];
  if (first.length + last.length > n) return false;
  if (!pieceAt(first, path, 0)) return false;
  if (!pieceAt(last, path, n - last.length)) return false;
  let pos = first.length;
  const limit = n - last.length;
  for (let k = 1; k < r.pieces.length - 1; k++) {
    const pc = r.pieces[k];
    if (pc.length === 0) continue;
    let found = -1;
    for (let i = pos; i + pc.length <= limit; i++) {
      if (pieceAt(pc, path, i)) {
        found = i;
        break;
      }
    }
    if (found < 0) return false;
    pos = found + pc.length;
  }
  return true;
}

export function evaluateAccess(rules: string[], requests: [string, string[], string, string][]): string[] {
  if (!Array.isArray(rules)) throw new Error("rules must be a list");
  if (!Array.isArray(requests)) throw new Error("requests must be a list");
  const parsed: Rule[] = [];
  for (let i = 0; i < rules.length; i++) {
    const rule: unknown = rules[i];
    if (typeof rule !== "string") throw new Error(`rule ${i}: not a str`);
    const f = pySplit(rule);
    if (f.length !== 4) throw new Error(`rule ${i}: expected 4 fields, got ${f.length}`);
    const [effect, principal, action, resource] = f;
    if (effect !== "ALLOW" && effect !== "DENY") throw new Error(`rule ${i}: bad effect ${pyRepr(effect)}`);
    if (principal !== "*" && !PRIN.test(principal)) throw new Error(`rule ${i}: bad principal ${pyRepr(principal)}`);
    if (action !== "*" && !ACTL.test(action)) throw new Error(`rule ${i}: bad action ${pyRepr(action)}`);
    let segs: string[] = [];
    let ok = true;
    if (resource === "/") segs = [];
    else if (resource[0] !== "/") ok = false;
    else {
      segs = resource.slice(1).split("/");
      for (const s of segs) {
        if (!(s === "*" || s === "**" || SEG.test(s))) {
          ok = false;
          break;
        }
      }
    }
    if (!ok) throw new Error(`rule ${i}: bad resource ${pyRepr(resource)}`);
    const pieces: string[][] = [[]];
    let hasStar = false;
    let L = 0;
    for (const s of segs) {
      if (s === "**") {
        hasStar = true;
        pieces.push([]);
      } else {
        pieces[pieces.length - 1].push(s);
        if (s !== "*") L++;
      }
    }
    let pk = 0;
    let pname = "";
    if (principal !== "*") {
      const idx = principal.indexOf(":");
      pk = principal.slice(0, idx) === "user" ? 2 : 1;
      pname = principal.slice(idx + 1);
    }
    const isList = action !== "*";
    parsed.push({
      deny: effect === "DENY",
      pk,
      pname,
      actions: isList ? new Set(action.split(",")) : null,
      hasStar,
      pieces,
      L,
      spec: L * 8 + pk * 2 + (isList ? 1 : 0),
    });
  }
  const reqs: { user: string; groups: Set<string>; action: string; path: string[] }[] = [];
  for (let j = 0; j < requests.length; j++) {
    const r: unknown = requests[j];
    if (!Array.isArray(r) || r.length !== 4) throw new Error(`request ${j}: expected 4-tuple`);
    const [user, groups, action, path] = r as unknown[];
    if (typeof user !== "string" || !NAME.test(user)) throw new Error(`request ${j}: bad user ${pyRepr(user)}`);
    if (!Array.isArray(groups) || !groups.every((g) => typeof g === "string" && NAME.test(g))) {
      throw new Error(`request ${j}: bad groups`);
    }
    if (typeof action !== "string" || !ACTW.test(action)) throw new Error(`request ${j}: bad action ${pyRepr(action)}`);
    let ok = typeof path === "string";
    let segs: string[] = [];
    if (ok) {
      const p = path as string;
      if (p === "/") segs = [];
      else if (p[0] !== "/") ok = false;
      else {
        segs = p.slice(1).split("/");
        if (!segs.every((s) => SEG.test(s))) ok = false;
      }
    }
    if (!ok) throw new Error(`request ${j}: bad path ${pyRepr(path)}`);
    reqs.push({ user, groups: new Set(groups as string[]), action, path: segs });
  }
  const out: string[] = [];
  for (const q of reqs) {
    let best = -1;
    let bestDeny = -1;
    let bestAllow = -1;
    for (let i = 0; i < parsed.length; i++) {
      const r = parsed[i];
      if (r.spec < best) continue;
      if (r.pk === 2 && r.pname !== q.user) continue;
      if (r.pk === 1 && !q.groups.has(r.pname)) continue;
      if (r.actions !== null && !r.actions.has(q.action)) continue;
      if (!resMatch(r, q.path)) continue;
      if (r.spec > best) {
        best = r.spec;
        bestDeny = -1;
        bestAllow = -1;
      }
      if (r.deny) {
        if (bestDeny < 0) bestDeny = i;
      } else if (bestAllow < 0) bestAllow = i;
    }
    if (best < 0) out.push("DENY by default");
    else if (bestDeny >= 0) out.push(`DENY by rule ${bestDeny}`);
    else out.push(`ALLOW by rule ${bestAllow}`);
  }
  return out;
}

package main

import (
	"fmt"
	"strings"
	"unicode"
)

type Tuple1 struct {
	F0 string
	F1 string
	F2 string
	F3 string
}

func pyRepr(s string) string {
	q := byte('\'')
	if strings.Contains(s, "'") && !strings.Contains(s, "\"") {
		q = '"'
	}
	var b strings.Builder
	b.WriteByte(q)
	for _, r := range s {
		switch {
		case r == '\\':
			b.WriteString("\\\\")
		case r == rune(q):
			b.WriteString("\\" + string(q))
		case r == '\n':
			b.WriteString("\\n")
		case r == '\t':
			b.WriteString("\\t")
		case r == '\r':
			b.WriteString("\\r")
		case r < 32 || r == 127:
			b.WriteString(fmt.Sprintf("\\x%02x", r))
		default:
			b.WriteRune(r)
		}
	}
	b.WriteByte(q)
	return b.String()
}

func isDigits(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

// parse integer part: (0|[1-9][0-9]{0,8})
func validInt(s string) bool {
	if len(s) == 0 || len(s) > 9 || !isDigits(s) {
		return false
	}
	if s[0] == '0' && len(s) > 1 {
		return false
	}
	return true
}

func atoi(s string) int64 {
	var v int64
	for i := 0; i < len(s); i++ {
		v = v*10 + int64(s[i]-'0')
	}
	return v
}

func parseOpening(s string) (int64, bool) {
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	}
	idx := strings.Index(s, ".")
	if idx < 0 {
		return 0, false
	}
	ip, fp := s[:idx], s[idx+1:]
	if !validInt(ip) || len(fp) != 2 || !isDigits(fp) {
		return 0, false
	}
	v := atoi(ip)*100 + atoi(fp)
	if neg {
		v = -v
	}
	return v, true
}

func parseAmount(s string) (int64, bool) {
	ip := s
	fp := ""
	if idx := strings.Index(s, "."); idx >= 0 {
		ip = s[:idx]
		fp = s[idx+1:]
		if len(fp) < 1 || len(fp) > 2 || !isDigits(fp) {
			return 0, false
		}
	}
	if !validInt(ip) {
		return 0, false
	}
	if len(fp) == 1 {
		fp += "0"
	}
	v := atoi(ip) * 100
	if fp != "" {
		v += atoi(fp)
	}
	if v == 0 {
		return 0, false
	}
	return v, true
}

func validDate(s string) bool {
	if len(s) != 10 || s[4] != '-' || s[7] != '-' {
		return false
	}
	if !isDigits(s[0:4]) || !isDigits(s[5:7]) || !isDigits(s[8:10]) {
		return false
	}
	y := int(atoi(s[0:4]))
	m := int(atoi(s[5:7]))
	d := int(atoi(s[8:10]))
	if y < 1900 || y > 2999 || m < 1 || m > 12 || d < 1 {
		return false
	}
	dim := []int{31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31}
	max := dim[m-1]
	if m == 2 && (y%4 == 0 && (y%100 != 0 || y%400 == 0)) {
		max = 29
	}
	return d <= max
}

func money(x int64) string {
	neg := x < 0
	if neg {
		x = -x
	}
	ip := fmt.Sprintf("%d", x/100)
	var parts []string
	for len(ip) > 3 {
		parts = append([]string{ip[len(ip)-3:]}, parts...)
		ip = ip[:len(ip)-3]
	}
	parts = append([]string{ip}, parts...)
	s := strings.Join(parts, ",") + fmt.Sprintf(".%02d", x%100)
	if neg {
		s = "-" + s
	}
	return s
}

func padLeft(s string, w int) string {
	n := len([]rune(s))
	if n < w {
		return strings.Repeat(" ", w-n) + s
	}
	return s
}

func padRight(s string, w int) string {
	n := len([]rune(s))
	if n < w {
		return s + strings.Repeat(" ", w-n)
	}
	return s
}

type applied struct {
	date, kind, memo string
	amt              int64
}

func RenderStatement(opening string, entries []Tuple1) ([]string, error) {
	open, ok := parseOpening(opening)
	if !ok {
		return nil, fmt.Errorf("opening: bad amount %s", pyRepr(opening))
	}
	amts := make([]int64, len(entries))
	prev := ""
	for i, e := range entries {
		if !validDate(e.F0) {
			return nil, fmt.Errorf("entry %d: bad date %s", i, pyRepr(e.F0))
		}
		if i > 0 && e.F0 < prev {
			return nil, fmt.Errorf("entry %d: date out of order", i)
		}
		prev = e.F0
		if e.F1 != "credit" && e.F1 != "debit" && e.F1 != "fee" {
			return nil, fmt.Errorf("entry %d: bad kind %s", i, pyRepr(e.F1))
		}
		a, ok := parseAmount(e.F2)
		if !ok {
			return nil, fmt.Errorf("entry %d: bad amount %s", i, pyRepr(e.F2))
		}
		amts[i] = a
		if len(strings.FieldsFunc(e.F3, unicode.IsSpace)) == 0 {
			return nil, fmt.Errorf("entry %d: bad memo", i)
		}
		for _, r := range e.F3 {
			if r < 32 || r == 127 {
				return nil, fmt.Errorf("entry %d: bad memo", i)
			}
		}
	}

	lines := []string{"Opening balance: " + money(open)}
	bal := open
	var c, d, f int
	feeDates := map[string]bool{}

	emit := func(date, kind, memo string, amt int64) {
		sign := "-"
		if kind == "credit" {
			sign = "+"
			bal += amt
			c++
		} else {
			bal -= amt
			if kind == "debit" {
				d++
			} else {
				f++
			}
		}
		m := strings.Join(strings.FieldsFunc(memo, unicode.IsSpace), " ")
		r := []rune(m)
		if len(r) > 20 {
			m = string(r[:19]) + "~"
		}
		m = padRight(m, 20)
		flag := ""
		if bal < 0 {
			flag = " OD"
		}
		lines = append(lines, date+"  "+m+"  "+padLeft(sign+money(amt), 14)+"  "+padLeft(money(bal), 15)+flag)
	}

	for i, e := range entries {
		emit(e.F0, e.F1, e.F3, amts[i])
		if e.F1 == "debit" && bal < 0 && !feeDates[e.F0] {
			feeDates[e.F0] = true
			emit(e.F0, "fee", "OVERDRAFT FEE", 2500)
		}
	}
	lines = append(lines, "Closing balance: "+money(bal))
	lines = append(lines, fmt.Sprintf("Credits: %d  Debits: %d  Fees: %d", c, d, f))
	return lines, nil
}

import java.util.*;
import java.util.regex.*;

public final class Solution {
    public record Tuple1(String f0, String f1, String f2, String f3) {}

    private static final Pattern OPEN = Pattern.compile("-?(0|[1-9][0-9]{0,8})\\.[0-9]{2}");
    private static final Pattern AMT = Pattern.compile("(0|[1-9][0-9]{0,8})(\\.[0-9]{1,2})?");
    private static final Pattern DATE = Pattern.compile("[0-9]{4}-[0-9]{2}-[0-9]{2}");

    private static boolean validDate(String s) {
        if (s == null || !DATE.matcher(s).matches()) return false;
        int y = Integer.parseInt(s.substring(0, 4));
        int m = Integer.parseInt(s.substring(5, 7));
        int d = Integer.parseInt(s.substring(8, 10));
        if (y < 1900 || y > 2999) return false;
        if (m < 1 || m > 12) return false;
        int[] dm = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        boolean leap = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
        int max = dm[m - 1] + (m == 2 && leap ? 1 : 0);
        return d >= 1 && d <= max;
    }

    private static boolean isPyWs(int c) {
        if (c >= 9 && c <= 13) return true;
        if (c >= 0x1c && c <= 0x20) return true;
        if (c == 0x85 || c == 0xa0 || c == 0x1680) return true;
        if (c >= 0x2000 && c <= 0x200a) return true;
        return c == 0x2028 || c == 0x2029 || c == 0x202f || c == 0x205f || c == 0x3000;
    }

    private static List<String> split(String s) {
        List<String> res = new ArrayList<>();
        StringBuilder cur = new StringBuilder();
        int i = 0;
        while (i < s.length()) {
            int c = s.codePointAt(i);
            i += Character.charCount(c);
            if (isPyWs(c)) {
                if (cur.length() > 0) {
                    res.add(cur.toString());
                    cur.setLength(0);
                }
            } else {
                cur.appendCodePoint(c);
            }
        }
        if (cur.length() > 0) res.add(cur.toString());
        return res;
    }

    private static long parseCents(String s) {
        boolean neg = s.startsWith("-");
        if (neg) s = s.substring(1);
        String ip, fp;
        int dot = s.indexOf('.');
        if (dot < 0) {
            ip = s;
            fp = "00";
        } else {
            ip = s.substring(0, dot);
            fp = s.substring(dot + 1);
            if (fp.length() == 1) fp = fp + "0";
        }
        long v = Long.parseLong(ip) * 100 + Long.parseLong(fp);
        return neg ? -v : v;
    }

    private static String money(long x) {
        boolean neg = x < 0;
        long a = Math.abs(x);
        long ip = a / 100;
        long fp = a % 100;
        String is = Long.toString(ip);
        StringBuilder sb = new StringBuilder();
        int len = is.length();
        for (int i = 0; i < len; i++) {
            if (i > 0 && (len - i) % 3 == 0) sb.append(',');
            sb.append(is.charAt(i));
        }
        return (neg ? "-" : "") + sb + "." + (fp < 10 ? "0" : "") + fp;
    }

    private static String padRight(String s, int w) {
        int n = s.codePointCount(0, s.length());
        StringBuilder sb = new StringBuilder(s);
        for (int i = n; i < w; i++) sb.append(' ');
        return sb.toString();
    }

    private static String padLeft(String s, int w) {
        int n = s.codePointCount(0, s.length());
        StringBuilder sb = new StringBuilder();
        for (int i = n; i < w; i++) sb.append(' ');
        return sb.append(s).toString();
    }

    public static List<String> renderStatement(String opening, List<Tuple1> entries) {
        if (opening == null) throw new IllegalArgumentException("opening must be a str");
        if (!OPEN.matcher(opening).matches()) throw new IllegalArgumentException("opening: bad amount");
        if (entries == null) throw new IllegalArgumentException("entries must be a list");
        int n = entries.size();
        long[] amts = new long[n];
        String[] memos = new String[n];
        String prev = null;
        for (int i = 0; i < n; i++) {
            Tuple1 e = entries.get(i);
            if (e == null) throw new IllegalArgumentException("entry " + i + ": expected 4-tuple");
            if (!validDate(e.f0())) throw new IllegalArgumentException("entry " + i + ": bad date");
            if (prev != null && e.f0().compareTo(prev) < 0)
                throw new IllegalArgumentException("entry " + i + ": date out of order");
            String k = e.f1();
            if (k == null || !(k.equals("credit") || k.equals("debit") || k.equals("fee")))
                throw new IllegalArgumentException("entry " + i + ": bad kind");
            String a = e.f2();
            if (a == null || !AMT.matcher(a).matches()) throw new IllegalArgumentException("entry " + i + ": bad amount");
            long c = parseCents(a);
            if (c == 0) throw new IllegalArgumentException("entry " + i + ": bad amount");
            amts[i] = c;
            String m = e.f3();
            if (m == null) throw new IllegalArgumentException("entry " + i + ": bad memo");
            List<String> toks = split(m);
            if (toks.isEmpty()) throw new IllegalArgumentException("entry " + i + ": bad memo");
            for (int j = 0; j < m.length(); j++) {
                char ch = m.charAt(j);
                if (ch < 32 || ch == 127) throw new IllegalArgumentException("entry " + i + ": bad memo");
            }
            memos[i] = String.join(" ", toks);
            prev = e.f0();
        }
        List<String> out = new ArrayList<>();
        long bal = parseCents(opening);
        out.add("Opening balance: " + money(bal));
        int cc = 0, dc = 0, fc = 0;
        Set<String> feeDates = new HashSet<>();
        for (int i = 0; i < n; i++) {
            Tuple1 e = entries.get(i);
            String kind = e.f1();
            String memo = memos[i];
            long amt = amts[i];
            if (kind.equals("credit")) {
                bal += amt;
                cc++;
            } else if (kind.equals("debit")) {
                bal -= amt;
                dc++;
            } else {
                bal -= amt;
                fc++;
            }
            out.add(line(e.f0(), memo, kind.equals("credit"), amt, bal));
            if (kind.equals("debit") && bal < 0 && !feeDates.contains(e.f0())) {
                feeDates.add(e.f0());
                bal -= 2500;
                fc++;
                out.add(line(e.f0(), "OVERDRAFT FEE", false, 2500, bal));
            }
        }
        out.add("Closing balance: " + money(bal));
        out.add("Credits: " + cc + "  Debits: " + dc + "  Fees: " + fc);
        return out;
    }

    private static String line(String date, String memo, boolean credit, long amt, long bal) {
        int cnt = memo.codePointCount(0, memo.length());
        if (cnt > 20) {
            memo = memo.substring(0, memo.offsetByCodePoints(0, 19)) + "~";
        }
        String m = padRight(memo, 20);
        String a = padLeft((credit ? "+" : "-") + money(amt), 14);
        String b = padLeft(money(bal), 15);
        return date + "  " + m + "  " + a + "  " + b + (bal < 0 ? " OD" : "");
    }
}

#include <string>
#include <vector>
#include <tuple>
#include <stdexcept>
