namespace {

bool isDigit(char c) { return c >= '0' && c <= '9'; }

// parse amount of form int part (no leading zeros, <=9 digits) with optional fraction
// returns cents; fracMin/fracMax digits allowed; ok flag
bool parseAmount(const std::string& s, size_t pos, bool exactTwo, long long& out) {
    size_t n = s.size();
    size_t i = pos;
    size_t start = i;
    while (i < n && isDigit(s[i])) i++;
    size_t len = i - start;
    if (len == 0 || len > 9) return false;
    if (len > 1 && s[start] == '0') return false;
    long long ip = std::stoll(s.substr(start, len));
    if (i == n) {
        if (exactTwo) return false;
        out = ip * 100;
        return true;
    }
    if (s[i] != '.') return false;
    i++;
    size_t fs = i;
    while (i < n && isDigit(s[i])) i++;
    if (i != n) return false;
    size_t fl = n - fs;
    if (exactTwo) {
        if (fl != 2) return false;
    } else {
        if (fl < 1 || fl > 2) return false;
    }
    long long frac = 0;
    if (fl == 1) frac = (s[fs] - '0') * 10;
    else frac = (s[fs] - '0') * 10 + (s[fs + 1] - '0');
    out = ip * 100 + frac;
    return true;
}

bool validDate(const std::string& d) {
    if (d.size() != 10) return false;
    for (int i = 0; i < 10; i++) {
        if (i == 4 || i == 7) {
            if (d[i] != '-') return false;
        } else if (!isDigit(d[i])) return false;
    }
    int y = std::stoi(d.substr(0, 4));
    int m = std::stoi(d.substr(5, 2));
    int day = std::stoi(d.substr(8, 2));
    if (y < 1900 || y > 2999) return false;
    if (m < 1 || m > 12) return false;
    static const int dm[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    int mx = dm[m - 1];
    bool leap = (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
    if (m == 2 && leap) mx = 29;
    return day >= 1 && day <= mx;
}

struct Ch {
    unsigned cp;
    std::string bytes;
};

std::vector<Ch> decode(const std::string& s) {
    std::vector<Ch> r;
    size_t i = 0, n = s.size();
    while (i < n) {
        unsigned char c = s[i];
        size_t len = 1;
        unsigned cp = c;
        if (c >= 0xF0 && c < 0xF8) { len = 4; cp = c & 0x07; }
        else if (c >= 0xE0) { len = 3; cp = c & 0x0F; }
        else if (c >= 0xC0) { len = 2; cp = c & 0x1F; }
        if (c >= 0xC0 && c < 0xF8 && i + len <= n) {
            bool ok = true;
            for (size_t k = 1; k < len; k++) {
                unsigned char cc = s[i + k];
                if ((cc & 0xC0) != 0x80) { ok = false; break; }
                cp = (cp << 6) | (cc & 0x3F);
            }
            if (!ok) { len = 1; cp = c; }
        } else if (c >= 0x80) {
            len = 1; cp = c;
        }
        r.push_back({cp, s.substr(i, len)});
        i += len;
    }
    return r;
}

bool isWS(unsigned cp) {
    if (cp == ' ' || (cp >= 9 && cp <= 13) || (cp >= 0x1c && cp <= 0x1f)) return true;
    if (cp == 0x85 || cp == 0xA0 || cp == 0x1680) return true;
    if (cp >= 0x2000 && cp <= 0x200A) return true;
    if (cp == 0x2028 || cp == 0x2029 || cp == 0x202F || cp == 0x205F || cp == 0x3000) return true;
    return false;
}

std::string money(long long x) {
    bool neg = x < 0;
    long long a = neg ? -x : x;
    long long ip = a / 100, fr = a % 100;
    std::string is = std::to_string(ip);
    std::string out;
    int cnt = 0;
    for (int i = (int)is.size() - 1; i >= 0; i--) {
        out.insert(out.begin(), is[i]);
        cnt++;
        if (cnt % 3 == 0 && i > 0) out.insert(out.begin(), ',');
    }
    std::string res = neg ? "-" : "";
    res += out;
    res += ".";
    res += char('0' + fr / 10);
    res += char('0' + fr % 10);
    return res;
}

std::string rjust(const std::string& s, size_t w) {
    if (s.size() >= w) return s;
    return std::string(w - s.size(), ' ') + s;
}

std::string normMemo(const std::string& memo) {
    std::vector<Ch> cs = decode(memo);
    std::vector<std::vector<Ch>> words;
    std::vector<Ch> cur;
    for (auto& c : cs) {
        if (isWS(c.cp)) {
            if (!cur.empty()) { words.push_back(cur); cur.clear(); }
        } else cur.push_back(c);
    }
    if (!cur.empty()) words.push_back(cur);
    std::vector<Ch> joined;
    for (size_t i = 0; i < words.size(); i++) {
        if (i) joined.push_back({' ', " "});
        for (auto& c : words[i]) joined.push_back(c);
    }
    std::string res;
    size_t count = joined.size();
    if (count > 20) {
        for (size_t i = 0; i < 19; i++) res += joined[i].bytes;
        res += "~";
        count = 20;
    } else {
        for (auto& c : joined) res += c.bytes;
    }
    if (count < 20) res += std::string(20 - count, ' ');
    return res;
}

} // namespace

std::vector<std::string> render_statement(const std::string& opening, const std::vector<std::tuple<std::string, std::string, std::string, std::string>>& entries) {
    long long balance = 0;
    {
        bool neg = false;
        size_t pos = 0;
        if (!opening.empty() && opening[0] == '-') { neg = true; pos = 1; }
        long long v;
        if (!parseAmount(opening, pos, true, v)) throw std::invalid_argument("opening: bad amount");
        balance = neg ? -v : v;
    }
    struct E { std::string date, kind; long long amt; std::string memo; };
    std::vector<E> es;
    std::string prevDate;
    for (size_t i = 0; i < entries.size(); i++) {
        const auto& [date, kind, amount, memo] = entries[i];
        if (!validDate(date)) throw std::invalid_argument("bad date");
        if (i > 0 && date < prevDate) throw std::invalid_argument("date out of order");
        if (kind != "credit" && kind != "debit" && kind != "fee") throw std::invalid_argument("bad kind");
        long long a;
        if (!parseAmount(amount, 0, false, a) || a == 0) throw std::invalid_argument("bad amount");
        std::vector<Ch> cs = decode(memo);
        bool nonws = false;
        for (auto& c : cs) {
            if (c.cp < 32 || c.cp == 127) throw std::invalid_argument("bad memo");
            if (!isWS(c.cp)) nonws = true;
        }
        if (!nonws) throw std::invalid_argument("bad memo");
        prevDate = date;
        es.push_back({date, kind, a, memo});
    }

    std::vector<std::string> out;
    out.push_back("Opening balance: " + money(balance));
    long long c = 0, d = 0, f = 0;
    std::set<std::string> feeDates;
    auto emit = [&](const std::string& date, const std::string& kind, long long amt, const std::string& memoPadded) {
        if (kind == "credit") { balance += amt; c++; }
        else if (kind == "debit") { balance -= amt; d++; }
        else { balance -= amt; f++; }
        std::string amts = (kind == "credit" ? "+" : "-") + money(amt);
        std::string line = date + "  " + memoPadded + "  " + rjust(amts, 14) + "  " + rjust(money(balance), 15);
        if (balance < 0) line += " OD";
        out.push_back(line);
    };
    for (auto& e : es) {
        emit(e.date, e.kind, e.amt, normMemo(e.memo));
        if (e.kind == "debit" && balance < 0 && !feeDates.count(e.date)) {
            feeDates.insert(e.date);
            emit(e.date, "fee", 2500, normMemo("OVERDRAFT FEE"));
        }
    }
    out.push_back("Closing balance: " + money(balance));
    out.push_back("Credits: " + std::to_string(c) + "  Debits: " + std::to_string(d) + "  Fees: " + std::to_string(f));
    return out;
}

export function renderStatement(opening: string, entries: [string, string, string, string][]): string[] {
  const pyRepr = (v: unknown): string => {
    if (typeof v === "string") {
      const q = v.includes("'") && !v.includes('"') ? '"' : "'";
      let out = q;
      for (const ch of v) {
        const c = ch.codePointAt(0)!;
        if (ch === "\\") out += "\\\\";
        else if (ch === q) out += "\\" + q;
        else if (ch === "\n") out += "\\n";
        else if (ch === "\r") out += "\\r";
        else if (ch === "\t") out += "\\t";
        else if (c < 32 || c === 127) out += "\\x" + c.toString(16).padStart(2, "0");
        else out += ch;
      }
      return out + q;
    }
    if (v === null || v === undefined) return "None";
    if (v === true) return "True";
    if (v === false) return "False";
    if (typeof v === "number") return String(v);
    try {
      return JSON.stringify(v) ?? String(v);
    } catch {
      return String(v);
    }
  };

  const wsSet = new Set<number>([
    0x20, 0x85, 0xa0, 0x1680, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
  ]);
  for (let c = 0x2000; c <= 0x200a; c++) wsSet.add(c);
  for (let c = 9; c <= 13; c++) wsSet.add(c);
  for (let c = 0x1c; c <= 0x1f; c++) wsSet.add(c);

  const pySplit = (s: string): string[] => {
    const parts: string[] = [];
    let cur = "";
    for (const ch of s) {
      if (wsSet.has(ch.codePointAt(0)!)) {
        if (cur.length > 0) {
          parts.push(cur);
          cur = "";
        }
      } else cur += ch;
    }
    if (cur.length > 0) parts.push(cur);
    return parts;
  };

  if (typeof opening !== "string") throw new Error("opening must be a str");
  if (!/^-?(0|[1-9][0-9]{0,8})\.[0-9]{2}$/.test(opening)) {
    throw new Error("opening: bad amount " + pyRepr(opening));
  }
  if (!Array.isArray(entries)) throw new Error("entries must be a list");

  const openNeg = opening.startsWith("-");
  const openBody = openNeg ? opening.slice(1) : opening;
  const [oi, of] = openBody.split(".");
  let openCents = parseInt(oi, 10) * 100 + parseInt(of, 10);
  if (openNeg) openCents = -openCents;

  const isLeap = (y: number) => (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
  const validDate = (d: unknown): boolean => {
    if (typeof d !== "string") return false;
    if (!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(d)) return false;
    const y = parseInt(d.slice(0, 4), 10);
    const m = parseInt(d.slice(5, 7), 10);
    const day = parseInt(d.slice(8, 10), 10);
    if (y < 1900 || y > 2999) return false;
    if (m < 1 || m > 12) return false;
    const dim = [31, isLeap(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1];
    return day >= 1 && day <= dim;
  };

  type E = { date: string; kind: string; cents: number; memo: string };
  const parsed: E[] = [];
  let prevDate: string | null = null;
  for (let i = 0; i < entries.length; i++) {
    const e: unknown = entries[i];
    if (!Array.isArray(e) || e.length !== 4) throw new Error(`entry ${i}: expected 4-tuple`);
    const [date, kind, amount, memo] = e as unknown[];
    if (!validDate(date)) throw new Error(`entry ${i}: bad date ${pyRepr(date)}`);
    const ds = date as string;
    if (prevDate !== null && ds < prevDate) throw new Error(`entry ${i}: date out of order`);
    prevDate = ds;
    if (kind !== "credit" && kind !== "debit" && kind !== "fee") {
      throw new Error(`entry ${i}: bad kind ${pyRepr(kind)}`);
    }
    let cents = 0;
    let ok = false;
    if (typeof amount === "string") {
      const m = /^(0|[1-9][0-9]{0,8})(?:\.([0-9]{1,2}))?$/.exec(amount);
      if (m) {
        const frac = (m[2] ?? "").padEnd(2, "0");
        cents = parseInt(m[1], 10) * 100 + parseInt(frac === "" ? "0" : frac, 10);
        ok = cents !== 0;
      }
    }
    if (!ok) throw new Error(`entry ${i}: bad amount ${pyRepr(amount)}`);
    let memoOk = typeof memo === "string";
    if (memoOk) {
      const ms = memo as string;
      if (pySplit(ms).length === 0) memoOk = false;
      else {
        for (const ch of ms) {
          const c = ch.codePointAt(0)!;
          if (c < 32 || c === 127) {
            memoOk = false;
            break;
          }
        }
      }
    }
    if (!memoOk) throw new Error(`entry ${i}: bad memo`);
    parsed.push({ date: ds, kind: kind as string, cents, memo: memo as string });
  }

  const money = (x: number): string => {
    const neg = x < 0;
    const a = Math.abs(x);
    const ip = Math.floor(a / 100);
    const fp = a % 100;
    const s = String(ip).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    return (neg ? "-" : "") + s + "." + String(fp).padStart(2, "0");
  };
  const cpLen = (s: string) => Array.from(s).length;
  const padRight = (s: string, w: number) => s + " ".repeat(Math.max(0, w - cpLen(s)));
  const padLeft = (s: string, w: number) => " ".repeat(Math.max(0, w - cpLen(s))) + s;

  const lines: string[] = ["Opening balance: " + money(openCents)];
  let bal = openCents;
  let c = 0, d = 0, f = 0;
  const autoDates = new Set<string>();

  const emit = (date: string, kind: string, cents: number, memo: string) => {
    if (kind === "credit") {
      bal += cents;
      c++;
    } else if (kind === "debit") {
      bal -= cents;
      d++;
    } else {
      bal -= cents;
      f++;
    }
    let mm = pySplit(memo).join(" ");
    const chars = Array.from(mm);
    if (chars.length > 20) mm = chars.slice(0, 19).join("") + "~";
    const amt = (kind === "credit" ? "+" : "-") + money(cents);
    lines.push(
      `${date}  ${padRight(mm, 20)}  ${padLeft(amt, 14)}  ${padLeft(money(bal), 15)}${bal < 0 ? " OD" : ""}`
    );
  };

  for (const e of parsed) {
    emit(e.date, e.kind, e.cents, e.memo);
    if (e.kind === "debit" && bal < 0 && !autoDates.has(e.date)) {
      autoDates.add(e.date);
      emit(e.date, "fee", 2500, "OVERDRAFT FEE");
    }
  }

  lines.push("Closing balance: " + money(bal));
  lines.push(`Credits: ${c}  Debits: ${d}  Fees: ${f}`);
  return lines;
}

package main

import (
	"fmt"
	"strings"
)

type version struct {
	n   [3]string
	rc  bool
	rcN string
}

func isNum(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	if len(s) > 1 && s[0] == '0' {
		return false
	}
	return true
}

func cmpNum(a, b string) int {
	if len(a) != len(b) {
		if len(a) < len(b) {
			return -1
		}
		return 1
	}
	return strings.Compare(a, b)
}

func parseVersion(s string) (version, bool) {
	var v version
	base := s
	if i := strings.Index(s, "~"); i >= 0 {
		base = s[:i]
		suf := s[i+1:]
		if !strings.HasPrefix(suf, "rc") {
			return v, false
		}
		n := suf[2:]
		if !isNum(n) || n == "0" {
			return v, false
		}
		v.rc = true
		v.rcN = n
	}
	parts := strings.Split(base, ".")
	if len(parts) != 3 {
		return v, false
	}
	for i, p := range parts {
		if !isNum(p) {
			return v, false
		}
		v.n[i] = p
	}
	return v, true
}

func cmpVer(a, b version) int {
	for i := 0; i < 3; i++ {
		if c := cmpNum(a.n[i], b.n[i]); c != 0 {
			return c
		}
	}
	if !a.rc && !b.rc {
		return 0
	}
	if !a.rc {
		return 1
	}
	if !b.rc {
		return -1
	}
	return cmpNum(a.rcN, b.rcN)
}

func pyRepr(s string) string {
	q := byte('\'')
	if strings.Contains(s, "'") && !strings.Contains(s, "\"") {
		q = '"'
	}
	var sb strings.Builder
	sb.WriteByte(q)
	for _, r := range s {
		switch {
		case r == '\\':
			sb.WriteString("\\\\")
		case r == '\n':
			sb.WriteString("\\n")
		case r == '\r':
			sb.WriteString("\\r")
		case r == '\t':
			sb.WriteString("\\t")
		case r == rune(q):
			sb.WriteString("\\" + string(q))
		case r < 0x20 || r == 0x7f:
			sb.WriteString(fmt.Sprintf("\\x%02x", r))
		default:
			sb.WriteRune(r)
		}
	}
	sb.WriteByte(q)
	return sb.String()
}

type clauseFn func(v version) bool

func parseClause(c string) (clauseFn, bool) {
	if c == "*" {
		return func(v version) bool { return true }, true
	}
	if strings.HasPrefix(c, "@") {
		parts := strings.Split(c[1:], ".")
		if len(parts) == 2 && isNum(parts[0]) && isNum(parts[1]) {
			x, y := parts[0], parts[1]
			return func(v version) bool {
				return v.n[0] == x && cmpNum(v.n[1], y) >= 0
			}, true
		}
		return nil, false
	}
	ops := []string{">=", "<=", "!=", ">", "<", "="}
	for _, op := range ops {
		if strings.HasPrefix(c, op) {
			t, ok := parseVersion(c[len(op):])
			if !ok {
				return nil, false
			}
			return func(v version) bool {
				r := cmpVer(v, t)
				switch op {
				case ">=":
					return r >= 0
				case "<=":
					return r <= 0
				case "!=":
					return r != 0
				case ">":
					return r > 0
				case "<":
					return r < 0
				default:
					return r == 0
				}
			}, true
		}
	}
	if t, ok := parseVersion(c); ok {
		return func(v version) bool { return cmpVer(v, t) == 0 }, true
	}
	if strings.HasSuffix(c, ".*") {
		parts := strings.Split(c, ".")
		if len(parts) == 2 && isNum(parts[0]) {
			x := parts[0]
			return func(v version) bool { return v.n[0] == x }, true
		}
		if len(parts) == 3 && isNum(parts[0]) && isNum(parts[1]) {
			x, y := parts[0], parts[1]
			return func(v version) bool { return v.n[0] == x && v.n[1] == y }, true
		}
	}
	return nil, false
}

type alternative struct {
	rc      bool
	clauses []clauseFn
}

func PickVersion(available []string, constraint string) (*string, error) {
	vers := make([]version, len(available))
	for i, s := range available {
		v, ok := parseVersion(s)
		if !ok {
			return nil, fmt.Errorf("invalid version at index %d: %s", i, pyRepr(s))
		}
		vers[i] = v
	}
	if strings.Trim(constraint, " ") == "" {
		return nil, fmt.Errorf("empty constraint")
	}
	var alts []alternative
	for ai, altText := range strings.Split(constraint, "|") {
		a := ai + 1
		t := strings.Trim(altText, " ")
		var alt alternative
		if strings.HasPrefix(t, "?") {
			alt.rc = true
			t = strings.Trim(t[1:], " ")
		}
		if t == "" {
			return nil, fmt.Errorf("alternative %d is empty", a)
		}
		for ci, ct := range strings.Split(t, ",") {
			c := strings.Trim(ct, " ")
			f, ok := parseClause(c)
			if !ok {
				return nil, fmt.Errorf("alternative %d, clause %d: invalid clause %s", a, ci+1, pyRepr(c))
			}
			alt.clauses = append(alt.clauses, f)
		}
		alts = append(alts, alt)
	}
	best := -1
	for i, v := range vers {
		matched := false
		for _, alt := range alts {
			if v.rc && !alt.rc {
				continue
			}
			ok := true
			for _, f := range alt.clauses {
				if !f(v) {
					ok = false
					break
				}
			}
			if ok {
				matched = true
				break
			}
		}
		if matched && (best < 0 || cmpVer(v, vers[best]) > 0) {
			best = i
		}
	}
	if best < 0 {
		return nil, nil
	}
	r := available[best]
	return &r, nil
}

import java.util.*;
import java.math.BigInteger;
import java.util.function.Predicate;

public final class Solution {
    private record Ver(BigInteger a, BigInteger b, BigInteger c, BigInteger rc) {}

    private record Alt(boolean allowRc, List<Predicate<Ver>> clauses) {}

    private static int cmp(Ver x, Ver y) {
        int r = x.a().compareTo(y.a());
        if (r != 0) return r;
        r = x.b().compareTo(y.b());
        if (r != 0) return r;
        r = x.c().compareTo(y.c());
        if (r != 0) return r;
        if (x.rc() == null && y.rc() == null) return 0;
        if (x.rc() == null) return 1;
        if (y.rc() == null) return -1;
        return x.rc().compareTo(y.rc());
    }

    private static BigInteger num(String s) {
        if (s == null || s.isEmpty()) return null;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch < '0' || ch > '9') return null;
        }
        if (s.length() > 1 && s.charAt(0) == '0') return null;
        return new BigInteger(s);
    }

    private static Ver parse(String s) {
        if (s == null) return null;
        String core = s;
        BigInteger rc = null;
        int t = s.indexOf('~');
        if (t >= 0) {
            core = s.substring(0, t);
            String suf = s.substring(t + 1);
            if (!suf.startsWith("rc")) return null;
            rc = num(suf.substring(2));
            if (rc == null || rc.signum() < 1) return null;
        }
        String[] p = core.split("\\.", -1);
        if (p.length != 3) return null;
        BigInteger a = num(p[0]), b = num(p[1]), c = num(p[2]);
        if (a == null || b == null || c == null) return null;
        return new Ver(a, b, c, rc);
    }

    private static String strip(String s) {
        int i = 0, j = s.length();
        while (i < j && s.charAt(i) == ' ') i++;
        while (j > i && s.charAt(j - 1) == ' ') j--;
        return s.substring(i, j);
    }

    private static Predicate<Ver> parseClause(String cl) {
        if (cl.equals("*")) return v -> true;
        if (cl.startsWith("!=")) {
            Ver w = parse(cl.substring(2));
            if (w == null) return null;
            return v -> cmp(v, w) != 0;
        }
        if (cl.startsWith(">=")) {
            Ver w = parse(cl.substring(2));
            if (w == null) return null;
            return v -> cmp(v, w) >= 0;
        }
        if (cl.startsWith("<=")) {
            Ver w = parse(cl.substring(2));
            if (w == null) return null;
            return v -> cmp(v, w) <= 0;
        }
        if (cl.startsWith(">")) {
            Ver w = parse(cl.substring(1));
            if (w == null) return null;
            return v -> cmp(v, w) > 0;
        }
        if (cl.startsWith("<")) {
            Ver w = parse(cl.substring(1));
            if (w == null) return null;
            return v -> cmp(v, w) < 0;
        }
        if (cl.startsWith("=")) {
            Ver w = parse(cl.substring(1));
            if (w == null) return null;
            return v -> cmp(v, w) == 0;
        }
        if (cl.startsWith("@")) {
            String[] p = cl.substring(1).split("\\.", -1);
            if (p.length != 2) return null;
            BigInteger x = num(p[0]), y = num(p[1]);
            if (x == null || y == null) return null;
            return v -> v.a().equals(x) && v.b().compareTo(y) >= 0;
        }
        if (cl.endsWith(".*")) {
            String[] p = cl.substring(0, cl.length() - 2).split("\\.", -1);
            if (p.length == 1) {
                BigInteger x = num(p[0]);
                if (x == null) return null;
                return v -> v.a().equals(x);
            } else if (p.length == 2) {
                BigInteger x = num(p[0]), y = num(p[1]);
                if (x == null || y == null) return null;
                return v -> v.a().equals(x) && v.b().equals(y);
            }
            return null;
        }
        Ver w = parse(cl);
        if (w == null) return null;
        return v -> cmp(v, w) == 0;
    }

    public static String pickVersion(List<String> available, String constraint) {
        if (available == null) throw new IllegalArgumentException("available must be a list");
        List<Ver> vers = new ArrayList<>();
        for (int i = 0; i < available.size(); i++) {
            String e = available.get(i);
            Ver v = parse(e);
            if (v == null) throw new IllegalArgumentException("invalid version at index " + i + ": " + e);
            vers.add(v);
        }
        if (constraint == null) throw new IllegalArgumentException("constraint must be a str");
        if (strip(constraint).isEmpty()) throw new IllegalArgumentException("empty constraint");
        String[] alts = constraint.split("\\|", -1);
        List<Alt> parsed = new ArrayList<>();
        for (int ai = 0; ai < alts.length; ai++) {
            String alt = strip(alts[ai]);
            boolean allow = false;
            if (alt.startsWith("?")) {
                allow = true;
                alt = strip(alt.substring(1));
            }
            if (alt.isEmpty()) throw new IllegalArgumentException("alternative " + (ai + 1) + " is empty");
            String[] cls = alt.split(",", -1);
            List<Predicate<Ver>> preds = new ArrayList<>();
            for (int ci = 0; ci < cls.length; ci++) {
                String cl = strip(cls[ci]);
                Predicate<Ver> p = parseClause(cl);
                if (p == null) {
                    throw new IllegalArgumentException("alternative " + (ai + 1) + ", clause " + (ci + 1)
                            + ": invalid clause '" + cl + "'");
                }
                preds.add(p);
            }
            parsed.add(new Alt(allow, preds));
        }
        Ver best = null;
        String bestS = null;
        for (int i = 0; i < vers.size(); i++) {
            Ver v = vers.get(i);
            boolean ok = false;
            for (Alt a : parsed) {
                if (v.rc() != null && !a.allowRc()) continue;
                boolean all = true;
                for (Predicate<Ver> p : a.clauses()) {
                    if (!p.test(v)) { all = false; break; }
                }
                if (all) { ok = true; break; }
            }
            if (ok && (best == null || cmp(v, best) > 0)) {
                best = v;
                bestS = available.get(i);
            }
        }
        return bestS;
    }
}

#include <string>
#include <vector>
#include <optional>
#include <stdexcept>
#include <algorithm>
#include <tuple>

namespace {

struct Ver {
    std::string x, y, z;
    bool rc = false;
    std::string n; // valid if rc
};

bool validNum(const std::string& s) {
    if (s.empty()) return false;
    for (char c : s) if (c < '0' || c > '9') return false;
    if (s.size() > 1 && s[0] == '0') return false;
    return true;
}

int cmpNum(const std::string& a, const std::string& b) {
    if (a.size() != b.size()) return a.size() < b.size() ? -1 : 1;
    int c = a.compare(b);
    return c < 0 ? -1 : (c > 0 ? 1 : 0);
}

std::vector<std::string> splitOn(const std::string& s, char d) {
    std::vector<std::string> r;
    std::string cur;
    for (char c : s) {
        if (c == d) { r.push_back(cur); cur.clear(); }
        else cur += c;
    }
    r.push_back(cur);
    return r;
}

bool parseVer(const std::string& s, Ver& v) {
    std::string base = s;
    v = Ver();
    size_t t = s.find('~');
    if (t != std::string::npos) {
        base = s.substr(0, t);
        std::string suf = s.substr(t + 1);
        if (suf.size() < 3 || suf.compare(0, 2, "rc") != 0) return false;
        std::string n = suf.substr(2);
        if (!validNum(n) || n == "0") return false;
        v.rc = true;
        v.n = n;
    }
    auto parts = splitOn(base, '.');
    if (parts.size() != 3) return false;
    for (auto& p : parts) if (!validNum(p)) return false;
    v.x = parts[0]; v.y = parts[1]; v.z = parts[2];
    return true;
}

int cmpVer(const Ver& a, const Ver& b) {
    int c;
    if ((c = cmpNum(a.x, b.x))) return c;
    if ((c = cmpNum(a.y, b.y))) return c;
    if ((c = cmpNum(a.z, b.z))) return c;
    if (a.rc != b.rc) return a.rc ? -1 : 1;
    if (a.rc) return cmpNum(a.n, b.n);
    return 0;
}

std::string repr(const std::string& s) {
    bool hasS = s.find('\'') != std::string::npos;
    bool hasD = s.find('"') != std::string::npos;
    char q = (hasS && !hasD) ? '"' : '\'';
    std::string r(1, q);
    for (char c : s) {
        if (c == '\\') r += "\\\\";
        else if (c == '\n') r += "\\n";
        else if (c == '\t') r += "\\t";
        else if (c == '\r') r += "\\r";
        else if (c == q) { r += '\\'; r += c; }
        else r += c;
    }
    r += q;
    return r;
}

std::string trimSp(const std::string& s) {
    size_t a = 0, b = s.size();
    while (a < b && s[a] == ' ') a++;
    while (b > a && s[b - 1] == ' ') b--;
    return s.substr(a, b - a);
}

enum Op { ALL, EQ, NE, GT, GE, LT, LE, MAJ, MAJMIN, AT };

struct Clause {
    Op op = ALL;
    Ver v;
    std::string a, b;
};

bool parseClause(const std::string& s, Clause& c) {
    if (s == "*") { c.op = ALL; return true; }
    if (s.empty()) return false;
    auto withVer = [&](size_t skip, Op op) {
        c.op = op;
        return parseVer(s.substr(skip), c.v);
    };
    if (s.compare(0, 2, "!=") == 0) return withVer(2, NE);
    if (s.compare(0, 2, ">=") == 0) return withVer(2, GE);
    if (s.compare(0, 2, "<=") == 0) return withVer(2, LE);
    if (s[0] == '>') return withVer(1, GT);
    if (s[0] == '<') return withVer(1, LT);
    if (s[0] == '=') return withVer(1, EQ);
    if (s[0] == '@') {
        auto parts = splitOn(s.substr(1), '.');
        if (parts.size() != 2 || !validNum(parts[0]) || !validNum(parts[1])) return false;
        c.op = AT; c.a = parts[0]; c.b = parts[1];
        return true;
    }
    if (parseVer(s, c.v)) { c.op = EQ; return true; }
    if (s.size() >= 2 && s.compare(s.size() - 2, 2, ".*") == 0) {
        auto parts = splitOn(s.substr(0, s.size() - 2), '.');
        if (parts.size() == 1 && validNum(parts[0])) {
            c.op = MAJ; c.a = parts[0]; return true;
        }
        if (parts.size() == 2 && validNum(parts[0]) && validNum(parts[1])) {
            c.op = MAJMIN; c.a = parts[0]; c.b = parts[1]; return true;
        }
    }
    return false;
}

bool clauseMatch(const Clause& c, const Ver& v) {
    switch (c.op) {
        case ALL: return true;
        case EQ: return cmpVer(v, c.v) == 0;
        case NE: return cmpVer(v, c.v) != 0;
        case GT: return cmpVer(v, c.v) > 0;
        case GE: return cmpVer(v, c.v) >= 0;
        case LT: return cmpVer(v, c.v) < 0;
        case LE: return cmpVer(v, c.v) <= 0;
        case MAJ: return cmpNum(v.x, c.a) == 0;
        case MAJMIN: return cmpNum(v.x, c.a) == 0 && cmpNum(v.y, c.b) == 0;
        case AT: return cmpNum(v.x, c.a) == 0 && cmpNum(v.y, c.b) >= 0;
    }
    return false;
}

struct Alt {
    bool allowRc = false;
    std::vector<Clause> clauses;
};

} // namespace

std::optional<std::string> pick_version(const std::vector<std::string>& available, const std::string& constraint) {
    std::vector<Ver> vers(available.size());
    for (size_t i = 0; i < available.size(); i++) {
        if (!parseVer(available[i], vers[i]))
            throw std::invalid_argument("invalid version at index " + std::to_string(i) + ": " + repr(available[i]));
    }
    if (trimSp(constraint).empty()) throw std::invalid_argument("empty constraint");
    std::vector<Alt> alts;
    auto altStrs = splitOn(constraint, '|');
    for (size_t ai = 0; ai < altStrs.size(); ai++) {
        std::string s = trimSp(altStrs[ai]);
        Alt alt;
        if (!s.empty() && s[0] == '?') {
            alt.allowRc = true;
            s = trimSp(s.substr(1));
        }
        if (s.empty())
            throw std::invalid_argument("alternative " + std::to_string(ai + 1) + " is empty");
        auto cls = splitOn(s, ',');
        for (size_t ci = 0; ci < cls.size(); ci++) {
            std::string cs = trimSp(cls[ci]);
            Clause c;
            if (!parseClause(cs, c))
                throw std::invalid_argument("alternative " + std::to_string(ai + 1) + ", clause " +
                                            std::to_string(ci + 1) + ": invalid clause " + repr(cs));
            alt.clauses.push_back(c);
        }
        alts.push_back(alt);
    }
    int best = -1;
    for (size_t i = 0; i < vers.size(); i++) {
        bool ok = false;
        for (auto& alt : alts) {
            if (vers[i].rc && !alt.allowRc) continue;
            bool all = true;
            for (auto& c : alt.clauses)
                if (!clauseMatch(c, vers[i])) { all = false; break; }
            if (all) { ok = true; break; }
        }
        if (ok && (best < 0 || cmpVer(vers[i], vers[best]) > 0)) best = (int)i;
    }
    if (best < 0) return std::nullopt;
    return available[best];
}

type Ver = { m: number; n: number; p: number; rc: number | null };

const NUM = "(0|[1-9][0-9]*)";
const VER_RE = new RegExp(`^${NUM}\\.${NUM}\\.${NUM}(?:~rc([1-9][0-9]*))?$`);
const MAJ_RE = new RegExp(`^${NUM}\\.\\*$`);
const MIN_RE = new RegExp(`^${NUM}\\.${NUM}\\.\\*$`);
const AT_RE = new RegExp(`^@${NUM}\\.${NUM}$`);

function parseVer(s: string): Ver | null {
  const r = VER_RE.exec(s);
  if (!r) return null;
  return {
    m: Number(r[1]),
    n: Number(r[2]),
    p: Number(r[3]),
    rc: r[4] === undefined ? null : Number(r[4]),
  };
}

function cmp(a: Ver, b: Ver): number {
  if (a.m !== b.m) return a.m < b.m ? -1 : 1;
  if (a.n !== b.n) return a.n < b.n ? -1 : 1;
  if (a.p !== b.p) return a.p < b.p ? -1 : 1;
  if (a.rc === b.rc) return 0;
  if (a.rc === null) return 1;
  if (b.rc === null) return -1;
  return a.rc < b.rc ? -1 : 1;
}

function stripSpaces(s: string): string {
  let i = 0;
  let j = s.length;
  while (i < j && s[i] === " ") i++;
  while (j > i && s[j - 1] === " ") j--;
  return s.slice(i, j);
}

function pyRepr(x: unknown): string {
  if (typeof x === "string") {
    let q = "'";
    if (x.includes("'") && !x.includes('"')) q = '"';
    let out = "";
    for (const ch of x) {
      if (ch === "\\") out += "\\\\";
      else if (ch === q) out += "\\" + q;
      else if (ch === "\n") out += "\\n";
      else if (ch === "\t") out += "\\t";
      else if (ch === "\r") out += "\\r";
      else out += ch;
    }
    return q + out + q;
  }
  if (x === null || x === undefined) return "None";
  if (x === true) return "True";
  if (x === false) return "False";
  if (typeof x === "number" || typeof x === "bigint") return String(x);
  try {
    const j = JSON.stringify(x);
    return j === undefined ? String(x) : j;
  } catch {
    return String(x);
  }
}

type Pred = (v: Ver) => boolean;

function parseClause(c: string): Pred | null {
  if (c === "*") return () => true;
  let r: RegExpExecArray | null;
  if ((r = MAJ_RE.exec(c))) {
    const x = Number(r[1]);
    return (v) => v.m === x;
  }
  if ((r = MIN_RE.exec(c))) {
    const x = Number(r[1]);
    const y = Number(r[2]);
    return (v) => v.m === x && v.n === y;
  }
  if ((r = AT_RE.exec(c))) {
    const x = Number(r[1]);
    const y = Number(r[2]);
    return (v) => v.m === x && v.n >= y;
  }
  let op = "";
  let rest = c;
  if (c.startsWith("!=") || c.startsWith(">=") || c.startsWith("<=")) {
    op = c.slice(0, 2);
    rest = c.slice(2);
  } else if (c.startsWith(">") || c.startsWith("<") || c.startsWith("=")) {
    op = c[0];
    rest = c.slice(1);
  }
  const t = parseVer(rest);
  if (!t) return null;
  switch (op) {
    case "":
    case "=":
      return (v) => cmp(v, t) === 0;
    case "!=":
      return (v) => cmp(v, t) !== 0;
    case ">":
      return (v) => cmp(v, t) > 0;
    case ">=":
      return (v) => cmp(v, t) >= 0;
    case "<":
      return (v) => cmp(v, t) < 0;
    case "<=":
      return (v) => cmp(v, t) <= 0;
  }
  return null;
}

export function pickVersion(available: string[], constraint: string): string | null {
  if (!Array.isArray(available)) throw new Error("available must be a list");
  const parsed: Ver[] = [];
  for (let i = 0; i < available.length; i++) {
    const e: unknown = available[i];
    const v = typeof e === "string" ? parseVer(e) : null;
    if (!v) throw new Error(`invalid version at index ${i}: ${pyRepr(e)}`);
    parsed.push(v);
  }
  if (typeof constraint !== "string") throw new Error("constraint must be a str");
  if (stripSpaces(constraint) === "") throw new Error("empty constraint");

  const alts: { rc: boolean; preds: Pred[] }[] = [];
  const parts = constraint.split("|");
  for (let a = 0; a < parts.length; a++) {
    let alt = stripSpaces(parts[a]);
    let allow = false;
    if (alt.startsWith("?")) {
      allow = true;
      alt = stripSpaces(alt.slice(1));
    }
    if (alt === "") throw new Error(`alternative ${a + 1} is empty`);
    const clauses = alt.split(",");
    const preds: Pred[] = [];
    for (let c = 0; c < clauses.length; c++) {
      const text = stripSpaces(clauses[c]);
      const p = parseClause(text);
      if (!p) {
        throw new Error(
          `alternative ${a + 1}, clause ${c + 1}: invalid clause ${pyRepr(text)}`
        );
      }
      preds.push(p);
    }
    alts.push({ rc: allow, preds });
  }

  let best = -1;
  for (let i = 0; i < parsed.length; i++) {
    const v = parsed[i];
    let ok = false;
    for (const alt of alts) {
      if (v.rc !== null && !alt.rc) continue;
      if (alt.preds.every((p) => p(v))) {
        ok = true;
        break;
      }
    }
    if (ok && (best < 0 || cmp(v, parsed[best]) > 0)) best = i;
  }
  return best < 0 ? null : available[best];
}

