import "sort"

type Tuple1 struct {
	F0 string
	F1 int
}

func LeaderboardRanks(submissions []Tuple1) []int {
	n := len(submissions)
	res := make([]int, n)
	if n == 0 {
		return res
	}
	order := make([]int, n)
	for i := range order {
		order[i] = i
	}
	sort.Slice(order, func(a, b int) bool {
		x, y := order[a], order[b]
		if submissions[x].F1 != submissions[y].F1 {
			return submissions[x].F1 > submissions[y].F1
		}
		return x < y
	})
	pos := make([]int, n)
	for r, idx := range order {
		pos[idx] = r + 1
	}
	tree := make([]int, n+2)
	update := func(i, v int) {
		for ; i <= n; i += i & (-i) {
			tree[i] += v
		}
	}
	query := func(i int) int {
		s := 0
		for ; i > 0; i -= i & (-i) {
			s += tree[i]
		}
		return s
	}
	ids := make(map[string]int)
	best := []int{}
	slot := []int{}
	for i, s := range submissions {
		id, ok := ids[s.F0]
		if !ok {
			id = len(best)
			ids[s.F0] = id
			best = append(best, s.F1)
			slot = append(slot, pos[i])
			update(pos[i], 1)
		} else if s.F1 > best[id] {
			update(slot[id], -1)
			best[id] = s.F1
			slot[id] = pos[i]
			update(pos[i], 1)
		}
		res[i] = 1 + query(slot[id]-1)
	}
	return res
}

import java.util.*;

public final class Solution {
    public record Tuple1(String f0, long f1) {}

    public static List<Long> leaderboardRanks(List<Tuple1> submissions) {
        int n = submissions.size();
        List<Long> res = new ArrayList<>(n);
        if (n == 0) return res;
        long[] keys = new long[n];
        for (int i = 0; i < n; i++) {
            long s = submissions.get(i).f1();
            keys[i] = ((1_000_000_000L - s) << 18) | i;
        }
        Arrays.sort(keys);
        int[] pos = new int[n];
        for (int r = 0; r < n; r++) {
            int idx = (int) (keys[r] & ((1 << 18) - 1));
            pos[idx] = r + 1;
        }
        int[] bit = new int[n + 2];
        HashMap<String, Integer> ids = new HashMap<>();
        int[] best = new int[n];
        int cnt = 0;
        for (int i = 0; i < n; i++) {
            Tuple1 t = submissions.get(i);
            Integer id = ids.get(t.f0());
            int p;
            if (id == null) {
                p = cnt++;
                ids.put(t.f0(), p);
                best[p] = i;
                for (int x = pos[i]; x <= n; x += x & -x) bit[x]++;
            } else {
                p = id;
                int b = best[p];
                if (t.f1() > submissions.get(b).f1()) {
                    for (int x = pos[b]; x <= n; x += x & -x) bit[x]--;
                    best[p] = i;
                    for (int x = pos[i]; x <= n; x += x & -x) bit[x]++;
                }
            }
            long sum = 0;
            for (int x = pos[best[p]]; x > 0; x -= x & -x) sum += bit[x];
            res.add(sum);
        }
        return res;
    }
}

