std::vector<long long> leaderboard_ranks(const std::vector<std::tuple<std::string, long long>>& submissions) {
    int n = (int)submissions.size();
    std::vector<long long> res(n);
    if (n == 0) return res;
    std::vector<int> order(n);
    std::iota(order.begin(), order.end(), 0);
    std::sort(order.begin(), order.end(), [&](int a, int b) {
        long long sa = std::get<1>(submissions[a]);
        long long sb = std::get<1>(submissions[b]);
        if (sa != sb) return sa > sb;
        return a < b;
    });
    std::vector<int> pos(n);
    for (int k = 0; k < n; k++) pos[order[k]] = k + 1;
    std::vector<int> bit(n + 1, 0);
    auto upd = [&](int i, int v) {
        for (; i <= n; i += i & -i) bit[i] += v;
    };
    auto qry = [&](int i) {
        int r = 0;
        for (; i > 0; i -= i & -i) r += bit[i];
        return r;
    };
    std::unordered_map<std::string, int> ids;
    ids.reserve(n * 2);
    std::vector<long long> best;
    std::vector<int> bt;
    for (int i = 0; i < n; i++) {
        const std::string& p = std::get<0>(submissions[i]);
        long long s = std::get<1>(submissions[i]);
        auto it = ids.find(p);
        int id;
        if (it == ids.end()) {
            id = (int)best.size();
            ids.emplace(p, id);
            best.push_back(s);
            bt.push_back(i);
            upd(pos[i], 1);
        } else {
            id = it->second;
            if (s > best[id]) {
                upd(pos[bt[id]], -1);
                best[id] = s;
                bt[id] = i;
                upd(pos[i], 1);
            }
        }
        res[i] = qry(pos[bt[id]]);
    }
    return res;
}

export function leaderboardRanks(submissions: [string, number][]): number[] {
  const n = submissions.length;
  const res: number[] = new Array(n);
  if (n === 0) return res;
  const idx = new Array<number>(n);
  for (let i = 0; i < n; i++) idx[i] = i;
  idx.sort((a, b) => {
    const d = submissions[b][1] - submissions[a][1];
    return d !== 0 ? d : a - b;
  });
  const pos = new Int32Array(n);
  for (let k = 0; k < n; k++) pos[idx[k]] = k + 1;
  const tree = new Int32Array(n + 2);
  const update = (i: number, v: number) => {
    for (; i <= n; i += i & -i) tree[i] += v;
  };
  const query = (i: number) => {
    let s = 0;
    for (; i > 0; i -= i & -i) s += tree[i];
    return s;
  };
  const ids = new Map<string, number>();
  const bestIdx: number[] = [];
  for (let i = 0; i < n; i++) {
    const [name, score] = submissions[i];
    let id = ids.get(name);
    if (id === undefined) {
      id = bestIdx.length;
      ids.set(name, id);
      bestIdx.push(-1);
    }
    const b = bestIdx[id];
    if (b === -1) {
      update(pos[i], 1);
      bestIdx[id] = i;
    } else if (score > submissions[b][1]) {
      update(pos[b], -1);
      update(pos[i], 1);
      bestIdx[id] = i;
    }
    res[i] = query(pos[bestIdx[id]] - 1) + 1;
  }
  return res;
}

