import "sort"

type Tuple1 struct {
	F0 int
	F1 int
	F2 int
}

type Tuple2 struct {
	F0 int
	F1 int
}

func BudgetPurchases(prices []int, queries []Tuple1) []Tuple2 {
	res := make([]Tuple2, len(queries))
	n := len(prices)
	if len(queries) == 0 || n == 0 {
		return res
	}
	idx := make([]int, n)
	for i := range idx {
		idx[i] = i
	}
	sort.Slice(idx, func(a, b int) bool {
		if prices[idx[a]] != prices[idx[b]] {
			return prices[idx[a]] < prices[idx[b]]
		}
		return idx[a] < idx[b]
	})
	rank := make([]int, n)
	for r, p := range idx {
		rank[p] = r
	}
	total := n*20 + 10
	L := make([]int32, 1, total)
	R := make([]int32, 1, total)
	cnt := make([]int32, 1, total)
	sum := make([]int64, 1, total)

	var insert func(prev int32, lo, hi, pos int, val int64) int32
	insert = func(prev int32, lo, hi, pos int, val int64) int32 {
		L = append(L, L[prev])
		R = append(R, R[prev])
		cnt = append(cnt, cnt[prev]+1)
		sum = append(sum, sum[prev]+val)
		cur := int32(len(L) - 1)
		if lo < hi {
			mid := (lo + hi) / 2
			if pos <= mid {
				c := insert(L[prev], lo, mid, pos, val)
				L[cur] = c
			} else {
				c := insert(R[prev], mid+1, hi, pos, val)
				R[cur] = c
			}
		}
		return cur
	}
	roots := make([]int32, n+1)
	for i := 0; i < n; i++ {
		roots[i+1] = insert(roots[i], 0, n-1, rank[i], int64(prices[i]))
	}
	for qi, q := range queries {
		a := roots[q.F1+1]
		b := roots[q.F0]
		budget := int64(q.F2)
		lo, hi := 0, n-1
		var count int
		var spent int64
		for lo < hi {
			mid := (lo + hi) / 2
			lc := cnt[L[a]] - cnt[L[b]]
			ls := sum[L[a]] - sum[L[b]]
			if ls <= budget {
				budget -= ls
				count += int(lc)
				spent += ls
				a = R[a]
				b = R[b]
				lo = mid + 1
			} else {
				a = L[a]
				b = L[b]
				hi = mid
			}
		}
		c := cnt[a] - cnt[b]
		s := sum[a] - sum[b]
		if c > 0 && s <= budget {
			count += int(c)
			spent += s
		}
		res[qi] = Tuple2{count, int(spent)}
	}
	return res
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1, long f2) {}

    public record Tuple2(long f0, long f1) {}

    static int[] L, R, C;
    static long[] S;
    static int tot;

    static int insert(int prev, int lo, int hi, int pos, long val) {
        int cur = ++tot;
        L[cur] = L[prev];
        R[cur] = R[prev];
        C[cur] = C[prev] + 1;
        S[cur] = S[prev] + val;
        if (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (pos <= mid) {
                L[cur] = insert(L[prev], lo, mid, pos, val);
            } else {
                R[cur] = insert(R[prev], mid + 1, hi, pos, val);
            }
        }
        return cur;
    }

    public static List<Tuple2> budgetPurchases(List<Long> prices, List<Tuple1> queries) {
        List<Tuple2> res = new ArrayList<>();
        int n = prices.size();
        if (queries.isEmpty()) return res;
        long[] p = new long[n];
        for (int i = 0; i < n; i++) p[i] = prices.get(i);
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> p[a] != p[b] ? Long.compare(p[a], p[b]) : Integer.compare(a, b));
        int[] rank = new int[n];
        for (int i = 0; i < n; i++) rank[idx[i]] = i;
        int size = n * 20 + 10;
        L = new int[size];
        R = new int[size];
        C = new int[size];
        S = new long[size];
        tot = 0;
        int[] root = new int[n + 1];
        for (int i = 0; i < n; i++) {
            root[i + 1] = insert(root[i], 0, n - 1, rank[i], p[i]);
        }
        for (Tuple1 q : queries) {
            int l = (int) q.f0();
            int r = (int) q.f1();
            long budget = q.f2();
            long rem = budget;
            long count = 0;
            int a = root[r + 1], b = root[l];
            int lo = 0, hi = n - 1;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                long ls = S[L[a]] - S[L[b]];
                if (ls <= rem) {
                    rem -= ls;
                    count += C[L[a]] - C[L[b]];
                    a = R[a];
                    b = R[b];
                    lo = mid + 1;
                } else {
                    a = L[a];
                    b = L[b];
                    hi = mid;
                }
            }
            if (C[a] - C[b] > 0 && S[a] - S[b] <= rem) {
                rem -= S[a] - S[b];
                count += C[a] - C[b];
            }
            res.add(new Tuple2(count, budget - rem));
        }
        return res;
    }
}

