std::vector<std::tuple<long long, long long>> budget_purchases(const std::vector<long long>& prices, const std::vector<std::tuple<long long, long long, long long>>& queries) {
    std::vector<std::tuple<long long, long long>> res;
    int n = (int)prices.size();
    if (queries.empty() || n == 0) {
        for (size_t i = 0; i < queries.size(); i++) res.emplace_back(0, 0);
        return res;
    }
    std::vector<int> ord(n);
    std::iota(ord.begin(), ord.end(), 0);
    std::sort(ord.begin(), ord.end(), [&](int a, int b) {
        if (prices[a] != prices[b]) return prices[a] < prices[b];
        return a < b;
    });
    std::vector<int> rk(n);
    for (int i = 0; i < n; i++) rk[ord[i]] = i;
    size_t maxNodes = (size_t)n * 19 + 5;
    std::vector<int> L(maxNodes, 0), R(maxNodes, 0), C(maxNodes, 0);
    std::vector<long long> S(maxNodes, 0);
    int tot = 1;
    std::vector<int> root(n + 1, 0);
    for (int i = 0; i < n; i++) {
        int pos = rk[i];
        long long p = prices[i];
        int prev = root[i];
        int cur = tot++;
        root[i + 1] = cur;
        int lo = 0, hi = n - 1;
        while (true) {
            C[cur] = C[prev] + 1;
            S[cur] = S[prev] + p;
            if (lo == hi) break;
            int mid = (lo + hi) / 2;
            int nn = tot++;
            if (pos <= mid) {
                L[cur] = nn;
                R[cur] = R[prev];
                prev = L[prev];
                hi = mid;
            } else {
                R[cur] = nn;
                L[cur] = L[prev];
                prev = R[prev];
                lo = mid + 1;
            }
            cur = nn;
        }
    }
    for (const auto& q : queries) {
        long long l = std::get<0>(q), r = std::get<1>(q), b = std::get<2>(q);
        int a = root[r + 1], c = root[l];
        long long count = 0, spent = 0;
        int lo = 0, hi = n - 1;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            long long s = S[L[a]] - S[L[c]];
            long long cn = C[L[a]] - C[L[c]];
            if (s <= b) {
                b -= s;
                count += cn;
                spent += s;
                a = R[a];
                c = R[c];
                lo = mid + 1;
            } else {
                a = L[a];
                c = L[c];
                hi = mid;
            }
        }
        long long s = S[a] - S[c];
        long long cn = C[a] - C[c];
        if (cn == 1 && s <= b) {
            count += 1;
            spent += s;
        }
        res.emplace_back(count, spent);
    }
    return res;
}

export function budgetPurchases(prices: number[], queries: [number, number, number][]): [number, number][] {
  const n = prices.length;
  const res: [number, number][] = [];
  if (queries.length === 0) return res;
  const idx: number[] = new Array(n);
  for (let i = 0; i < n; i++) idx[i] = i;
  idx.sort((a, b) => prices[a] - prices[b] || a - b);
  const rank = new Int32Array(n);
  for (let k = 0; k < n; k++) rank[idx[k]] = k;

  const depth = Math.ceil(Math.log2(Math.max(n, 2))) + 2;
  const maxNodes = n * depth + 5;
  const L = new Int32Array(maxNodes);
  const R = new Int32Array(maxNodes);
  const C = new Int32Array(maxNodes);
  const S = new Float64Array(maxNodes);
  let tot = 1;

  function insert(prev: number, lo: number, hi: number, pos: number, price: number): number {
    const id = tot++;
    L[id] = L[prev];
    R[id] = R[prev];
    C[id] = C[prev] + 1;
    S[id] = S[prev] + price;
    if (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (pos <= mid) L[id] = insert(L[prev], lo, mid, pos, price);
      else R[id] = insert(R[prev], mid + 1, hi, pos, price);
    }
    return id;
  }

  const roots = new Int32Array(n + 1);
  for (let i = 0; i < n; i++) {
    roots[i + 1] = insert(roots[i], 0, n - 1, rank[i], prices[i]);
  }

  for (const [l, r, budget] of queries) {
    let a = roots[r + 1];
    let b = roots[l];
    let lo = 0, hi = n - 1;
    let rem = budget;
    let count = 0;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      const la = L[a], lb = L[b];
      const s = S[la] - S[lb];
      if (rem >= s) {
        rem -= s;
        count += C[la] - C[lb];
        a = R[a];
        b = R[b];
        lo = mid + 1;
      } else {
        a = la;
        b = lb;
        hi = mid;
      }
    }
    if (C[a] - C[b] > 0) {
      const s = S[a] - S[b];
      if (s <= rem) {
        rem -= s;
        count += C[a] - C[b];
      }
    }
    res.push([count, budget - rem]);
  }
  return res;
}

