import "sort"

type Tuple1 struct {
	F0 int
	F1 int
}

func CountRecords(levels []int, margin int, queries []Tuple1) []int {
	res := make([]int, len(queries))
	n := len(levels)
	if n == 0 || len(queries) == 0 {
		return res
	}
	nxt := make([]int32, n+1)
	nxt[n] = int32(n)
	stack := make([]int, 0, n)
	for i := n - 1; i >= 0; i-- {
		v := levels[i] + margin
		// stack values decrease with index; find first index with val < v
		p := sort.Search(len(stack), func(k int) bool {
			return levels[stack[k]] < v
		})
		k := p - 1
		if k < 0 {
			nxt[i] = int32(n)
		} else {
			nxt[i] = int32(stack[k])
		}
		for len(stack) > 0 && levels[stack[len(stack)-1]] <= levels[i] {
			stack = stack[:len(stack)-1]
		}
		stack = append(stack, i)
	}
	LOG := 1
	for (1 << LOG) <= n {
		LOG++
	}
	up := make([][]int32, LOG)
	up[0] = nxt
	for k := 1; k < LOG; k++ {
		up[k] = make([]int32, n+1)
		prev := up[k-1]
		cur := up[k]
		for i := 0; i <= n; i++ {
			cur[i] = prev[prev[i]]
		}
	}
	for qi, q := range queries {
		cur := int32(q.F0)
		r := int32(q.F1)
		cnt := 1
		for k := LOG - 1; k >= 0; k-- {
			t := up[k][cur]
			if t <= r {
				cur = t
				cnt += 1 << uint(k)
			}
		}
		res[qi] = cnt
	}
	return res
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1) {}

    public static List<Long> countRecords(List<Long> levels, long margin, List<Tuple1> queries) {
        List<Long> res = new ArrayList<>();
        if (queries == null || queries.isEmpty()) return res;
        int n = levels.size();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = levels.get(i);
        int LOG = 1;
        while ((1 << LOG) <= n + 1) LOG++;
        int[][] up = new int[LOG][n + 1];
        int[] stack = new int[n + 1];
        int sz = 0;
        for (int i = n - 1; i >= 0; i--) {
            long t = a[i] + margin;
            // find largest index p in [0,sz) with a[stack[p]] >= t; values decrease with p
            int lo = 0, hi = sz - 1, p = -1;
            while (lo <= hi) {
                int mid = (lo + hi) >>> 1;
                if (a[stack[mid]] >= t) {
                    p = mid;
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
            up[0][i] = p < 0 ? n : stack[p];
            while (sz > 0 && a[stack[sz - 1]] <= a[i]) sz--;
            stack[sz++] = i;
        }
        up[0][n] = n;
        for (int k = 1; k < LOG; k++) {
            int[] prev = up[k - 1];
            int[] cur = up[k];
            for (int i = 0; i <= n; i++) {
                cur[i] = prev[prev[i]];
            }
        }
        for (Tuple1 q : queries) {
            int l = (int) q.f0();
            int r = (int) q.f1();
            int v = l;
            long count = 1;
            for (int k = LOG - 1; k >= 0; k--) {
                int nx = up[k][v];
                if (nx <= r) {
                    v = nx;
                    count += 1L << k;
                }
            }
            res.add(count);
        }
        return res;
    }
}

