std::vector<long long> count_records(const std::vector<long long>& levels, long long margin, const std::vector<std::tuple<long long, long long>>& queries) {
    int n = (int)levels.size();
    std::vector<long long> res;
    res.reserve(queries.size());
    if (queries.empty()) return res;
    int LOG = 1;
    while ((1 << LOG) <= n + 1) LOG++;
    std::vector<std::vector<int>> up(LOG, std::vector<int>(n + 1, n));
    std::vector<int> st;
    for (int i = n - 1; i >= 0; --i) {
        long long t = levels[i] + margin;
        // find largest p with levels[st[p]] >= t; values decrease with p
        int lo = 0, hi = (int)st.size(); // count of entries with value >= t
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (levels[st[mid]] >= t) lo = mid + 1;
            else hi = mid;
        }
        if (lo == 0) up[0][i] = n;
        else up[0][i] = st[lo - 1];
        while (!st.empty() && levels[st.back()] <= levels[i]) st.pop_back();
        st.push_back(i);
    }
    for (int k = 1; k < LOG; ++k) {
        for (int i = 0; i <= n; ++i) {
            up[k][i] = up[k - 1][up[k - 1][i]];
        }
    }
    for (const auto& q : queries) {
        long long l = std::get<0>(q);
        long long r = std::get<1>(q);
        int cur = (int)l;
        long long cnt = 1;
        for (int k = LOG - 1; k >= 0; --k) {
            int nx = up[k][cur];
            if (nx <= r) {
                cur = nx;
                cnt += (1LL << k);
            }
        }
        res.push_back(cnt);
    }
    return res;
}

export function countRecords(levels: number[], margin: number, queries: [number, number][]): number[] {
  const q = queries.length;
  if (q === 0) return [];
  const n = levels.length;
  const LOG = 18;
  const size = n + 1;
  const up = new Int32Array(LOG * size);
  const stack = new Int32Array(n + 1);
  let sp = 0;
  for (let i = n - 1; i >= 0; i--) {
    const target = levels[i] + margin;
    // stack[0..sp-1], values decreasing with array index; find last index with value >= target
    let lo = 0, hi = sp - 1, found = -1;
    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      if (levels[stack[mid]] >= target) {
        found = mid;
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }
    up[i] = found >= 0 ? stack[found] : n;
    while (sp > 0 && levels[stack[sp - 1]] <= levels[i]) sp--;
    stack[sp++] = i;
  }
  up[n] = n;
  for (let k = 1; k < LOG; k++) {
    const base = k * size;
    const prev = (k - 1) * size;
    for (let i = 0; i <= n; i++) {
      up[base + i] = up[prev + up[prev + i]];
    }
  }
  const res: number[] = new Array(q);
  for (let t = 0; t < q; t++) {
    const l = queries[t][0];
    const r = queries[t][1];
    let cur = l;
    let count = 1;
    for (let k = LOG - 1; k >= 0; k--) {
      const nx = up[k * size + cur];
      if (nx <= r) {
        cur = nx;
        count += 1 << k;
      }
    }
    res[t] = count;
  }
  return res;
}

package main

import (
	"errors"
	"math/big"
)

type Tuple1 struct {
	F0 string
	F1 string
	F2 string
}

func isDigits(s string) bool {
	if len(s) == 0 {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

func splitDot(s string) (string, string, bool, bool) {
	for i := 0; i < len(s); i++ {
		if s[i] == '.' {
			return s[:i], s[i+1:], true, true
		}
	}
	return s, "", false, true
}

func fmtCents(x *big.Int) string {
	s := x.String()
	for len(s) < 3 {
		s = "0" + s
	}
	return s[:len(s)-2] + "." + s[len(s)-2:]
}

func Amortize(principal string, annual_rate_pct string, months int) ([]Tuple1, error) {
	if months < 1 || months > 1200 {
		return nil, errors.New("bad months")
	}
	// principal
	ip, fp, hasDot, _ := splitDot(principal)
	if !isDigits(ip) {
		return nil, errors.New("bad principal")
	}
	if hasDot && (len(fp) < 1 || len(fp) > 2 || !isDigits(fp)) {
		return nil, errors.New("bad principal")
	}
	for len(fp) < 2 {
		fp += "0"
	}
	pc, ok := new(big.Int).SetString(ip+fp, 10)
	if !ok || pc.Sign() <= 0 {
		return nil, errors.New("bad principal")
	}
	// rate
	ir, fr, hasDot2, _ := splitDot(annual_rate_pct)
	if !isDigits(ir) {
		return nil, errors.New("bad rate")
	}
	if hasDot2 && (len(fr) < 1 || len(fr) > 6 || !isDigits(fr)) {
		return nil, errors.New("bad rate")
	}
	k := len(fr)
	a, ok := new(big.Int).SetString(ir+fr, 10)
	if !ok {
		return nil, errors.New("bad rate")
	}
	b := new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(k)), nil)
	lim := new(big.Int).Mul(b, big.NewInt(100))
	if a.Cmp(lim) > 0 {
		return nil, errors.New("rate too large")
	}
	b.Mul(b, big.NewInt(1200))
	n := big.NewInt(int64(months))

	var num, den *big.Int
	if a.Sign() == 0 {
		num = new(big.Int).Set(pc)
		den = n
	} else {
		ba := new(big.Int).Add(b, a)
		pw := new(big.Int).Exp(ba, n, nil)
		pb := new(big.Int).Exp(b, n, nil)
		num = new(big.Int).Mul(pc, a)
		num.Mul(num, pw)
		den = new(big.Int).Sub(pw, pb)
		den.Mul(den, b)
	}
	one := big.NewInt(1)
	t := new(big.Int).Add(num, den)
	t.Sub(t, one)
	pay := new(big.Int).Quo(t, den)

	bal := new(big.Int).Set(pc)
	var res []Tuple1
	for i := 1; i <= months; i++ {
		var interest *big.Int
		if a.Sign() == 0 {
			interest = new(big.Int)
		} else {
			x := new(big.Int).Mul(bal, a)
			q, r := new(big.Int).QuoRem(x, b, new(big.Int))
			r2 := new(big.Int).Lsh(r, 1)
			c := r2.Cmp(b)
			if c > 0 || (c == 0 && q.Bit(0) == 1) {
				q.Add(q, one)
			}
			interest = q
		}
		total := new(big.Int).Add(bal, interest)
		if i == months || total.Cmp(pay) <= 0 {
			res = append(res, Tuple1{fmtCents(total), fmtCents(interest), fmtCents(new(big.Int))})
			break
		}
		bal = new(big.Int).Sub(bal, new(big.Int).Sub(pay, interest))
		res = append(res, Tuple1{fmtCents(pay), fmtCents(interest), fmtCents(bal)})
	}
	return res, nil
}

import java.util.*;
import java.math.BigInteger;
import java.util.regex.*;

public final class Solution {
    public record Tuple1(String f0, String f1, String f2) {}

    private static String fmt(BigInteger c) {
        BigInteger[] qr = c.divideAndRemainder(BigInteger.valueOf(100));
        String r = qr[1].toString();
        if (r.length() < 2) r = "0" + r;
        return qr[0].toString() + "." + r;
    }

    private static BigInteger ceilDiv(BigInteger a, BigInteger b) {
        BigInteger[] qr = a.divideAndRemainder(b);
        return qr[1].signum() > 0 ? qr[0].add(BigInteger.ONE) : qr[0];
    }

    public static List<Tuple1> amortize(String principal, String annual_rate_pct, long months) {
        if (principal == null || annual_rate_pct == null) throw new IllegalArgumentException();
        if (!principal.matches("[0-9]+(\\.[0-9]{1,2})?")) throw new IllegalArgumentException();
        if (!annual_rate_pct.matches("[0-9]+(\\.[0-9]{1,6})?")) throw new IllegalArgumentException();
        if (months < 1 || months > 1200) throw new IllegalArgumentException();
        int n = (int) months;

        String ip, fp;
        int dot = principal.indexOf('.');
        if (dot < 0) { ip = principal; fp = ""; } else { ip = principal.substring(0, dot); fp = principal.substring(dot + 1); }
        while (fp.length() < 2) fp += "0";
        BigInteger pc = new BigInteger(ip + fp);
        if (pc.signum() <= 0) throw new IllegalArgumentException();

        String ir, fr;
        dot = annual_rate_pct.indexOf('.');
        if (dot < 0) { ir = annual_rate_pct; fr = ""; } else { ir = annual_rate_pct.substring(0, dot); fr = annual_rate_pct.substring(dot + 1); }
        while (fr.length() < 6) fr += "0";
        BigInteger R = new BigInteger(ir + fr);
        if (R.compareTo(BigInteger.valueOf(100_000_000L)) > 0) throw new IllegalArgumentException();

        BigInteger D = BigInteger.valueOf(1_200_000_000L);
        BigInteger pay;
        if (R.signum() == 0) {
            pay = ceilDiv(pc, BigInteger.valueOf(n));
        } else {
            BigInteger up = D.add(R).pow(n);
            BigInteger dn = D.pow(n);
            BigInteger num = pc.multiply(R).multiply(up);
            BigInteger den = D.multiply(up.subtract(dn));
            pay = ceilDiv(num, den);
        }

        List<Tuple1> res = new ArrayList<>();
        BigInteger bal = pc;
        BigInteger two = BigInteger.TWO;
        for (int t = 1; t <= n; t++) {
            BigInteger num = bal.multiply(R);
            BigInteger[] qr = num.divideAndRemainder(D);
            BigInteger q = qr[0];
            int cmp = qr[1].multiply(two).compareTo(D);
            if (cmp > 0 || (cmp == 0 && q.testBit(0))) q = q.add(BigInteger.ONE);
            BigInteger interest = q;
            BigInteger total = bal.add(interest);
            if (t == n || total.compareTo(pay) <= 0) {
                res.add(new Tuple1(fmt(total), fmt(interest), fmt(BigInteger.ZERO)));
                break;
            } else {
                bal = bal.subtract(pay.subtract(interest));
                res.add(new Tuple1(fmt(pay), fmt(interest), fmt(bal)));
            }
        }
        return res;
    }
}

#include <string>
