typedef unsigned __int128 u128;
typedef std::vector<uint32_t> Big;

static void trim(Big& a) {
    while (!a.empty() && a.back() == 0) a.pop_back();
}
static void mulSmall(Big& a, uint32_t m) {
    uint64_t carry = 0;
    for (size_t i = 0; i < a.size(); i++) {
        uint64_t cur = (uint64_t)a[i] * m + carry;
        a[i] = (uint32_t)cur;
        carry = cur >> 32;
    }
    if (carry) a.push_back((uint32_t)carry);
    trim(a);
}
static Big mulBig(const Big& a, const Big& b) {
    if (a.empty() || b.empty()) return Big();
    Big r(a.size() + b.size(), 0);
    for (size_t i = 0; i < a.size(); i++) {
        uint64_t carry = 0;
        for (size_t j = 0; j < b.size(); j++) {
            uint64_t cur = (uint64_t)a[i] * b[j] + r[i + j] + carry;
            r[i + j] = (uint32_t)cur;
            carry = cur >> 32;
        }
        size_t k = i + b.size();
        while (carry) {
            uint64_t cur = (uint64_t)r[k] + carry;
            r[k] = (uint32_t)cur;
            carry = cur >> 32;
            k++;
        }
    }
    trim(r);
    return r;
}
static Big subBig(const Big& a, const Big& b) { // a >= b
    Big r = a;
    int64_t borrow = 0;
    for (size_t i = 0; i < r.size(); i++) {
        int64_t cur = (int64_t)r[i] - borrow - (i < b.size() ? (int64_t)b[i] : 0);
        if (cur < 0) { cur += ((int64_t)1 << 32); borrow = 1; } else borrow = 0;
        r[i] = (uint32_t)cur;
    }
    trim(r);
    return r;
}
static int cmpBig(const Big& a, const Big& b) {
    if (a.size() != b.size()) return a.size() < b.size() ? -1 : 1;
    for (size_t i = a.size(); i-- > 0;) {
        if (a[i] != b[i]) return a[i] < b[i] ? -1 : 1;
    }
    return 0;
}
static Big fromU128(u128 v) {
    Big r;
    while (v) { r.push_back((uint32_t)(v & 0xFFFFFFFFu)); v >>= 32; }
    return r;
}
static std::string fmt(u128 c) {
    u128 ip = c / 100;
    int fr = (int)(c % 100);
    std::string s;
    if (ip == 0) s = "0";
    while (ip) { s += char('0' + (int)(ip % 10)); ip /= 10; }
    if (s.empty()) s = "0";
    std::reverse(s.begin(), s.end());
    s += '.';
    s += char('0' + fr / 10);
    s += char('0' + fr % 10);
    return s;
}

std::vector<std::tuple<std::string, std::string, std::string>> amortize(const std::string& principal, const std::string& annual_rate_pct, long long months) {
    if (months < 1 || months > 1200) throw std::invalid_argument("months");
    auto isd = [](char c) { return c >= '0' && c <= '9'; };
    // parse principal
    u128 Pc = 0;
    {
        const std::string& s = principal;
        size_t p = s.find('.');
        std::string ip = (p == std::string::npos) ? s : s.substr(0, p);
        std::string fp = (p == std::string::npos) ? "" : s.substr(p + 1);
        if (ip.empty()) throw std::invalid_argument("principal");
        for (char c : ip) if (!isd(c)) throw std::invalid_argument("principal");
        if (p != std::string::npos) {
            if (fp.size() < 1 || fp.size() > 2) throw std::invalid_argument("principal");
            for (char c : fp) if (!isd(c)) throw std::invalid_argument("principal");
        }
        while (fp.size() < 2) fp += '0';
        for (char c : ip) Pc = Pc * 10 + (c - '0');
        for (char c : fp) Pc = Pc * 10 + (c - '0');
        if (Pc == 0) throw std::invalid_argument("principal");
    }
    uint64_t R = 0;
    {
        const std::string& s = annual_rate_pct;
        size_t p = s.find('.');
        std::string ip = (p == std::string::npos) ? s : s.substr(0, p);
        std::string fp = (p == std::string::npos) ? "" : s.substr(p + 1);
        if (ip.empty()) throw std::invalid_argument("rate");
        for (char c : ip) if (!isd(c)) throw std::invalid_argument("rate");
        if (p != std::string::npos) {
            if (fp.size() < 1 || fp.size() > 6) throw std::invalid_argument("rate");
            for (char c : fp) if (!isd(c)) throw std::invalid_argument("rate");
        }
        size_t z = 0;
        while (z < ip.size() && ip[z] == '0') z++;
        ip = ip.substr(z);
        if (ip.size() > 3) throw std::invalid_argument("rate");
        while (fp.size() < 6) fp += '0';
        uint64_t iv = 0;
        for (char c : ip) iv = iv * 10 + (c - '0');
        uint64_t fv = 0;
        for (char c : fp) fv = fv * 10 + (c - '0');
        R = iv * 1000000ULL + fv;
        if (R > 100000000ULL) throw std::invalid_argument("rate");
    }
    const uint64_t D = 1200000000ULL;
    int n = (int)months;
    u128 PAY;
    if (R == 0) {
        PAY = (Pc + n - 1) / n;
    } else {
        Big N(1, 1), Dn(1, 1);
        for (int i = 0; i < n; i++) {
            mulSmall(N, (uint32_t)(D + R));
            mulSmall(Dn, (uint32_t)D);
        }
        Big Den = subBig(N, Dn);
        mulSmall(Den, (uint32_t)D);
        Big Num = N;
        mulSmall(Num, (uint32_t)R);
        Num = mulBig(Num, fromU128(Pc));
        u128 lo = 0, hi = 2 * Pc + 2;
        while (lo < hi) {
            u128 mid = lo + (hi - lo) / 2;
            Big prod = mulBig(Den, fromU128(mid));
            if (cmpBig(prod, Num) >= 0) hi = mid; else lo = mid + 1;
        }
        PAY = lo;
    }
    std::vector<std::tuple<std::string, std::string, std::string>> res;
    u128 bal = Pc;
    for (int t = 1; t <= n; t++) {
        u128 a = bal / D;
        u128 b = bal % D;
        u128 br = b * R;
        u128 interest = a * R + br / D;
        u128 rem = br % D;
        if (2 * rem > D) interest += 1;
        else if (2 * rem == D) { if (interest & 1) interest += 1; }
        if (t == n || bal + interest <= PAY) {
            res.emplace_back(fmt(bal + interest), fmt(interest), fmt(0));
            break;
        } else {
            bal = bal - (PAY - interest);
            res.emplace_back(fmt(PAY), fmt(interest), fmt(bal));
        }
    }
    return res;
}

export function amortize(principal: string, annual_rate_pct: string, months: number): [string, string, string][] {
  if (typeof principal !== "string" || typeof annual_rate_pct !== "string") {
    throw new Error("invalid input");
  }
  if (!/^[0-9]+(\.[0-9]{1,2})?$/.test(principal)) throw new Error("bad principal");
  if (!/^[0-9]+(\.[0-9]{1,6})?$/.test(annual_rate_pct)) throw new Error("bad rate");
  if (typeof months !== "number" || !Number.isInteger(months) || months < 1 || months > 1200) {
    throw new Error("bad months");
  }

  // principal in cents
  const [pi, pf = ""] = principal.split(".");
  const Pc = BigInt(pi) * 100n + BigInt((pf + "00").slice(0, 2));
  if (Pc <= 0n) throw new Error("principal must be > 0");

  // rate in millionths of a percent
  const [ri, rf = ""] = annual_rate_pct.split(".");
  const R = BigInt(ri) * 1000000n + BigInt((rf + "000000").slice(0, 6));
  if (R > 100000000n) throw new Error("rate too large");

  const n = months;
  const nB = BigInt(n);
  const D = 1200000000n; // m = R / D

  const ceilDiv = (a: bigint, b: bigint): bigint => (a + b - 1n) / b;

  let PAY: bigint;
  if (R === 0n) {
    PAY = ceilDiv(Pc, nB);
  } else {
    const up = (D + R) ** nB;
    const down = D ** nB;
    PAY = ceilDiv(Pc * R * up, D * (up - down));
  }

  const fmt = (c: bigint): string => {
    const ip = c / 100n;
    const fp = c % 100n;
    return ip.toString() + "." + (fp < 10n ? "0" : "") + fp.toString();
  };

  const rows: [string, string, string][] = [];
  let BAL = Pc;
  for (let t = 1; t <= n; t++) {
    const num = BAL * R;
    let q = num / D;
    const rem = num % D;
    const twice = rem * 2n;
    if (twice > D || (twice === D && (q & 1n) === 1n)) q += 1n;
    const INT = q;
    if (t === n || BAL + INT <= PAY) {
      rows.push([fmt(BAL + INT), fmt(INT), fmt(0n)]);
      break;
    }
    BAL = BAL - (PAY - INT);
    rows.push([fmt(PAY), fmt(INT), fmt(BAL)]);
  }
  return rows;
}

package main

import (
	"errors"
	"math/big"
	"strings"
)

func FormatBase(p int, q int, base int, k int) (string, error) {
	if q == 0 {
		return "", errors.New("q == 0")
	}
	if base < 2 || base > 36 {
		return "", errors.New("invalid base")
	}
	if k < 0 {
		return "", errors.New("k < 0")
	}
	neg := (p < 0) != (q < 0) && p != 0
	bp := big.NewInt(int64(p))
	bp.Abs(bp)
	bq := big.NewInt(int64(q))
	bq.Abs(bq)
	bk := new(big.Int).Exp(big.NewInt(int64(base)), big.NewInt(int64(k)), nil)
	num := new(big.Int).Mul(bp, bk)
	N, r := new(big.Int).QuoRem(num, bq, new(big.Int))
	r2 := new(big.Int).Lsh(r, 1)
	c := r2.Cmp(bq)
	if c > 0 || (c == 0 && N.Bit(0) == 1) {
		N.Add(N, big.NewInt(1))
	}
	if N.Sign() == 0 {
		return "0", nil
	}
	s := N.Text(base)
	if len(s) < k+1 {
		s = strings.Repeat("0", k+1-len(s)) + s
	}
	ip := s[:len(s)-k]
	frac := strings.TrimRight(s[len(s)-k:], "0")
	res := ip
	if len(frac) > 0 {
		res += "." + frac
	}
	if neg {
		res = "-" + res
	}
	return res, nil
}

import java.util.*;
import java.math.BigInteger;

public final class Solution {
    public static String formatBase(long p, long q, long base, long k) {
        if (q == 0 || base < 2 || base > 36 || k < 0) {
            throw new IllegalArgumentException();
        }
        boolean neg = (p < 0) != (q < 0);
        BigInteger bp = BigInteger.valueOf(p).abs();
        BigInteger bq = BigInteger.valueOf(q).abs();
        int ki = (int) k;
        BigInteger num = bp.multiply(BigInteger.valueOf(base).pow(ki));
        BigInteger[] qr = num.divideAndRemainder(bq);
        BigInteger n = qr[0];
        int c = qr[1].shiftLeft(1).compareTo(bq);
        if (c > 0 || (c == 0 && n.testBit(0))) {
            n = n.add(BigInteger.ONE);
        }
        if (n.signum() == 0) {
            return "0";
        }
        String s = n.toString((int) base);
        if (s.length() < ki + 1) {
            StringBuilder sb = new StringBuilder();
            for (int i = s.length(); i < ki + 1; i++) sb.append('0');
            sb.append(s);
            s = sb.toString();
        }
        int len = s.length();
        String ip = s.substring(0, len - ki);
        int end = len;
        while (end > len - ki && s.charAt(end - 1) == '0') end--;
        StringBuilder res = new StringBuilder();
        if (neg) res.append('-');
        res.append(ip);
        if (end > len - ki) {
            res.append('.');
            res.append(s, len - ki, end);
        }
        return res.toString();
    }
}

#include <string>
#include <vector>
#include <stdexcept>
#include <cstdint>
#include <algorithm>

std::string format_base(long long p, long long q, long long base, long long k) {
    if (q == 0 || base < 2 || base > 36 || k < 0) throw std::invalid_argument("bad");
    typedef unsigned long long u64;
    typedef unsigned __int128 u128;
    bool neg = (p < 0) != (q < 0);
    u64 ap = p < 0 ? (u64)0 - (u64)p : (u64)p;
    u64 aq = q < 0 ? (u64)0 - (u64)q : (u64)q;
    u64 I = ap / aq;
    u64 r = ap % aq;
    std::vector<unsigned char> dig((size_t)k);
    u64 b = (u64)base;
    for (long long i = 0; i < k; i++) {
        u128 t = (u128)r * b;
        u128 d = t / aq;
        r = (u64)(t - d * aq);
        dig[(size_t)i] = (unsigned char)d;
    }
    u128 twice = (u128)r * 2;
    bool up = false;
    if (twice > aq) up = true;
    else if (twice == aq) {
        bool odd;
        if (base % 2 == 0) {
            if (k > 0) odd = dig[(size_t)k - 1] & 1;
            else odd = I & 1;
        } else {
            u64 s = I & 1;
            for (auto d : dig) s += d;
            odd = s & 1;
        }
        up = odd;
    }
    if (up) {
        long long i = k - 1;
        bool carry = true;
        while (i >= 0 && carry) {
            if (dig[(size_t)i] + 1 == base) {
                dig[(size_t)i] = 0;
                i--;
            } else {
                dig[(size_t)i]++;
                carry = false;
            }
        }
        if (carry) I += 1;
    }
    // determine zero
    size_t last = dig.size(); // one past last nonzero
    while (last > 0 && dig[last - 1] == 0) last--;
    if (I == 0 && last == 0) return "0";
    const char* chars = "0123456789abcdefghijklmnopqrstuvwxyz";
    std::string res;
    if (neg) res.push_back('-');
    if (I == 0) res.push_back('0');
    else {
        std::string t;
        u64 x = I;
        while (x > 0) {
            t.push_back(chars[x % b]);
            x /= b;
        }
        std::reverse(t.begin(), t.end());
        res += t;
    }
    if (last > 0) {
        res.push_back('.');
        for (size_t i = 0; i < last; i++) res.push_back(chars[dig[i]]);
    }
    return res;
}

export function formatBase(p: number, q: number, base: number, k: number): string {
  if (q === 0) throw new Error("q == 0");
  if (!Number.isInteger(base) || base < 2 || base > 36) throw new Error("bad base");
  if (!Number.isInteger(k) || k < 0) throw new Error("bad k");

  let P = BigInt(p);
  let Q = BigInt(q);
  const neg = (P < 0n) !== (Q < 0n);
  if (P < 0n) P = -P;
  if (Q < 0n) Q = -Q;
  const B = BigInt(base);

  const powCache: bigint[] = [B]; // powCache[j] = B^(2^j)
  const pow2 = (j: number): bigint => {
    while (powCache.length <= j) {
      const last = powCache[powCache.length - 1];
      powCache.push(last * last);
    }
    return powCache[j];
  };

  const toDigits = (n: bigint, len: number): string => {
    if (len <= 600) {
      return n.toString(base).padStart(len, "0");
    }
    let j = 0;
    while ((1 << (j + 1)) < len) j++;
    const half = 1 << j; // largest power of two < len
    const pw = pow2(j);
    const hi = n / pw;
    const lo = n % pw;
    return toDigits(hi, len - half) + toDigits(lo, half);
  };

  const Bk = B ** BigInt(k);
  const num = P * Bk;
  let N = num / Q;
  const r = num % Q;
  const twice = r * 2n;
  if (twice > Q) {
    N += 1n;
  } else if (twice === Q) {
    if ((N & 1n) === 1n) N += 1n;
  }

  if (N === 0n) return "0";

  const intPart = N / Bk;
  const frac = N % Bk;
  let out = (neg ? "-" : "") + intPart.toString(base);
  if (frac !== 0n) {
    const s = toDigits(frac, k);
    let end = s.length;
    while (end > 0 && s.charCodeAt(end - 1) === 48) end--;
    out += "." + s.slice(0, end);
  }
  return out;
}

package main

import (
	"errors"
	"math/big"
	"strings"
)

func ClosestFraction(x string, max_num int, max_den int) (string, error) {
	if max_num < 0 || max_den < 1 {
		return "", errors.New("invalid bounds")
	}
	s := x
	i := 0
	neg := false
	if i < len(s) && (s[i] == '+' || s[i] == '-') {
		neg = s[i] == '-'
		i++
	}
	isD := func(c byte) bool { return c >= '0' && c <= '9' }
	st := i
	for i < len(s) && isD(s[i]) {
		i++
	}
	intPart := s[st:i]
	fracPart := ""
	if i < len(s) && s[i] == '.' {
		i++
		st2 := i
		for i < len(s) && isD(s[i]) {
			i++
		}
		fracPart = s[st2:i]
	}
	if len(intPart)+len(fracPart) == 0 {
		return "", errors.New("invalid literal")
	}
	exp := 0
	if i < len(s) && (s[i] == 'e' || s[i] == 'E') {
		i++
		eneg := false
		if i < len(s) && (s[i] == '+' || s[i] == '-') {
			eneg = s[i] == '-'
			i++
		}
		st3 := i
		for i < len(s) && isD(s[i]) {
			i++
		}
		if st3 == i {
			return "", errors.New("invalid exponent")
		}
		ed := strings.TrimLeft(s[st3:i], "0")
		if len(ed) > 7 {
			return "", errors.New("exponent too large")
		}
		for _, c := range ed {
			exp = exp*10 + int(c-'0')
		}
		if eneg {
			exp = -exp
		}
	}
	if i != len(s) {
		return "", errors.New("invalid literal")
	}
	N, ok := new(big.Int).SetString(intPart+fracPart, 10)
	if !ok {
		return "", errors.New("invalid literal")
	}
	D := big.NewInt(1)
	e := exp - len(fracPart)
	ten := big.NewInt(10)
	if e >= 0 {
		N.Mul(N, new(big.Int).Exp(ten, big.NewInt(int64(e)), nil))
	} else {
		D.Exp(ten, big.NewInt(int64(-e)), nil)
	}
	if N.Sign() == 0 || max_num == 0 {
		return "0/1", nil
	}
	M := big.NewInt(int64(max_num))
	B := big.NewInt(int64(max_den))
	out := func(a, b *big.Int) (string, error) {
		r := a.String()
		if neg && a.Sign() != 0 {
			r = "-" + r
		}
		return r + "/" + b.String(), nil
	}
	// x >= M
	if N.Cmp(new(big.Int).Mul(M, D)) >= 0 {
		return out(M, big.NewInt(1))
	}
	p0, q0 := big.NewInt(0), big.NewInt(1)
	p1, q1 := big.NewInt(1), big.NewInt(0)
	mul := func(a, b *big.Int) *big.Int { return new(big.Int).Mul(a, b) }
	for {
		if mul(p0, D).Cmp(mul(N, q0)) == 0 {
			return out(p0, q0)
		}
		if q1.Sign() > 0 && mul(p1, D).Cmp(mul(N, q1)) == 0 {
			return out(p1, q1)
		}
		mp := new(big.Int).Add(p0, p1)
		mq := new(big.Int).Add(q0, q1)
		if mp.Cmp(M) > 0 || mq.Cmp(B) > 0 {
			break
		}
		if mul(mp, D).Cmp(mul(N, mq)) <= 0 {
			num := new(big.Int).Sub(mul(N, q0), mul(p0, D))
			den := new(big.Int).Sub(mul(p1, D), mul(N, q1))
			k := new(big.Int).Quo(num, den)
			if p1.Sign() > 0 {
				t := new(big.Int).Quo(new(big.Int).Sub(M, p0), p1)
				if t.Cmp(k) < 0 {
					k = t
				}
			}
			if q1.Sign() > 0 {
				t := new(big.Int).Quo(new(big.Int).Sub(B, q0), q1)
				if t.Cmp(k) < 0 {
					k = t
				}
			}
			p0 = new(big.Int).Add(p0, mul(k, p1))
			q0 = new(big.Int).Add(q0, mul(k, q1))
		} else {
			num := new(big.Int).Sub(mul(p1, D), mul(N, q1))
			den := new(big.Int).Sub(mul(N, q0), mul(p0, D))
			k := new(big.Int).Quo(num, den)
			if p0.Sign() > 0 {
				t := new(big.Int).Quo(new(big.Int).Sub(M, p1), p0)
				if t.Cmp(k) < 0 {
					k = t
				}
			}
			if q0.Sign() > 0 {
				t := new(big.Int).Quo(new(big.Int).Sub(B, q1), q0)
				if t.Cmp(k) < 0 {
					k = t
				}
			}
			p1 = new(big.Int).Add(p1, mul(k, p0))
			q1 = new(big.Int).Add(q1, mul(k, q0))
		}
	}
	if q1.Sign() == 0 {
		return out(p0, q0)
	}
	dl := mul(new(big.Int).Sub(mul(N, q0), mul(p0, D)), q1)
	dh := mul(new(big.Int).Sub(mul(p1, D), mul(N, q1)), q0)
	c := dl.Cmp(dh)
	if c < 0 {
		return out(p0, q0)
	}
	if c > 0 {
		return out(p1, q1)
	}
	if q0.Cmp(q1) < 0 {
		return out(p0, q0)
	}
	if q1.Cmp(q0) < 0 {
		return out(p1, q1)
	}
	return out(p0, q0)
}

import java.util.*;
import java.math.BigInteger;
import java.util.regex.*;

public final class Solution {
    public static String closestFraction(String x, long max_num, long max_den) {
        if (x == null) throw new IllegalArgumentException();
        if (max_num < 0 || max_den < 1) throw new IllegalArgumentException();
        Pattern p = Pattern.compile("([+-]?)(?:([0-9]+)\\.?([0-9]*)|\\.([0-9]+))(?:[eE]([+-]?[0-9]+))?");
        Matcher m = p.matcher(x);
        if (!m.matches()) throw new IllegalArgumentException();
        boolean neg = m.group(1).equals("-");
        String ip, fp;
        if (m.group(2) != null) {
            ip = m.group(2);
            fp = m.group(3) == null ? "" : m.group(3);
        } else {
            ip = "";
            fp = m.group(4);
        }
        long exp = 0;
        if (m.group(5) != null) {
            String es = m.group(5);
            exp = new BigInteger(es).longValue();
        }
        BigInteger N = new BigInteger(ip + fp);
        long scale = fp.length() - exp;
        BigInteger D = BigInteger.ONE;
        if (scale > 0) D = BigInteger.TEN.pow((int) scale);
        else if (scale < 0) N = N.multiply(BigInteger.TEN.pow((int) (-scale)));
        BigInteger g = N.gcd(D);
        if (g.signum() != 0) {
            N = N.divide(g);
            D = D.divide(g);
        }
        BigInteger MN = BigInteger.valueOf(max_num);
        BigInteger MD = BigInteger.valueOf(max_den);
        BigInteger resNum, resDen;
        if (N.compareTo(MN.multiply(D)) >= 0) {
            resNum = MN;
            resDen = BigInteger.ONE;
        } else {
            BigInteger a = BigInteger.ZERO, b = BigInteger.ONE;
            BigInteger c = BigInteger.ONE, d = BigInteger.ZERO;
            while (true) {
                if (N.multiply(b).equals(a.multiply(D))) break;
                // move lo
                BigInteger num = N.multiply(b).subtract(a.multiply(D));
                BigInteger den = c.multiply(D).subtract(N.multiply(d));
                BigInteger k1 = num.divide(den);
                if (c.signum() > 0) k1 = k1.min(MN.subtract(a).divide(c));
                if (d.signum() > 0) k1 = k1.min(MD.subtract(b).divide(d));
                if (k1.signum() < 0) k1 = BigInteger.ZERO;
                a = a.add(k1.multiply(c));
                b = b.add(k1.multiply(d));
                if (N.multiply(b).equals(a.multiply(D))) break;
                // move hi
                BigInteger num2 = c.multiply(D).subtract(N.multiply(d)).subtract(BigInteger.ONE);
                BigInteger den2 = N.multiply(b).subtract(a.multiply(D));
                BigInteger k2 = num2.divide(den2);
                if (a.signum() > 0) k2 = k2.min(MN.subtract(c).divide(a));
                if (b.signum() > 0) k2 = k2.min(MD.subtract(d).divide(b));
                if (k2.signum() < 0) k2 = BigInteger.ZERO;
                c = c.add(k2.multiply(a));
                d = d.add(k2.multiply(b));
                if (k1.signum() == 0 && k2.signum() == 0) break;
            }
            if (N.multiply(b).equals(a.multiply(D))) {
                resNum = a;
                resDen = b;
            } else {
                BigInteger left = N.multiply(b).subtract(a.multiply(D)).multiply(d);
                BigInteger right = c.multiply(D).subtract(N.multiply(d)).multiply(b);
                int cmp = left.compareTo(right);
                boolean useLo;
                if (d.signum() == 0) {
                    useLo = true;
                } else if (cmp < 0) useLo = true;
                else if (cmp > 0) useLo = false;
                else {
                    int dc = b.compareTo(d);
                    useLo = dc <= 0;
                }
                if (useLo) {
                    resNum = a;
                    resDen = b;
                } else {
                    resNum = c;
                    resDen = d;
                }
            }
        }
        if (resNum.signum() == 0) return "0/1";
        BigInteger gg = resNum.gcd(resDen);
        resNum = resNum.divide(gg);
        resDen = resDen.divide(gg);
        return (neg ? "-" : "") + resNum + "/" + resDen;
    }
}

#include <string>
#include <vector>
#include <stdexcept>
#include <algorithm>
#include <cstdint>

namespace {
typedef std::vector<uint32_t> Big;
const uint32_t BASE = 1000000000u;

void trim(Big& a) {
    while (!a.empty() && a.back() == 0) a.pop_back();
}

Big mulSmall(const Big& a, unsigned long long m) {
    Big r;
    if (a.empty() || m == 0) return r;
    r.reserve(a.size() + 3);
    unsigned __int128 carry = 0;
    for (size_t i = 0; i < a.size(); i++) {
        unsigned __int128 cur = (unsigned __int128)a[i] * m + carry;
        r.push_back((uint32_t)(cur % BASE));
        carry = cur / BASE;
    }
    while (carry > 0) {
        r.push_back((uint32_t)(carry % BASE));
        carry /= BASE;
    }
    trim(r);
    return r;
}

int cmpBig(const Big& a, const Big& b) {
    if (a.size() != b.size()) return a.size() < b.size() ? -1 : 1;
    for (size_t i = a.size(); i-- > 0;) {
        if (a[i] != b[i]) return a[i] < b[i] ? -1 : 1;
    }
    return 0;
}

Big subBig(const Big& a, const Big& b) { // a >= b
    Big r = a;
    long long borrow = 0;
    for (size_t i = 0; i < r.size(); i++) {
        long long cur = (long long)r[i] - borrow - (i < b.size() ? (long long)b[i] : 0);
        if (cur < 0) { cur += BASE; borrow = 1; } else borrow = 0;
        r[i] = (uint32_t)cur;
    }
    trim(r);
    return r;
}

Big fromU64(unsigned long long v) {
    Big r;
    while (v > 0) { r.push_back((uint32_t)(v % BASE)); v /= BASE; }
    return r;
}

Big mulPow10(Big a, long long n) {
    while (n >= 9) { a = mulSmall(a, 1000000000ULL); n -= 9; }
    if (n > 0) {
        unsigned long long m = 1;
        for (long long i = 0; i < n; i++) m *= 10;
        a = mulSmall(a, m);
    }
    return a;
}
}

std::string closest_fraction(const std::string& x, long long max_num, long long max_den) {
    if (max_num < 0 || max_den < 1) throw std::invalid_argument("bounds");
    size_t i = 0, n = x.size();
    bool neg = false;
    if (i < n && (x[i] == '+' || x[i] == '-')) { neg = (x[i] == '-'); i++; }
    std::string digs;
    long long fracDigits = 0;
    size_t intCount = 0, fracCount = 0;
    while (i < n && x[i] >= '0' && x[i] <= '9') { digs += x[i]; i++; intCount++; }
    if (i < n && x[i] == '.') {
        i++;
        while (i < n && x[i] >= '0' && x[i] <= '9') { digs += x[i]; i++; fracCount++; }
    }
    if (intCount + fracCount == 0) throw std::invalid_argument("mantissa");
    fracDigits = (long long)fracCount;
    long long ex = 0;
    if (i < n && (x[i] == 'e' || x[i] == 'E')) {
        i++;
        bool eneg = false;
        if (i < n && (x[i] == '+' || x[i] == '-')) { eneg = (x[i] == '-'); i++; }
        size_t st = i;
        while (i < n && x[i] >= '0' && x[i] <= '9') {
            if (ex < 100000000LL) ex = ex * 10 + (x[i] - '0');
            i++;
        }
        if (i == st) throw std::invalid_argument("exponent");
        if (eneg) ex = -ex;
    }
    if (i != n) throw std::invalid_argument("trailing");

    // build D
    Big D;
    {
        size_t s = 0;
        while (s < digs.size() && digs[s] == '0') s++;
        std::string t = digs.substr(s);
        for (size_t end = t.size(); end > 0;) {
            size_t beg = end >= 9 ? end - 9 : 0;
            uint32_t v = 0;
            for (size_t j = beg; j < end; j++) v = v * 10 + (t[j] - '0');
            D.push_back(v);
            end = beg;
        }
        trim(D);
    }
    long long e10 = ex - fracDigits;
    Big P, Q;
    Q = fromU64(1);
    if (e10 >= 0) P = mulPow10(D, e10);
    else { P = D; Q = mulPow10(Q, -e10); }

    typedef unsigned long long u64;
    auto fmt = [&](u64 a, u64 b) {
        std::string s;
        if (a == 0) return std::string("0/1");
        if (neg) s += "-";
        s += std::to_string(a) + "/" + std::to_string(b);
        return s;
    };

    // x >= max_num ?
    if (cmpBig(P, mulSmall(Q, (u64)max_num)) >= 0) {
        return fmt((u64)max_num, 1);
    }

    u64 a0 = 0, b0 = 1, a1 = 1, b1 = 0;
    u64 MN = (u64)max_num, MD = (u64)max_den;
    auto xGE = [&](u64 a, u64 b) { // x >= a/b
        return cmpBig(mulSmall(P, b), mulSmall(Q, a)) >= 0;
    };
    auto xLE = [&](u64 a, u64 b) {
        return cmpBig(mulSmall(P, b), mulSmall(Q, a)) <= 0;
    };
    const u64 INF = ~0ULL;
    while (true) {
        if (a0 + a1 > MN || b0 + b1 > MD) break;
        u64 ma = a0 + a1, mb = b0 + b1;
        if (xGE(ma, mb)) {
            // move lo = lo + k*hi
            u64 kmax = INF;
            if (a1 > 0) kmax = std::min(kmax, (MN - a0) / a1);
            if (b1 > 0) kmax = std::min(kmax, (MD - b0) / b1);
            auto ok = [&](u64 k) { return xGE(a0 + k * a1, b0 + k * b1); };
            u64 good = 1, step = 1;
            u64 bad = 0;
            while (true) {
                u64 nk = good + step;
                if (nk > kmax || nk < good) { bad = (kmax == INF) ? INF : kmax + 1; break; }
                if (ok(nk)) { good = nk; step *= 2; }
                else { bad = nk; break; }
            }
            while (bad - good > 1) {
                u64 mid = good + (bad - good) / 2;
                if (ok(mid)) good = mid; else bad = mid;
            }
            a0 = a0 + good * a1;
            b0 = b0 + good * b1;
        } else {
            // move hi = hi + k*lo
            u64 kmax = INF;
            if (a0 > 0) kmax = std::min(kmax, (MN - a1) / a0);
            if (b0 > 0) kmax = std::min(kmax, (MD - b1) / b0);
            auto ok = [&](u64 k) { return xLE(a1 + k * a0, b1 + k * b0); };
            u64 good = 1, step = 1;
            u64 bad = 0;
            while (true) {
                u64 nk = good + step;
                if (nk > kmax || nk < good) { bad = (kmax == INF) ? INF : kmax + 1; break; }
                if (ok(nk)) { good = nk; step *= 2; }
                else { bad = nk; break; }
            }
            while (bad - good > 1) {
                u64 mid = good + (bad - good) / 2;
                if (ok(mid)) good = mid; else bad = mid;
            }
            a1 = a1 + good * a0;
            b1 = b1 + good * b0;
        }
    }

    // exact checks
    if (cmpBig(mulSmall(P, b0), mulSmall(Q, a0)) == 0) return fmt(a0, b0);
    if (b1 == 0) return fmt(a0, b0);
    if (cmpBig(mulSmall(P, b1), mulSmall(Q, a1)) == 0) return fmt(a1, b1);

    Big dl = subBig(mulSmall(P, b0), mulSmall(Q, a0));
    Big dh = subBig(mulSmall(Q, a1), mulSmall(P, b1));
    int c = cmpBig(mulSmall(dl, b1), mulSmall(dh, b0));
    if (c < 0) return fmt(a0, b0);
    if (c > 0) return fmt(a1, b1);
    if (b0 <= b1) return fmt(a0, b0);
    return fmt(a1, b1);
}

export function closestFraction(x: string, max_num: number, max_den: number): string {
  const m = /^([+-])?(\d+\.?\d*|\.\d+)(?:[eE]([+-])?(\d+))?$/.exec(x);
  if (!m) throw new Error("invalid literal");
  if (!(max_num >= 0) || !(max_den >= 1)) throw new Error("invalid bounds");
  const A = BigInt(max_num);
  const B = BigInt(max_den);
  const neg = m[1] === "-";
  const mant = m[2];
  const dot = mant.indexOf(".");
  let intPart = mant;
  let frac = "";
  if (dot >= 0) {
    intPart = mant.slice(0, dot);
    frac = mant.slice(dot + 1);
  }
  let N = BigInt((intPart + frac) || "0");
  let e = 0;
  if (m[4] !== undefined) {
    e = parseInt(m[4], 10);
    if (m[3] === "-") e = -e;
  }
  e -= frac.length;
  let D = 1n;
  if (e >= 0) N *= 10n ** BigInt(e);
  else D = 10n ** BigInt(-e);

  const fmt = (a: bigint, b: bigint): string => {
    if (a === 0n) return "0/1";
    return (neg ? "-" : "") + a.toString() + "/" + b.toString();
  };

  if (N >= A * D) return fmt(A, 1n);

  let a1 = 0n, b1 = 1n, a2 = 1n, b2 = 0n;
  const minB = (a: bigint, b: bigint) => (a < b ? a : b);
  while (true) {
    if (a1 * D === N * b1) return fmt(a1, b1);
    if (b2 > 0n && a2 * D === N * b2) return fmt(a2, b2);
    const ma = a1 + a2, mb = b1 + b2;
    if (ma > A || mb > B) break;
    if (ma * D <= N * mb) {
      const c = a2 * D - N * b2;
      let k = (N * b1 - a1 * D) / c;
      if (a2 > 0n) k = minB(k, (A - a1) / a2);
      if (b2 > 0n) k = minB(k, (B - b1) / b2);
      a1 += k * a2;
      b1 += k * b2;
    } else {
      const c = N * b1 - a1 * D;
      let k = (a2 * D - N * b2) / c;
      if (a1 > 0n) k = minB(k, (A - a2) / a1);
      if (b1 > 0n) k = minB(k, (B - b2) / b1);
      a2 += k * a1;
      b2 += k * b1;
    }
  }
  if (b2 === 0n) return fmt(a1, b1);
  const dl = (N * b1 - a1 * D) * b2;
  const dh = (a2 * D - N * b2) * b1;
  if (dl < dh) return fmt(a1, b1);
  if (dh < dl) return fmt(a2, b2);
  if (b1 < b2) return fmt(a1, b1);
  if (b2 < b1) return fmt(a2, b2);
  return a1 <= a2 ? fmt(a1, b1) : fmt(a2, b2);
}

package main

import (
	"errors"
	"math/big"
)

func DecimalToHalfBits(s string) (int, error) {
	i := 0
	n := len(s)
	neg := false
	if i < n && (s[i] == '+' || s[i] == '-') {
		neg = s[i] == '-'
		i++
	}
	isD := func(c byte) bool { return c >= '0' && c <= '9' }
	st := i
	for i < n && isD(s[i]) {
		i++
	}
	intPart := s[st:i]
	fracPart := ""
	if i < n && s[i] == '.' {
		i++
		st = i
		for i < n && isD(s[i]) {
			i++
		}
		fracPart = s[st:i]
	}
	if len(intPart)+len(fracPart) == 0 {
		return 0, errors.New("invalid")
	}
	var expVal int64 = 0
	if i < n && (s[i] == 'e' || s[i] == 'E') {
		i++
		eneg := false
		if i < n && (s[i] == '+' || s[i] == '-') {
			eneg = s[i] == '-'
			i++
		}
		st = i
		for i < n && isD(s[i]) {
			i++
		}
		ed := s[st:i]
		if len(ed) == 0 {
			return 0, errors.New("invalid")
		}
		k := 0
		for k < len(ed) && ed[k] == '0' {
			k++
		}
		ed = ed[k:]
		if len(ed) > 12 {
			expVal = 1000000000000
		} else {
			for j := 0; j < len(ed); j++ {
				expVal = expVal*10 + int64(ed[j]-'0')
			}
		}
		if eneg {
			expVal = -expVal
		}
	}
	if i != n {
		return 0, errors.New("invalid")
	}
	signBit := 0
	if neg {
		signBit = 0x8000
	}
	D := intPart + fracPart
	k := 0
	for k < len(D) && D[k] == '0' {
		k++
	}
	D = D[k:]
	if len(D) == 0 {
		return signBit, nil
	}
	e10 := expVal - int64(len(fracPart))
	mag := int64(len(D)) + e10
	if mag > 6 {
		return signBit | 0x7C00, nil
	}
	if mag < -8 {
		return signBit, nil
	}
	p, ok := new(big.Int).SetString(D, 10)
	if !ok {
		return 0, errors.New("invalid")
	}
	q := big.NewInt(1)
	ten := big.NewInt(10)
	if e10 >= 0 {
		p.Mul(p, new(big.Int).Exp(ten, big.NewInt(e10), nil))
	} else {
		q = new(big.Int).Exp(ten, big.NewInt(-e10), nil)
	}
	b := p.BitLen() - q.BitLen()
	// check v >= 2^b
	var ge bool
	if b >= 0 {
		ge = p.Cmp(new(big.Int).Lsh(q, uint(b))) >= 0
	} else {
		ge = new(big.Int).Lsh(p, uint(-b)).Cmp(q) >= 0
	}
	if !ge {
		b--
	}
	if b > 16 {
		return signBit | 0x7C00, nil
	}
	qe := b - 10
	if qe < -24 {
		qe = -24
	}
	num := new(big.Int).Set(p)
	den := new(big.Int).Set(q)
	if qe < 0 {
		num.Lsh(num, uint(-qe))
	} else {
		den.Lsh(den, uint(qe))
	}
	mq, rem := new(big.Int).QuoRem(num, den, new(big.Int))
	m := mq.Int64()
	rem.Lsh(rem, 1)
	c := rem.Cmp(den)
	if c > 0 || (c == 0 && m&1 == 1) {
		m++
	}
	if qe == -24 {
		return signBit | int(m), nil
	}
	if m >= 2048 {
		m = 1024
		qe++
	}
	E := qe + 25
	if E >= 31 {
		return signBit | 0x7C00, nil
	}
	return signBit | (E << 10) | int(m-1024), nil
}

import java.util.*;
import java.math.BigInteger;

public final class Solution {
    public static long decimalToHalfBits(String s) {
        if (s == null) throw new IllegalArgumentException();
        int len = s.length();
        int i = 0;
        boolean neg = false;
        if (i < len && (s.charAt(i) == '+' || s.charAt(i) == '-')) {
            neg = s.charAt(i) == '-';
            i++;
        }
        int st = i;
        while (i < len && s.charAt(i) >= '0' && s.charAt(i) <= '9') i++;
        String ip = s.substring(st, i);
        String fp = "";
        if (i < len && s.charAt(i) == '.') {
            i++;
            int fs = i;
            while (i < len && s.charAt(i) >= '0' && s.charAt(i) <= '9') i++;
            fp = s.substring(fs, i);
        }
        if (ip.isEmpty() && fp.isEmpty()) throw new IllegalArgumentException();
        long exp = 0;
        if (i < len && (s.charAt(i) == 'e' || s.charAt(i) == 'E')) {
            i++;
            boolean eneg = false;
            if (i < len && (s.charAt(i) == '+' || s.charAt(i) == '-')) {
                eneg = s.charAt(i) == '-';
                i++;
            }
            int es = i;
            while (i < len && s.charAt(i) >= '0' && s.charAt(i) <= '9') {
                if (exp < 1_000_000_000_000L) exp = exp * 10 + (s.charAt(i) - '0');
                i++;
            }
            if (i == es) throw new IllegalArgumentException();
            if (eneg) exp = -exp;
        }
        if (i != len) throw new IllegalArgumentException();

        long signBit = neg ? 0x8000L : 0L;
        String all = ip + fp;
        int a = 0;
        while (a < all.length() && all.charAt(a) == '0') a++;
        int b = all.length();
        if (a == b) return signBit;
        int tz = 0;
        while (b > a && all.charAt(b - 1) == '0') { b--; tz++; }
        String digs = all.substring(a, b);
        int n = digs.length();
        long exp10 = exp - fp.length() + tz;
        long mag = n + exp10;
        if (mag > 6) return signBit | 0x7C00L;
        if (mag < -9) return signBit;
        if (n > 60) {
            digs = digs.substring(0, 60) + "1";
            exp10 += (n - 60) - 1;
        }
        BigInteger num = new BigInteger(digs);
        BigInteger den = BigInteger.ONE;
        if (exp10 >= 0) {
            num = num.multiply(BigInteger.TEN.pow((int) exp10));
        } else {
            den = BigInteger.TEN.pow((int) (-exp10));
        }
        int k = num.bitLength() - den.bitLength();
        int cmp;
        if (k >= 0) cmp = num.compareTo(den.shiftLeft(k));
        else cmp = num.shiftLeft(-k).compareTo(den);
        if (cmp < 0) k--;
        int e = Math.max(k, -14);
        int sh = e - 10;
        if (sh >= 0) den = den.shiftLeft(sh);
        else num = num.shiftLeft(-sh);
        BigInteger[] qr = num.divideAndRemainder(den);
        long m = qr[0].longValue();
        int c = qr[1].shiftLeft(1).compareTo(den);
        if (c > 0 || (c == 0 && (m & 1) == 1)) m++;
        if (m >= 2048) {
            m = 1024;
            e++;
        }
        long pattern;
        if (e == -14 && m < 1024) {
            pattern = m;
        } else {
            long E = e + 15;
            if (E >= 31) return signBit | 0x7C00L;
            pattern = (E << 10) | (m - 1024);
        }
        return signBit | pattern;
    }
}

#include <string>
#include <stdexcept>
#include <vector>
#include <algorithm>

long long decimal_to_half_bits(const std::string& s) {
    size_t i = 0, n = s.size();
    bool neg = false;
    if (i < n && (s[i] == '+' || s[i] == '-')) {
        neg = (s[i] == '-');
        i++;
    }
    std::string ip, fp;
    while (i < n && s[i] >= '0' && s[i] <= '9') { ip.push_back(s[i]); i++; }
    if (i < n && s[i] == '.') {
        i++;
        while (i < n && s[i] >= '0' && s[i] <= '9') { fp.push_back(s[i]); i++; }
    }
    if (ip.empty() && fp.empty()) throw std::invalid_argument("bad");
    long long ex = 0;
    if (i < n && (s[i] == 'e' || s[i] == 'E')) {
        i++;
        bool eneg = false;
        if (i < n && (s[i] == '+' || s[i] == '-')) {
            eneg = (s[i] == '-');
            i++;
        }
        size_t st = i;
        while (i < n && s[i] >= '0' && s[i] <= '9') {
            ex = ex * 10 + (s[i] - '0');
            if (ex > 1000000000LL) ex = 1000000000LL;
            i++;
        }
        if (i == st) throw std::invalid_argument("bad");
        if (eneg) ex = -ex;
    }
    if (i != n) throw std::invalid_argument("bad");

    long long signbit = neg ? 0x8000 : 0;
    std::string ds = ip + fp;
    long long e10 = ex - (long long)fp.size();
    size_t lead = 0;
    while (lead < ds.size() && ds[lead] == '0') lead++;
    if (lead == ds.size()) return signbit;
    ds = ds.substr(lead);
    while (!ds.empty() && ds.back() == '0') { ds.pop_back(); e10++; }
    long long len = (long long)ds.size();
    long long top = len + e10;
    if (top > 6) return signbit | 0x7C00;
    if (top < -8) return signbit;

    const int SZ = 47;
    int A[SZ];
    for (int k = 0; k < SZ; k++) A[k] = 0;
    bool sticky = false;
    for (long long k = 0; k < len; k++) {
        long long j = 7 - top + k;
        int d = ds[k] - '0';
        if (j >= SZ) {
            if (d) sticky = true;
        } else {
            A[j] = d;
        }
    }
    unsigned long long carry = 0;
    const unsigned long long M = 1ULL << 25;
    for (int j = SZ - 1; j >= 0; j--) {
        unsigned long long v = (unsigned long long)A[j] * M + carry;
        A[j] = (int)(v % 10);
        carry = v / 10;
    }
    unsigned long long X = carry;
    for (int j = 0; j < 7; j++) X = X * 10 + A[j];
    bool f = sticky;
    for (int j = 7; j < SZ; j++) if (A[j]) f = true;

    unsigned long long thr = 65520ULL << 25;
    if (X >= thr) return signbit | 0x7C00;
    if (X == 0) return signbit;

    int bl = 0;
    {
        unsigned long long t = X;
        while (t) { bl++; t >>= 1; }
    }
    int sh = std::max(1, bl - 11);
    unsigned long long q = X >> sh;
    unsigned long long rem = X & ((1ULL << sh) - 1);
    unsigned long long half = 1ULL << (sh - 1);
    bool up = false;
    if (rem > half) up = true;
    else if (rem == half) {
        if (f || (q & 1)) up = true;
    }
    if (up) q++;
    long long bits = ((long long)std::max(bl - 12, 0) << 10) + (long long)q;
    if (bits >= 0x7C00) bits = 0x7C00;
    return signbit | bits;
}

export function decimalToHalfBits(s: string): number {
  if (typeof s !== "string") throw new Error("not a string");
  const re = /^([+-])?(?:(\d+)(?:\.(\d*))?|\.(\d+))(?:[eE]([+-])?(\d+))?$/;
  const m = re.exec(s);
  if (!m) throw new Error("invalid literal");
  const neg = m[1] === "-";
  const intPart = m[2] !== undefined ? m[2] : "";
  const fracPart = m[3] !== undefined ? m[3] : m[4] !== undefined ? m[4] : "";
  let expStr = m[6] !== undefined ? m[6] : "0";
  const expNeg = m[5] === "-";
  expStr = expStr.replace(/^0+/, "");
  let expNum: number;
  if (expStr.length === 0) expNum = 0;
  else if (expStr.length > 12) expNum = 1e12;
  else expNum = Number(expStr);
  if (expNeg) expNum = -expNum;
  const signBit = neg ? 0x8000 : 0;

  let digits = (intPart + fracPart).replace(/^0+/, "");
  if (digits.length === 0) return signBit;
  let e10 = expNum - fracPart.length;
  const n = digits.length;
  const mag = n + e10;
  if (mag >= 6) return signBit | 0x7c00;
  if (mag < -8) return signBit;

  if (e10 < -40) {
    const drop = -40 - e10;
    const dropped = digits.slice(n - drop);
    const kept = digits.slice(0, n - drop);
    const sticky = /[1-9]/.test(dropped);
    if (sticky) {
      digits = kept + "1";
      e10 = -41;
    } else {
      digits = kept;
      e10 = -40;
    }
  }
  const D = BigInt(digits);
  let q0: bigint;
  let stickyFrac = false;
  if (e10 >= 0) {
    q0 = (D * 10n ** BigInt(e10)) << 25n;
  } else {
    const N = D << 25n;
    const M = 10n ** BigInt(-e10);
    q0 = N / M;
    stickyFrac = N % M !== 0n;
  }
  if (q0 === 0n) {
    // value below 2^-25 scale; v*2^25 < 1 -> rounds to zero
    return signBit;
  }
  const L = q0.toString(2).length;
  const shift = Math.max(L - 11, 1);
  const sh = BigInt(shift);
  let mm = q0 >> sh;
  const rem = q0 & ((1n << sh) - 1n);
  const half = 1n << (sh - 1n);
  let up = false;
  if (rem > half) up = true;
  else if (rem === half) {
    if (stickyFrac || (mm & 1n) === 1n) up = true;
  }
  if (up) mm += 1n;
  const sPrime = BigInt(shift - 1);
  let bits = sPrime * 1024n + mm;
  if (bits >= 0x7c00n) bits = 0x7c00n;
  return signBit | Number(bits);
}

package main

import (
	"container/heap"
	"errors"
	"sort"
)

type Tuple1 struct {
	F0 string
	F1 int
	F2 int
	F3 int
	F4 *int
}

type Tuple2 struct {
	F0 string
	F1 int
	F2 int
}

type Tuple3 struct {
	F0 []Tuple2
	F1 []string
}

type jobHeap []Tuple1

func (h jobHeap) Len() int { return len(h) }
func (h jobHeap) Less(i, j int) bool {
	a, b := h[i], h[j]
	if a.F3 != b.F3 {
		return a.F3 > b.F3
	}
	if a.F1 != b.F1 {
		return a.F1 < b.F1
	}
	return a.F0 < b.F0
}
func (h jobHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
func (h *jobHeap) Push(x interface{}) {
	*h = append(*h, x.(Tuple1))
}
func (h *jobHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func Schedule(jobs []Tuple1) (Tuple3, error) {
	seen := make(map[string]struct{}, len(jobs))
	for _, j := range jobs {
		if _, ok := seen[j.F0]; ok {
			return Tuple3{}, errors.New("duplicate job id")
		}
		seen[j.F0] = struct{}{}
		if j.F1 < 0 {
			return Tuple3{}, errors.New("negative release time")
		}
		if j.F2 < 1 {
			return Tuple3{}, errors.New("non-positive duration")
		}
	}
	js := make([]Tuple1, len(jobs))
	copy(js, jobs)
	sort.SliceStable(js, func(a, b int) bool { return js[a].F1 < js[b].F1 })

	runs := make([]Tuple2, 0)
	dropped := make([]string, 0)
	h := &jobHeap{}
	clock := 0
	nxt := 0
	for nxt < len(js) || h.Len() > 0 {
		for nxt < len(js) && js[nxt].F1 <= clock {
			heap.Push(h, js[nxt])
			nxt++
		}
		if h.Len() == 0 {
			if js[nxt].F1 > clock {
				clock = js[nxt].F1
			}
			for nxt < len(js) && js[nxt].F1 <= clock {
				heap.Push(h, js[nxt])
				nxt++
			}
		}
		best := heap.Pop(h).(Tuple1)
		if best.F4 != nil && clock+best.F2 > *best.F4 {
			dropped = append(dropped, best.F0)
			continue
		}
		runs = append(runs, Tuple2{best.F0, clock, clock + best.F2})
		clock += best.F2
	}
	return Tuple3{runs, dropped}, nil
}

import java.util.*;

public final class Solution {
    public record Tuple1(String f0, long f1, long f2, long f3, Long f4) {}

    public record Tuple2(String f0, long f1, long f2) {}

    public record Tuple3(List<Tuple2> f0, List<String> f1) {}

    private static int cmpStr(String a, String b) {
        int i = 0, j = 0;
        int la = a.length(), lb = b.length();
        while (i < la && j < lb) {
            int ca = a.codePointAt(i);
            int cb = b.codePointAt(j);
            if (ca != cb) return Integer.compare(ca, cb);
            i += Character.charCount(ca);
            j += Character.charCount(cb);
        }
        if (i < la) return 1;
        if (j < lb) return -1;
        return 0;
    }

    public static Tuple3 schedule(List<Tuple1> jobs) {
        if (jobs == null) throw new IllegalArgumentException("jobs");
        Set<String> seen = new HashSet<>();
        List<Tuple1> list = new ArrayList<>(jobs.size());
        for (Tuple1 job : jobs) {
            if (job == null || job.f0() == null) {
                throw new IllegalArgumentException("each job must be a 5-tuple");
            }
            if (!seen.add(job.f0())) {
                throw new IllegalArgumentException("duplicate job id");
            }
            if (job.f1() < 0) throw new IllegalArgumentException("negative release");
            if (job.f2() < 1) throw new IllegalArgumentException("non-positive duration");
            list.add(job);
        }
        list.sort(Comparator.comparingLong(Tuple1::f1));

        PriorityQueue<Tuple1> ready = new PriorityQueue<>((a, b) -> {
            int c = Long.compare(b.f3(), a.f3());
            if (c != 0) return c;
            c = Long.compare(a.f1(), b.f1());
            if (c != 0) return c;
            return cmpStr(a.f0(), b.f0());
        });

        List<Tuple2> runs = new ArrayList<>();
        List<String> dropped = new ArrayList<>();
        long clock = 0;
        int nxt = 0;
        int n = list.size();
        while (nxt < n || !ready.isEmpty()) {
            if (ready.isEmpty()) {
                clock = Math.max(clock, list.get(nxt).f1());
            }
            while (nxt < n && list.get(nxt).f1() <= clock) {
                ready.add(list.get(nxt));
                nxt++;
            }
            Tuple1 best = ready.poll();
            if (best.f4() != null && clock + best.f2() > best.f4()) {
                dropped.add(best.f0());
                continue;
            }
            runs.add(new Tuple2(best.f0(), clock, clock + best.f2()));
            clock += best.f2();
        }
        return new Tuple3(runs, dropped);
    }
}

#include <vector>
#include <tuple>
#include <string>
#include <optional>
#include <queue>
#include <unordered_set>
#include <algorithm>
#include <stdexcept>
#include <numeric>

std::tuple<std::vector<std::tuple<std::string, long long, long long>>, std::vector<std::string>> schedule(const std::vector<std::tuple<std::string, long long, long long, long long, std::optional<long long>>>& jobs) {
    std::unordered_set<std::string> seen;
    for (const auto& j : jobs) {
        const std::string& id = std::get<0>(j);
        if (seen.count(id)) throw std::invalid_argument("duplicate job id");
        seen.insert(id);
        if (std::get<1>(j) < 0) throw std::invalid_argument("negative release");
        if (std::get<2>(j) < 1) throw std::invalid_argument("non-positive duration");
    }
    size_t n = jobs.size();
    std::vector<size_t> order(n);
    std::iota(order.begin(), order.end(), 0);
    std::sort(order.begin(), order.end(), [&](size_t a, size_t b) {
        return std::get<1>(jobs[a]) < std::get<1>(jobs[b]);
    });
    auto worse = [&](size_t a, size_t b) {
        // true if a has lower precedence than b
        const auto& ja = jobs[a];
        const auto& jb = jobs[b];
        if (std::get<3>(ja) != std::get<3>(jb)) return std::get<3>(ja) < std::get<3>(jb);
        if (std::get<1>(ja) != std::get<1>(jb)) return std::get<1>(ja) > std::get<1>(jb);
        return std::get<0>(ja) > std::get<0>(jb);
    };
    std::priority_queue<size_t, std::vector<size_t>, decltype(worse)> pq(worse);
    std::vector<std::tuple<std::string, long long, long long>> runs;
    std::vector<std::string> dropped;
    long long clock = 0;
    size_t nxt = 0;
    while (nxt < n || !pq.empty()) {
        if (pq.empty()) {
            clock = std::max(clock, std::get<1>(jobs[order[nxt]]));
        }
        while (nxt < n && std::get<1>(jobs[order[nxt]]) <= clock) {
            pq.push(order[nxt]);
            ++nxt;
        }
        size_t b = pq.top();
        pq.pop();
        const auto& j = jobs[b];
        long long dur = std::get<2>(j);
        const auto& dl = std::get<4>(j);
        if (dl.has_value() && clock + dur > *dl) {
            dropped.push_back(std::get<0>(j));
            continue;
        }
        runs.emplace_back(std::get<0>(j), clock, clock + dur);
        clock += dur;
    }
    return std::make_tuple(std::move(runs), std::move(dropped));
}

export function schedule(jobs: ([string, number, number, number, number | null])[]): [[string, number, number][], string[]] {
  const seen = new Set<string>();
  for (const job of jobs as unknown[]) {
    if (!Array.isArray(job) || job.length !== 5) {
      throw new Error("each job must be a 5-tuple");
    }
    const [id, release, duration] = job as [string, number, number, number, number | null];
    if (seen.has(id)) throw new Error("duplicate job id " + id);
    seen.add(id);
    if (release < 0) throw new Error("job " + id + " has a negative release time");
    if (duration < 1) throw new Error("job " + id + " has a non-positive duration");
  }

  // copy; do not modify caller's list (Array.prototype.sort is stable)
  const js = jobs.slice().sort((a, b) => a[1] - b[1]);
  const n = js.length;

  function cmpStr(a: string, b: string): number {
    if (a === b) return 0;
    const l = Math.min(a.length, b.length);
    for (let i = 0; i < l; i++) {
      let c1 = a.charCodeAt(i);
      let c2 = b.charCodeAt(i);
      if (c1 !== c2) {
        if (c1 >= 0xd800 && c2 >= 0xd800) {
          c1 = c1 >= 0xe000 ? c1 - 0x800 : c1 + 0x2000;
          c2 = c2 >= 0xe000 ? c2 - 0x800 : c2 + 0x2000;
        }
        return c1 < c2 ? -1 : 1;
      }
    }
    return a.length < b.length ? -1 : a.length > b.length ? 1 : 0;
  }

  // less(i, j): job index i ranks before j
  function less(i: number, j: number): boolean {
    const a = js[i];
    const b = js[j];
    if (a[3] !== b[3]) return a[3] > b[3];
    if (a[1] !== b[1]) return a[1] < b[1];
    return cmpStr(a[0], b[0]) < 0;
  }

  const heap: number[] = [];
  function push(x: number): void {
    let i = heap.length;
    heap.push(x);
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (less(heap[i], heap[p])) {
        const t = heap[i];
        heap[i] = heap[p];
        heap[p] = t;
        i = p;
      } else break;
    }
  }
  function pop(): number {
    const top = heap[0];
    const last = heap.pop() as number;
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      const len = heap.length;
      for (;;) {
        const l = 2 * i + 1;
        const r = l + 1;
        let m = i;
        if (l < len && less(heap[l], heap[m])) m = l;
        if (r < len && less(heap[r], heap[m])) m = r;
        if (m === i) break;
        const t = heap[i];
        heap[i] = heap[m];
        heap[m] = t;
        i = m;
      }
    }
    return top;
  }

  const runs: [string, number, number][] = [];
  const dropped: string[] = [];
  let clock = 0;
  let nxt = 0;
  while (nxt < n || heap.length > 0) {
    if (heap.length === 0) {
      clock = Math.max(clock, js[nxt][1]);
    }
    while (nxt < n && js[nxt][1] <= clock) {
      push(nxt);
      nxt++;
    }
    const best = js[pop()];
    const [id, , duration, , deadline] = best;
    if (deadline !== null && deadline !== undefined && clock + duration > deadline) {
      dropped.push(id);
      continue;
    }
    runs.push([id, clock, clock + duration]);
    clock += duration;
  }
  return [runs, dropped];
}

package main

import (
	"errors"
	"sort"
)

func WindowMedians(readings []*int, k int) ([]*int, error) {
	if k < 1 {
		return nil, errors.New("k must be a positive int")
	}
	n := len(readings)
	out := make([]*int, n)
	vals := make([]int, 0, n)
	for _, p := range readings {
		if p != nil {
			vals = append(vals, *p)
		}
	}
	sort.Ints(vals)
	u := vals[:0]
	for i, v := range vals {
		if i == 0 || v != vals[i-1] {
			u = append(u, v)
		}
	}
	vals = u
	m := len(vals)
	tree := make([]int, m+1)
	update := func(i, d int) {
		for i++; i <= m; i += i & (-i) {
			tree[i] += d
		}
	}
	top := 1
	for top*2 <= m {
		top *= 2
	}
	kth := func(t int) int {
		pos := 0
		for pw := top; pw > 0; pw >>= 1 {
			if pos+pw <= m && tree[pos+pw] < t {
				pos += pw
				t -= tree[pos]
			}
		}
		return pos
	}
	count := 0
	for i := 0; i < n; i++ {
		if readings[i] != nil {
			idx := sort.SearchInts(vals, *readings[i])
			update(idx, 1)
			count++
		}
		if i >= k && readings[i-k] != nil {
			idx := sort.SearchInts(vals, *readings[i-k])
			update(idx, -1)
			count--
		}
		if count > 0 {
			v := vals[kth((count-1)/2+1)]
			out[i] = &v
		}
	}
	return out, nil
}

import java.util.*;

public final class Solution {
    public static List<Long> windowMedians(List<Long> readings, long k) {
        if (k < 1 || readings == null) {
            throw new IllegalArgumentException("k must be a positive int");
        }
        int n = readings.size();
        Long[] arr = readings.toArray(new Long[0]);
        int c = 0;
        long[] tmp = new long[n];
        for (Long v : arr) {
            if (v != null) tmp[c++] = v;
        }
        long[] sorted = Arrays.copyOf(tmp, c);
        Arrays.sort(sorted);
        int m = 0;
        for (int i = 0; i < c; i++) {
            if (i == 0 || sorted[i] != sorted[i - 1]) sorted[m++] = sorted[i];
        }
        long[] vals = Arrays.copyOf(sorted, m);
        int[] id = new int[n];
        for (int i = 0; i < n; i++) {
            if (arr[i] == null) id[i] = -1;
            else id[i] = Arrays.binarySearch(vals, arr[i]) + 1; // 1-based
        }
        int[] tree = new int[m + 1];
        int top = 1;
        while (top * 2 <= m) top *= 2;
        int cnt = 0;
        List<Long> out = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            if (id[i] > 0) {
                for (int p = id[i]; p <= m; p += p & -p) tree[p]++;
                cnt++;
            }
            long j = (long) i - k;
            if (j >= 0 && id[(int) j] > 0) {
                for (int p = id[(int) j]; p <= m; p += p & -p) tree[p]--;
                cnt--;
            }
            if (cnt == 0) {
                out.add(null);
            } else {
                int kth = (cnt - 1) / 2 + 1;
                int pos = 0;
                for (int pw = top; pw > 0; pw >>= 1) {
                    if (pos + pw <= m && tree[pos + pw] < kth) {
                        pos += pw;
                        kth -= tree[pos];
                    }
                }
                out.add(vals[pos]);
            }
        }
        return out;
    }
}

#include <vector>
#include <optional>
#include <algorithm>
#include <stdexcept>

std::vector<std::optional<long long>> window_medians(const std::vector<std::optional<long long>>& readings, long long k) {
    if (k < 1) throw std::invalid_argument("k must be a positive int");
    size_t n = readings.size();
    std::vector<long long> vals;
    vals.reserve(n);
    for (auto& r : readings) if (r) vals.push_back(*r);
    std::sort(vals.begin(), vals.end());
    vals.erase(std::unique(vals.begin(), vals.end()), vals.end());
    int m = (int)vals.size();
    std::vector<int> tree(m + 1, 0);
    int LOG = 1;
    while (LOG * 2 <= m) LOG *= 2;

    auto upd = [&](int idx, int d) {
        for (int i = idx + 1; i <= m; i += i & -i) tree[i] += d;
    };
    auto idxOf = [&](long long v) {
        return (int)(std::lower_bound(vals.begin(), vals.end(), v) - vals.begin());
    };
    auto kth = [&](int rem) {
        int pos = 0;
        for (int pw = LOG; pw >= 1; pw >>= 1) {
            if (pos + pw <= m && tree[pos + pw] < rem) {
                pos += pw;
                rem -= tree[pos];
            }
        }
        return pos; // 0-indexed index into vals
    };

    std::vector<std::optional<long long>> out;
    out.reserve(n);
    long long total = 0;
    for (size_t i = 0; i < n; ++i) {
        if (readings[i]) {
            upd(idxOf(*readings[i]), 1);
            ++total;
        }
        if ((long long)i >= k) {
            const auto& old = readings[i - (size_t)k];
            if (old) {
                upd(idxOf(*old), -1);
                --total;
            }
        }
        if (total == 0) out.push_back(std::nullopt);
        else out.push_back(vals[kth((int)((total - 1) / 2 + 1))]);
    }
    return out;
}

export function windowMedians(readings: (number | null)[], k: number): (number | null)[] {
  if (typeof k !== "number" || !Number.isInteger(k) || k < 1) {
    throw new Error("k must be a positive int");
  }
  const n = readings.length;
  const out: (number | null)[] = [];
  if (n === 0) return out;

  const vals: number[] = [];
  for (const x of readings) if (x !== null) vals.push(x);
  vals.sort((a, b) => a - b);
  const uniq: number[] = [];
  for (const v of vals) if (uniq.length === 0 || uniq[uniq.length - 1] !== v) uniq.push(v);
  const m = uniq.length;
  const idx = new Map<number, number>();
  for (let i = 0; i < m; i++) idx.set(uniq[i], i + 1);

  const tree = new Int32Array(m + 1);
  let top = 1;
  while (top * 2 <= m) top *= 2;

  const update = (p: number, d: number) => {
    for (; p <= m; p += p & -p) tree[p] += d;
  };

  let total = 0;
  for (let i = 0; i < n; i++) {
    const x = readings[i];
    if (x !== null) {
      update(idx.get(x)!, 1);
      total++;
    }
    if (i >= k) {
      const y = readings[i - k];
      if (y !== null) {
        update(idx.get(y)!, -1);
        total--;
      }
    }
    if (total === 0) {
      out.push(null);
    } else {
      let rem = Math.floor((total - 1) / 2) + 1;
      let pos = 0;
      for (let pw = top; pw > 0; pw >>= 1) {
        const np = pos + pw;
        if (np <= m && tree[np] < rem) {
          pos = np;
          rem -= tree[np];
        }
      }
      out.push(uniq[pos]);
    }
  }
  return out;
}

import heapq

def fastest_delivery(n, roads, stations, capacity, swap_time, max_swaps, s, t):
    if s == t:
        return (0, 0)
    adj = [[] for _ in range(n)]
    for u, v, m, e in roads:
        adj[u].append((v, m, e))
    st = set(stations)
    C = capacity + 1
    K = max_swaps + 1
    INF = float('inf')
    dist = [INF] * (n * C * K)

    def idx(v, c, k):
        return (v * C + c) * K + k

    start = idx(s, capacity, 0)
    dist[start] = 0
    heap = [(0, 0, s, capacity)]
    while heap:
        d, k, v, c = heapq.heappop(heap)
        if d > dist[idx(v, c, k)]:
            continue
        if v == t:
            return (d, k)
        for w, m, e in adj[v]:
            if e > 0 and c < e:
                continue
            nc = c - e
            if nc > capacity:
                nc = capacity
            nd = d + m
            i = idx(w, nc, k)
            if nd < dist[i]:
                dist[i] = nd
                heapq.heappush(heap, (nd, k, w, nc))
        if v in st and k < max_swaps and c < capacity:
            nd = d + swap_time
            i = idx(v, capacity, k + 1)
            if nd < dist[i]:
                dist[i] = nd
                heapq.heappush(heap, (nd, k + 1, v, capacity))
    return None

def best_context(messages, budget, max_gap, bonus):
    if budget < 0 or max_gap < 0:
        raise ValueError("budget and max_gap must be non-negative")
    n = len(messages)
    NEG = -10**18
    W = budget + 1
    # dp[r][w]: best score where r = length of the trailing dropped run
    # (r = 0 means the last message was kept) and w = total length kept so far.
    dp = [[NEG] * W for _ in range(max_gap + 1)]
    dp[0][0] = 0
    for i, (L, v, pinned) in enumerate(messages):
        new = [None] * (max_gap + 1)
        # Dropping extends the trailing dropped run by one.
        if pinned:
            for r in range(max_gap + 1):
                new[r] = None
        else:
            for r in range(1, max_gap + 1):
                new[r] = dp[r - 1]
        # Keeping resets the run to 0 and earns the bonus if the previous message was kept.
        if L > budget:
            keep = [NEG] * W
        else:
            if i == 0:
                rows = [dp[0]]  # no previous message, so no bonus
            else:
                rows = [[x + bonus for x in dp[0]]] + dp[1:]
            m = list(map(max, *rows)) if len(rows) > 1 else rows[0]
            keep = [NEG] * L + [x + v for x in m[:W - L]]
        new[0] = keep
        if new[1:] and pinned:
            blank = [NEG] * W
            for r in range(1, max_gap + 1):
                new[r] = blank
        dp = new
    best = max(max(row) for row in dp)
    if best < -10**17:
        return None
    return best

def min_pruning_cost(parent, demand, cap, cut_cost, critical, root_cap, penalty):
    INF = float('inf')
    n = len(parent)
    children = [[] for _ in range(n)]
    for v in range(1, n):
        children[parent[v]].append(v)
    order = [0]
    for v in order:
        order.extend(children[v])
    S = demand[:]          # subtree demand
    hascrit = [bool(c) for c in critical]
    for v in reversed(order):
        for c in children[v]:
            S[v] += S[c]
            if hascrit[c]:
                hascrit[v] = True
    f = [None] * n
    for v in reversed(order):
        lim = root_cap if v == 0 else cap[v]
        d = demand[v]
        if d > lim:
            arr = [INF] * (lim + 1)
        else:
            arr = [INF] * (d + 1)
            arr[d] = 0
        for c in children[v]:
            h = f[c][:]
            f[c] = None
            if not hascrit[c]:
                cc = cut_cost[c] + penalty * S[c]
                if not h:
                    h = [cc]
                elif cc < h[0]:
                    h[0] = cc
            if not h:
                h = [INF]
            newlen = min(len(arr) + len(h) - 1, lim + 1)
            new = [INF] * newlen
            for i, a in enumerate(arr):
                if a == INF:
                    continue
                for k, b in enumerate(h):
                    t = i + k
                    if t >= newlen:
                        break
                    if b == INF:
                        continue
                    s = a + b
                    if s < new[t]:
                        new[t] = s
            arr = new
        if len(arr) > lim + 1:
            arr = arr[:lim + 1]
        f[v] = arr
    res = min(f[0]) if f[0] else INF
    return None if res == INF else int(res)

from bisect import bisect_left

def earliest_arrival(connections, transfer, source, target, start_time, max_boardings):
    if source == target:
        return start_time
    if max_boardings <= 0:
        return None
    INF = float('inf')

    # group by trip
    trips = {}
    for c in connections:
        trips.setdefault(c[0], []).append(c)
    n = len(transfer)
    tto = []
    tarr = []
    by_station_tmp = [[] for _ in range(n)]
    for ti, (tid, lst) in enumerate(trips.items()):
        lst.sort(key=lambda c: c[3])
        tto.append([c[2] for c in lst])
        tarr.append([c[4] for c in lst])
        for i, c in enumerate(lst):
            by_station_tmp[c[1]].append((c[3], ti, i))
    deps = []
    ent = []
    for s in range(n):
        l = by_station_tmp[s]
        l.sort()
        deps.append([e[0] for e in l])
        ent.append(l)
    ptr = [len(a) for a in tto]
    processed = [INF] * n

    ans = INF
    cand = {source: start_time}
    k = 0
    while cand and k < max_boardings:
        k += 1
        cur = cand
        cand = {}
        for x, r in cur.items():
            old = processed[x]
            if r >= old:
                continue
            processed[x] = r
            dl = deps[x]
            lo = bisect_left(dl, r)
            hi = len(dl) if old == INF else bisect_left(dl, old)
            el = ent[x]
            for j in range(lo, hi):
                _, t, i = el[j]
                p = ptr[t]
                if i < p:
                    ptr[t] = i
                    to_l = tto[t]
                    arr_l = tarr[t]
                    for m in range(i, p):
                        to = to_l[m]
                        a = arr_l[m]
                        if to == target:
                            if a < ans:
                                ans = a
                        v = a + transfer[to]
                        if v < processed[to] and v < cand.get(to, INF):
                            cand[to] = v
    return None if ans == INF else ans

import re

_NAME = re.compile(r'[a-z0-9_]+')
_WORD = re.compile(r'[a-z]+')
_SEG = re.compile(r'[a-z0-9._-]+')


def _valid_name(s):
    return isinstance(s, str) and _NAME.fullmatch(s) is not None


def _valid_word(s):
    return isinstance(s, str) and _WORD.fullmatch(s) is not None


def _parse_path(p):
    # returns list of segments or None if invalid
    if not isinstance(p, str) or not p.startswith("/"):
        return None
    if p == "/":
        return []
    segs = p[1:].split("/")
    for s in segs:
        if _SEG.fullmatch(s) is None:
            return None
    return segs


def _parse_resource(r):
    if not r.startswith("/"):
        return None
    if r == "/":
        return []
    segs = r[1:].split("/")
    for s in segs:
        if s in ("*", "**"):
            continue
        if _SEG.fullmatch(s) is None:
            return None
    return segs


def _compile(segs):
    toks = []
    for s in segs:
        if s == "**" and toks and toks[-1] == "**":
            continue
        toks.append(s)
    m = len(toks)
    dstar = 0
    single = 0
    lit = {}
    minlen = 0
    for i, t in enumerate(toks):
        if t == "**":
            dstar |= 1 << i
        else:
            minlen += 1
            if t == "*":
                single |= 1 << i
            else:
                lit[t] = lit.get(t, 0) | (1 << i)
    return (m, dstar, single, lit, minlen, dstar != 0)


def _match(comp, path_segs):
    m, dstar, single, lit, minlen, has_d = comp
    n = len(path_segs)
    if n < minlen or (not has_d and n != minlen):
        return False
    cur = 1
    cur |= (cur & dstar) << 1
    for seg in path_segs:
        mm = single | lit.get(seg, 0)
        cur = ((cur & mm) << 1) | (cur & dstar)
        cur |= (cur & dstar) << 1
        if not cur:
            return False
    return bool((cur >> m) & 1)


def evaluate_access(rules, requests):
    if not isinstance(rules, list):
        raise TypeError("rules must be a list")
    if not isinstance(requests, list):
        raise TypeError("requests must be a list")

    parsed = []
    for i, rule in enumerate(rules):
        if not isinstance(rule, str):
            raise TypeError(f"rule {i}: not a str")
        f = rule.split()
        if len(f) != 4:
            raise ValueError(f"rule {i}: expected 4 fields, got {len(f)}")
        effect, principal, action, resource = f
        if effect not in ("ALLOW", "DENY"):
            raise ValueError(f"rule {i}: bad effect {effect!r}")
        if principal == "*":
            pk, pn = 0, None
        elif principal.startswith("user:") and _NAME.fullmatch(principal[5:]):
            pk, pn = 2, principal[5:]
        elif principal.startswith("group:") and _NAME.fullmatch(principal[6:]):
            pk, pn = 1, principal[6:]
        else:
            raise ValueError(f"rule {i}: bad principal {principal!r}")
        if action == "*":
            acts = None
        else:
            words = action.split(",")
            if not all(_WORD.fullmatch(w) for w in words):
                raise ValueError(f"rule {i}: bad action {action!r}")
            acts = frozenset(words)
        segs = _parse_resource(resource)
        if segs is None:
            raise ValueError(f"rule {i}: bad resource {resource!r}")
        L = sum(1 for s in segs if s not in ("*", "**"))
        spec = (L, pk, 0 if acts is None else 1)
        parsed.append((spec, i, effect == "DENY", pk, pn, acts, _compile(segs), resource))

    reqs = []
    for j, rq in enumerate(requests):
        if not isinstance(rq, tuple) or len(rq) != 4:
            raise TypeError(f"request {j}: expected 4-tuple")
        user, groups, action, path = rq
        if not _valid_name(user):
            raise ValueError(f"request {j}: bad user {user!r}")
        if not isinstance(groups, list) or not all(_valid_name(g) for g in groups):
            raise ValueError(f"request {j}: bad groups")
        if not _valid_word(action):
            raise ValueError(f"request {j}: bad action {action!r}")
        segs = _parse_path(path)
        if segs is None:
            raise ValueError(f"request {j}: bad path {path!r}")
        reqs.append((user, set(groups), action, path, segs))

    parsed.sort(key=lambda r: (tuple(-x for x in r[0]), r[1]))
    cache = {}
    out = []
    for user, groups, action, path, segs in reqs:
        best = None
        deny_i = None
        allow_i = None
        for spec, i, is_deny, pk, pn, acts, comp, rstr in parsed:
            if best is not None and spec < best:
                break
            if pk == 2:
                if pn != user:
                    continue
            elif pk == 1:
                if pn not in groups:
                    continue
            if acts is not None and action not in acts:
                continue
            key = (rstr, path)
            r = cache.get(key)
            if r is None:
                r = _match(comp, segs)
                cache[key] = r
            if not r:
                continue
            best = spec
            if is_deny:
                if deny_i is None or i < deny_i:
                    deny_i = i
            else:
                if allow_i is None or i < allow_i:
                    allow_i = i
        if best is None:
            out.append("DENY by default")
        elif deny_i is not None:
            out.append(f"DENY by rule {deny_i}")
        else:
            out.append(f"ALLOW by rule {allow_i}")
    return out

import re
import datetime

_OPENING_RE = re.compile(r"-?(0|[1-9][0-9]{0,8})\.[0-9]{2}")
_DATE_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")
_AMOUNT_RE = re.compile(r"(0|[1-9][0-9]{0,8})(?:\.([0-9]{1,2}))?")
_KINDS = ("credit", "debit", "fee")


def _money(c):
    neg = c < 0
    i, f = divmod(abs(c), 100)
    return ("-" if neg else "") + f"{i:,}.{f:02d}"


def render_statement(opening, entries):
    if not isinstance(opening, str):
        raise TypeError("opening must be a str")
    if not _OPENING_RE.fullmatch(opening):
        raise ValueError("opening: bad amount " + repr(opening))
    if not isinstance(entries, list):
        raise TypeError("entries must be a list")

    neg = opening.startswith("-")
    ip, fp = opening.lstrip("-").split(".")
    balance = int(ip) * 100 + int(fp)
    if neg:
        balance = -balance
    opening_cents = balance

    parsed = []
    prev_date = None
    for i, e in enumerate(entries):
        if not isinstance(e, tuple) or len(e) != 4:
            raise TypeError(f"entry {i}: expected 4-tuple")
        date, kind, amount, memo = e

        ok = False
        if isinstance(date, str):
            m = _DATE_RE.fullmatch(date)
            if m:
                y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
                if 1900 <= y <= 2999:
                    try:
                        datetime.date(y, mo, d)
                        ok = True
                    except ValueError:
                        ok = False
        if not ok:
            raise ValueError(f"entry {i}: bad date {date!r}")

        if prev_date is not None and date < prev_date:
            raise ValueError(f"entry {i}: date out of order")

        if not isinstance(kind, str) or kind not in _KINDS:
            raise ValueError(f"entry {i}: bad kind {kind!r}")

        cents = None
        if isinstance(amount, str):
            m = _AMOUNT_RE.fullmatch(amount)
            if m:
                frac = (m.group(2) or "").ljust(2, "0")
                cents = int(m.group(1)) * 100 + int(frac)
                if cents == 0:
                    cents = None
        if cents is None:
            raise ValueError(f"entry {i}: bad amount {amount!r}")

        if (not isinstance(memo, str) or not memo.split()
                or any(ord(ch) < 32 or ord(ch) == 127 for ch in memo)):
            raise ValueError(f"entry {i}: bad memo")

        parsed.append((date, kind, cents, memo))
        prev_date = date

    lines = ["Opening balance: " + _money(opening_cents)]
    counts = {"credit": 0, "debit": 0, "fee": 0}
    fee_dates = set()

    def emit(date, kind, cents, memo):
        nonlocal balance
        if kind == "credit":
            balance += cents
        else:
            balance -= cents
        counts[kind] += 1
        m = " ".join(memo.split())
        if len(m) > 20:
            m = m[:19] + "~"
        m = m.ljust(20)
        amt = (("+" if kind == "credit" else "-") + _money(cents)).rjust(14)
        bal = _money(balance).rjust(15)
        flag = " OD" if balance < 0 else ""
        lines.append(f"{date}  {m}  {amt}  {bal}{flag}")

    for date, kind, cents, memo in parsed:
        emit(date, kind, cents, memo)
        if kind == "debit" and balance < 0 and date not in fee_dates:
            fee_dates.add(date)
            emit(date, "fee", 2500, "OVERDRAFT FEE")

    lines.append("Closing balance: " + _money(balance))
    lines.append(f"Credits: {counts['credit']}  Debits: {counts['debit']}  Fees: {counts['fee']}")
    return lines

from __future__ import annotations
import re

_NUM = r"(?:0|[1-9][0-9]*)"
_VER_RE = re.compile(rf"({_NUM})\.({_NUM})\.({_NUM})(?:~rc([1-9][0-9]*))?")
_MAJ_RE = re.compile(rf"({_NUM})\.\*")
_MINOR_RE = re.compile(rf"({_NUM})\.({_NUM})\.\*")
_AT_RE = re.compile(rf"@({_NUM})\.({_NUM})")


def _parse_version(s):
    """Return (key, is_rc, (x, y, z)) or None if s is not a valid version."""
    if not isinstance(s, str):
        return None
    m = _VER_RE.fullmatch(s)
    if not m:
        return None
    x, y, z = int(m.group(1)), int(m.group(2)), int(m.group(3))
    if m.group(4) is None:
        return ((x, y, z, 1, 0), False, (x, y, z))
    return ((x, y, z, 0, int(m.group(4))), True, (x, y, z))


def _parse_clause(clause):
    """Return a predicate taking (key, xyz) or None if the clause is invalid."""
    if clause == "*":
        return lambda key, xyz: True

    for op in (">=", "<=", "!=", ">", "<", "="):
        if clause.startswith(op):
            v = _parse_version(clause[len(op):])
            if v is None:
                return None
            vk = v[0]
            if op == ">=":
                return lambda key, xyz, vk=vk: key >= vk
            if op == "<=":
                return lambda key, xyz, vk=vk: key <= vk
            if op == "!=":
                return lambda key, xyz, vk=vk: key != vk
            if op == ">":
                return lambda key, xyz, vk=vk: key > vk
            if op == "<":
                return lambda key, xyz, vk=vk: key < vk
            return lambda key, xyz, vk=vk: key == vk

    v = _parse_version(clause)
    if v is not None:
        vk = v[0]
        return lambda key, xyz, vk=vk: key == vk

    m = _MAJ_RE.fullmatch(clause)
    if m:
        X = int(m.group(1))
        return lambda key, xyz, X=X: xyz[0] == X

    m = _MINOR_RE.fullmatch(clause)
    if m:
        X, Y = int(m.group(1)), int(m.group(2))
        return lambda key, xyz, X=X, Y=Y: xyz[0] == X and xyz[1] == Y

    m = _AT_RE.fullmatch(clause)
    if m:
        X, Y = int(m.group(1)), int(m.group(2))
        return lambda key, xyz, X=X, Y=Y: xyz[0] == X and xyz[1] >= Y

    return None


def pick_version(available, constraint):
    if not isinstance(available, list):
        raise TypeError("available must be a list")
    parsed = []
    for i, el in enumerate(available):
        p = _parse_version(el)
        if p is None:
            raise ValueError(f"invalid version at index {i}: {el!r}")
        parsed.append((el, p))

    if not isinstance(constraint, str):
        raise TypeError("constraint must be a str")
    if constraint.strip(" ") == "":
        raise ValueError("empty constraint")

    alternatives = []  # list of (allows_rc, [predicates])
    for a, alt in enumerate(constraint.split("|"), start=1):
        alt = alt.strip(" ")
        allows_rc = False
        if alt.startswith("?"):
            allows_rc = True
            alt = alt[1:].strip(" ")
        if alt == "":
            raise ValueError(f"alternative {a} is empty")
        preds = []
        for c, clause in enumerate(alt.split(","), start=1):
            clause = clause.strip(" ")
            pred = _parse_clause(clause)
            if pred is None:
                raise ValueError(
                    f"alternative {a}, clause {c}: invalid clause {clause!r}")
            preds.append(pred)
        alternatives.append((allows_rc, preds))

    best = None
    best_key = None
    for el, (key, is_rc, xyz) in parsed:
        ok = False
        for allows_rc, preds in alternatives:
            if is_rc and not allows_rc:
                continue
            if all(p(key, xyz) for p in preds):
                ok = True
                break
        if ok and (best_key is None or key > best_key):
            best, best_key = el, key
    return best

def leaderboard_ranks(submissions: list[tuple[str, int]]) -> list[int]:
    n = len(submissions)
    if n == 0:
        return []

    order = sorted(range(n), key=lambda i: -submissions[i][1])  # stable: ties by index
    pos = [0] * n
    for p, i in enumerate(order):
        pos[i] = p

    tree = [0] * (n + 1)

    def add(p, delta):
        p += 1
        while p <= n:
            tree[p] += delta
            p += p & -p

    def prefix(p):  # count of marked positions < p
        s = 0
        while p > 0:
            s += tree[p]
            p -= p & -p
        return s

    best_score = {}
    best_idx = {}
    res = []
    for i, (player, score) in enumerate(submissions):
        if player not in best_score:
            best_score[player] = score
            best_idx[player] = i
            add(pos[i], 1)
        elif score > best_score[player]:
            add(pos[best_idx[player]], -1)
            best_score[player] = score
            best_idx[player] = i
            add(pos[i], 1)
        res.append(1 + prefix(pos[best_idx[player]]))
    return res

import math
from decimal import Context, Decimal, MAX_EMAX, MIN_EMIN
from itertools import product

_DIG = "0123456789abcdefghijklmnopqrstuvwxyz"


def _small_to_base(v, base):
    if v == 0:
        return "0"
    out = []
    while v:
        v, r = divmod(v, base)
        out.append(_DIG[r])
    return "".join(reversed(out))


def format_base(p: int, q: int, base: int, k: int) -> str:
    if q == 0:
        raise ValueError("q must be nonzero")
    if not (2 <= base <= 36):
        raise ValueError("base must be in 2..36")
    if k < 0:
        raise ValueError("k must be >= 0")

    neg = (p < 0) != (q < 0)
    ap, aq = abs(p), abs(q)
    if ap == 0:
        return "0"

    # ---------------- power-of-two bases: pure int arithmetic ----------------
    if base & (base - 1) == 0:
        s = base.bit_length() - 1
        sh = s * k
        quo, rem = divmod(ap << sh, aq)
        twice = rem * 2
        if twice > aq or (twice == aq and (quo & 1)):
            quo += 1
        N = quo
        if N == 0:
            return "0"
        ip = N >> sh
        R = N & ((1 << sh) - 1)
        res = _small_to_base(ip, base)
        if R:
            if s == 1:
                fs = format(R, "b").zfill(k)
            elif s == 3:
                fs = format(R, "o").zfill(k)
            elif s == 4:
                fs = format(R, "x").zfill(k)
            else:
                bits = format(R, "b").zfill(sh)
                m = {format(i, "0%db" % s): _DIG[i] for i in range(base)}
                fs = "".join([m[bits[i:i + s]] for i in range(0, sh, s)])
            fs = fs.rstrip("0")
            if fs:
                res += "." + fs
        return ("-" if neg else "") + res

    # ---------------- general bases: decimal module for fast big arithmetic ----
    prec = int(k * math.log10(base)) + 1500
    ctx = Context(prec=prec, Emax=MAX_EMAX, Emin=MIN_EMIN)
    Dbase = Decimal(base)
    B = ctx.power(Dbase, k)
    num = ctx.multiply(Decimal(ap), B)
    Dq = Decimal(aq)
    quo, rem = ctx.divmod(num, Dq)
    cmp = ctx.compare(ctx.add(rem, rem), Dq)
    if cmp > 0 or (cmp == 0 and not ctx.remainder(quo, Decimal(2)).is_zero()):
        quo = ctx.add(quo, Decimal(1))
    N = quo
    if N.is_zero():
        return "0"
    ipart, R = ctx.divmod(N, B)
    sign = "-" if neg else ""

    if base == 10:
        res = format(ipart, "f")
        if not R.is_zero():
            fs = format(R, "f").zfill(k).rstrip("0")
            if fs:
                res += "." + fs
        return sign + res

    res = _small_to_base(int(ipart), base)
    if R.is_zero():
        return sign + res

    # table for small chunks
    t = 1
    while base ** (t + 1) <= 65536:
        t += 1
    Bt = base ** t
    T = list(map("".join, product(_DIG[:base], repeat=t)))

    INT_THR = 120
    DEC_LEAF = 2500
    ipow_cache = {}

    def ipow(m):
        v = ipow_cache.get(m)
        if v is None:
            v = ipow_cache[m] = base ** m
        return v

    def int_digits(v, n):
        if v == 0:
            return "0" * n
        if n <= INT_THR:
            parts = []
            for _ in range((n + t - 1) // t):
                v, r = divmod(v, Bt)
                parts.append(T[r])
            parts.reverse()
            return "".join(parts)[-n:]
        m = n // 2
        hi, lo = divmod(v, ipow(m))
        return int_digits(hi, n - m) + int_digits(lo, m)

    dpow_cache = {}

    def dpow(m):
        v = dpow_cache.get(m)
        if v is None:
            v = dpow_cache[m] = ctx.power(Dbase, m)
        return v

    def dec_digits(v, n):
        if v.is_zero():
            return "0" * n
        if n <= DEC_LEAF:
            return int_digits(int(v), n)
        m = n // 2
        hi, lo = ctx.divmod(v, dpow(m))
        return dec_digits(hi, n - m) + dec_digits(lo, m)

    fs = dec_digits(R, k).rstrip("0")
    if fs:
        res += "." + fs
    return sign + res

import re

_PAT = re.compile(r'([+-]?)(?:([0-9]+)(?:\.([0-9]*))?|\.([0-9]+))(?:[eE]([+-]?[0-9]+))?')


def closest_fraction(x: str, max_num: int, max_den: int) -> str:
    if not isinstance(x, str):
        raise ValueError("x must be a string")
    m = _PAT.fullmatch(x)
    if m is None:
        raise ValueError("bad literal")
    if max_num < 0 or max_den < 1:
        raise ValueError("bad bounds")
    sign, ip, fp, fp2, ex = m.groups()
    if ip is None:
        ip, fp = "", fp2
    if fp is None:
        fp = ""
    digits = int(ip + fp)
    scale = (int(ex) if ex else 0) - len(fp)
    if scale >= 0:
        P, Q = digits * 10 ** scale, 1
    else:
        P, Q = digits, 10 ** (-scale)
    neg = sign == '-'
    N, D = max_num, max_den

    def fmt(a, b):
        if a == 0:
            return "0/1"
        return ("-" if neg else "") + "%d/%d" % (a, b)

    # work with |x| = P/Q >= 0
    if P >= N * Q:
        return fmt(N, 1)
    ln, ld = 0, 1
    hn, hd = 1, 0
    while True:
        if P * ld == ln * Q:
            return fmt(ln, ld)
        moved = False
        # move lo toward hi
        c = hn * Q - P * hd  # > 0
        k = (P * ld - ln * Q) // c
        if hn > 0:
            k = min(k, (N - ln) // hn)
        if hd > 0:
            k = min(k, (D - ld) // hd)
        if k > 0:
            ln += k * hn
            ld += k * hd
            moved = True
        if P * ld == ln * Q:
            return fmt(ln, ld)
        # move hi toward lo
        c = hn * Q - P * hd
        e = P * ld - ln * Q  # > 0
        k = (c - 1) // e
        if ln > 0:
            k = min(k, (N - hn) // ln)
        k = min(k, (D - hd) // ld)
        if k > 0:
            hn += k * ln
            hd += k * ld
            moved = True
        if not moved:
            break
    dl = (P * ld - ln * Q) * hd
    dh = (hn * Q - P * hd) * ld
    if dl < dh:
        return fmt(ln, ld)
    if dh < dl:
        return fmt(hn, hd)
    if ld <= hd:
        return fmt(ln, ld)
    return fmt(hn, hd)

import re

_LIT = re.compile(
    r'([+-]?)(?:([0-9]+)(?:\.([0-9]*))?|\.([0-9]+))(?:[eE]([+-]?)([0-9]+))?'
)


def decimal_to_half_bits(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("not a string")
    m = _LIT.fullmatch(s)
    if not m:
        raise ValueError("bad literal")
    sign, ip, fp, fp2, esign, edigits = m.groups()
    if ip is None:
        ip, fp = "", fp2
    elif fp is None:
        fp = ""
    signbit = 0x8000 if sign == "-" else 0

    # exponent
    if edigits is None:
        exp = 0
    else:
        ed = edigits.lstrip("0")
        if len(ed) > 12:
            exp = 10 ** 12
        else:
            exp = int(ed) if ed else 0
        if esign == "-":
            exp = -exp

    d = (ip + fp).lstrip("0")
    if not d:
        return signbit
    e = exp - len(fp)
    order = len(d) + e  # 10**(order-1) <= v < 10**order
    if order > 6:
        return signbit | 0x7C00
    if order < -8:
        return signbit

    if len(d) > 60:
        rest = d[60:]
        e += len(rest)
        d = d[:60]
        if rest.strip("0"):
            d += "1"
            e -= 1

    N = int(d)
    if e >= 0:
        num = N * 10 ** e
        den = 1
    else:
        num = N
        den = 10 ** (-e)

    k = num.bit_length() - den.bit_length()
    if k >= 0:
        ok = num >= (den << k)
    else:
        ok = (num << (-k)) >= den
    if not ok:
        k -= 1

    kk = max(k, -14)
    q = kk - 10
    if q < 0:
        num <<= -q
    else:
        den <<= q
    mq, r = divmod(num, den)
    if 2 * r > den:
        mq += 1
    elif 2 * r == den:
        mq += mq & 1

    bits = (kk + 14) * 1024 + mq
    if bits >= 0x7C00:
        bits = 0x7C00
    return signbit | bits
